const NM={EXP:"Exposição",LIM:"Limitador",INV:"Inalvejável",PROV:"Provocado",ATORD:"Atordoado",REFL:"Reflexo",IMUN:"Imune",INVEST:"Investida",IMORT:"Imortal"},DB=["EXP","PROV","ATORD"];
