function snap(){return JSON.stringify({t:G.t,c:G.cur,ki:G.ki,zk:G.zk,n:G.u.length,sbcd:(G.sbcd||[0,0]).slice(),f:{kz:G.kz,zs:G.zs,zd:G.zd,dr:G.dr,zg:G.zg,kkU:G.kkU||0,dst:G.dst||0,lvki:(G.lvki||[0,0]).slice(),cpsv:(G.cpsv||[0,0]).slice(),kzu:(G.kzu==null?null:G.kzu),zdu:(G.zdu==null?null:G.zdu)},u:G.u.map(x=>({...x,cd:x.cd.slice(),st:x.st.map(y=>({...y,v:typeof y.v=="object"?G.u.indexOf(y.v):y.v}))})),r:G.rep.map(r=>({...r,u:G.u.indexOf(r.u),t:G.u.indexOf(r.t)}))})}
function rs(S){const d=JSON.parse(S);G.t=d.t;G.cur=d.c;G.ki=d.ki;G.zk=d.zk;Object.assign(G,d.f);d.u.forEach((x,i)=>{const o=G.u[i];for(const k in o)if(!(k in x))delete o[k];/* remove campos criados durante a simulação do bot (ex.: free do líder Black) */Object.assign(o,x);G.u[i].st.forEach(y=>{if(y.k=="PROV"||y.k=="SCOUT"||y.k=="TOON")y.v=G.u[y.v]})});G.rep=d.r.map(r=>({...r,u:G.u[r.u],t:G.u[r.t]}));
 /* uma morte durante a simulacao pode ter levantado uma sombra: sem isto ela
    ficaria em G.u depois do rs() e entraria na partida de verdade */
 if(d.n!=null&&G.u.length>d.n)G.u.length=d.n;
 if(d.sbcd)G.sbcd=d.sbcd.slice()}
const SV={REVV:34,TROC:16,JSELO:-8,CDAN:6,INV:30,IMORT:28,ESQ:14,REFL:14,IMUN:12,AURA:10,RAIVA:10,ACEL:18,LIM:8,INVEST:10,ANUL:10,HER:12,DESC:8,ATORD:-34,PARAL:-22,EXP:-14,SOBR:-12,BKI:-14,BCURA:-6,ANTIB:-8,FRAG:-10,DREN:-10,EXAU:-10,SANG:-8,PROV:-8,DESTR:-6,MARC:-6,SCOUT:-4,TOON:-12,CAOS:-6};
const EVK={a:75,m:1.15,s:1.6,k:2,z:4};
function ev(s){const al=[0,1].map(t=>G.u.some(x=>x.s==t&&x.alive&&!semCorpo(x)));if(!al[1-s])return 1e6;if(!al[s])return -1e6;
 let v=EVK.z*(G.zk[s]-G.zk[1-s])+EVK.k*.75*(G.ki[s]-G.ki[1-s]);{/* limite de Energia: Energia que vai transbordar no próximo turno vale menos */const ov=t=>Math.max(0,G.ki[t]+G.u.filter(x=>x.s==t&&x.alive&&!semCorpo(x)).length-KIMAX);v-=EVK.k*.45*(ov(s)-ov(1-s))}
 G.u.forEach(x=>{if(!x.alive||semCorpo(x))return;/* sombra nao tem vida para pesar */const m=x.s==s?1:-EVK.m;let w=x.hp+.8*x.br+1.2*arm(x)+EVK.a;
  if(x.c=="tu"&&!x.rv)w+=Math.min(x.mx,75)+20;if(x.c=="g2"&&!x.rv)w+=x.mx+20;if(x.c=="black"&&!x.im)w+=22;
  if(x.hp<=30)w-=(30-x.hp)*.4;
  if(x.mx<100)w-=(100-x.mx)*.3;/* HP maximo perdido deixa o personagem mais fragil: o bot valoriza devolver */
  if(x.crc)w+=Math.min(100,x.crc)*.25;/* chance de CRITICO acumulada vale como poder de dano */
  if(x.bn)w+=Math.min(40,x.bn)*2.5;/* dano extra permanente tambem e poder guardado: sem isto o bot
    nao via valor nenhum em acumular (Gohan Beast, Goku Instinto) nem em invocar o Igris */
  x.st.forEach(y=>{const b=SV[y.k];if(!b)return;w+=EVK.s*b*(y.t>=2&&y.t<99?1.25:1)});
  G.rep.forEach(r=>{if(r.t===x&&r.u.alive)w-=(r.v||15)*(r.fx?2:Math.min(r.n,2))*.8});
  if(x.c=="tu"&&!x.rv){const B=G.u.find(b=>b.c=="beast"&&b.alive&&b.s!=x.s);if(B&&B.cd[3]<=1&&G.zk[B.s]>=cz(B,C.beast.sk[3]))w-=has(x,"EXP")?45:15}
  v+=m*w});return v}
function opts(u){const r=[];C[u.c].sk.forEach((k,i)=>{if(!ok(u,i))return;if(k.tg=="S"||tgu(k,u)=="E")r.push({u,i});else if(k.tg=="2"){const f=tgts(u,k);if(f.length<2)r.push({u,i,ts:f});else f.forEach((a,x)=>f.slice(x+1).forEach(b=>r.push({u,i,ts:[a,b]})))}else if(k.vz){const m=u.free?(k.vzm||4):Math.min(k.vzm||4,G.zk[u.s]-spent()[1]);tgts(u,k).forEach(t=>{for(let z=1;z<=m;z++)r.push({u,i,t,z})})}else tgts(u,k).forEach(t=>r.push({u,i,t}))});if(G.lead[u.s]=="gbk"&&u.hp>45)r.slice().forEach(a=>{if(kkDmg(C[u.c].sk[a.i]))r.push(Object.assign({},a,{kk:1}))});return r}
function adv(){G.t++;const s=G.cur,n=1-s;G.u.filter(x=>x.s==s).forEach(x=>{x.nxp=x.nx||0});G.u.filter(x=>x.s==s).forEach(x=>{x.st.forEach(y=>{if(y.f)y.f=0;else y.t--});brExp(x);x.st=x.st.filter(y=>y.t>0)});G.cur=n;const m=G.u.filter(x=>x.s==n&&x.alive);G.ki[n]=Math.min(KIMAX,G.ki[n]+m.length);if(G.zg[n]<zgMax(n))G.zk[n]++;/* o limite segue o do jogo (7, ou 9 com o lider Gogeta) */G.u.forEach(x=>{x.rec=0;x.aru=0});m.forEach(x=>x.cd=x.cd.map(c=>Math.max(0,c-1)))}
function greedy(s){G.cur=s;G.q=[];G.u.filter(x=>x.s==s&&x.alive).flatMap(x=>has(x,"ACEL")?[x,x]:[x]).forEach(u=>{let b=null,S=snap();run();let bv=ev(s);rs(S);
  opts(u).forEach(a=>{const S2=snap();G.q.push(a);run();const v=ev(s);rs(S2);G.q.pop();if(v>bv){bv=v;b=a}});if(b)G.q.push(b)});return G.q.slice()}
function best1(P,lim){G.cur=P;G.q=[];const us=G.u.filter(x=>x.s==P&&x.alive).flatMap(x=>has(x,"ACEL")?[x,x]:[x]),L=[];let n=0;
 const dfs=k=>{if(n>lim)return;if(k==us.length){n++;const q=G.q.slice(),S=snap();run();L.push({q,v:ev(P)});rs(S);return}dfs(k+1);opts(us[k]).forEach(a=>{G.q.push(a);dfs(k+1);G.q.pop()})};
 dfs(0);L.sort((a,b)=>b.v-a.v);return L}
function perms(a){if(a.length<2)return[a];const r=[];a.forEach((x,i)=>perms(a.slice(0,i).concat(a.slice(i+1))).forEach(p=>r.push([x].concat(p))));return r}

