function resChips(s){if(fogRes(s))return"<span class='rsc'><span class='rsk'>"+ICK()+" <b>?</b> Energia</span><span class='rsz'>"+ICZ()+" <b>?</b> Essência</span></span>";return"<span class='rsc'><span class='rsk'>"+ICK()+" <b>"+G.ki[s]+"</b><small>/"+KIMAX+"</small> Energia"+resDelta(s,"ki")+"</span><span class='rsz'>"+ICZ()+" <b>"+G.zk[s]+"</b> Essência"+resDelta(s,"zk")+"<small class='rszg' title='Essência já gerada na partida (máximo "+zgMax(s)+")'>gerado "+G.zg[s]+"/"+zgMax(s)+"</small></span></span>"}
