function turnAnn(){const R=G._rs;if(!R||!R.nt||G.sim||G.win!=null||G.scr!="p")return;R.nt=0;if(G.t<=1)return;const s=G.cur;let mine=G.online?(G.me>=0&&s===G.me):G.bot?s===0:true;if(!mine)return;
 const d=R.dl&&R.dl.s===s?R.dl:null,sub=d?[d.dk?(d.dk>0?"+":"")+d.dk+" Energia":"",d.dz?(d.dz>0?"+":"")+d.dz+" Essência":""].filter(Boolean).join(" · "):"";
 PANN.yt=[G.online||G.bot?"Sua Vez!":"Vez do Jogador "+(s+1),sub];const wait=Math.max(0,(G.holdT||0)-Date.now());setTimeout(()=>{if(G.cur===s&&G.win==null&&G.scr=="p")phaseAnn("yt",1)},wait+150)}

