/* ===== Nivel da Conta: EXP em toda partida, de todos os modos, sem limite =====
   Do nivel N para o N+1 sao 100 + 25 x (N-1) de EXP. Fica em za_conta (vai junto
   com a conta). g: as ultimas partidas ja pagas, para nenhuma pagar duas vezes. */
const CTCFG={vit:275,der:195,ecos:5,rank:10};
const ctPasso=n=>100+25*(n-1);                    /* EXP do nivel n para o n+1 */
const ctTotal=n=>100*(n-1)+25*(n-1)*(n-2)/2;      /* EXP total para ESTAR no nivel n */
function ctProg(xp){xp=Math.max(0,Math.floor(+xp||0));let n=1;while(xp>=ctTotal(n+1))n++;
 const base=ctTotal(n),passo=ctPasso(n);return{n,xp,no:xp-base,passo,frac:(xp-base)/passo}}
function ctLer(){let c=null;try{c=JSON.parse(ls("za_conta")||"null")}catch(e){c=null}
 if(!c||typeof c!="object")c={};if(typeof c.xp!="number"||!isFinite(c.xp))c.xp=0;if(!Array.isArray(c.g))c.g=[];return c}
function ctGrava(c){try{ls("za_conta",JSON.stringify(c))}catch(e){}}
const ctNivel=()=>ctProg(ctLer().xp).n;
/* o que libera em cada nivel */
const CTDESB={5:"Aba Ecos e Fila Casual",10:"Fila Ranqueada"};
const ctLiberado=o=>ctNivel()>=(o=="ecos"?CTCFG.ecos:CTCFG.rank);
function ctDesbEntre(a,b){const L=[];Object.keys(CTDESB).map(Number).sort((x,y)=>x-y).forEach(n=>{if(n>a&&n<=b)L.push(CTDESB[n])});return L}
/* paga uma partida: devolve antes, depois, ganho e o que desbloqueou (ou nada, se ja foi paga) */
function ctCredita(gid,venceu){if(!gid)return null;const c=ctLer();if(c.g.indexOf(gid)>=0)return null;
 c.g.push(gid);if(c.g.length>200)c.g=c.g.slice(-200);
 const antes=ctProg(c.xp),ganho=venceu?CTCFG.vit:CTCFG.der;c.xp=antes.xp+ganho;ctGrava(c);
 const depois=ctProg(c.xp);return{antes,depois,ganho,desb:ctDesbEntre(antes.n,depois.n)}}
/* fim da partida: de quem e o resultado. Tutorial, simulacao e quem so assiste nao ganham.
   No mesmo aparelho (treino a dois) vale o lado esquerdo, que e sempre o do jogador. */
function ctFim(){if(G.sim||G.tutp||G.win==null)return null;
 const me=G.online?(G.me>=0?G.me:null):0;if(me==null)return null;
 /* online a chave e sempre a da partida (gid): quem nao e o dono da sala nunca passa
    pelo newGame, entao a chave da partida anterior nao pode ficar valendo */
 if(G.online&&G.gid&&G._ctk!=="o:"+G.gid&&G._ctk!==G._prk){G._ctk=null;G._ctr=null;G._ctAnim=0}
 if(!G._ctk)G._ctk=G._prk||((G.online&&G.gid)?"o:"+G.gid:"l:"+Date.now().toString(36)+Math.random().toString(36).slice(2,7));
 const r=ctCredita(G._ctk,G.win===me);if(r){G._ctr=r;try{pfPublica()}catch(e){}}
 try{prgFimPartida(me)}catch(e){}
 return G._ctr||null}
/* o bloco da EXP na tela de fim: a barra enche do que era ate o que ficou */
function ctBloco(r){const b=mk("div","ctfim");if(!r)return b;
 const p0=r.antes,p1=r.depois,txt=p=>fnum(p.no)+" / "+fnum(p.passo)+" EXP";
 b.innerHTML="<div class='ctl'><b>Nível <span>"+p0.n+"</span></b><em>+"+fnum(r.ganho)+" EXP</em></div>"+
  "<div class='ctbar'><i style='width:"+(p0.frac*100).toFixed(1)+"%'></i></div><small>"+txt(p0)+"</small><div class='ctup' hidden></div>";
 const bar=b.querySelector(".ctbar i"),nv=b.querySelector(".ctl span"),sm=b.querySelector("small"),up=b.querySelector(".ctup");
 const fim=()=>{nv.textContent=p1.n;sm.textContent=txt(p1);bar.style.transition="none";bar.style.width=(p1.frac*100).toFixed(1)+"%";
  if(p1.n>p0.n){up.hidden=false;up.innerHTML="<b>Subiu para o nível "+p1.n+"!</b>"+r.desb.map(d=>"<span>Desbloqueado: "+escH(d)+"</span>").join("")}};
 if(G._ctAnim){fim();return b}G._ctAnim=1;
 const sobe=p1.n-p0.n;
 setTimeout(()=>{if(!sobe){bar.style.width=(p1.frac*100).toFixed(1)+"%";setTimeout(fim,900);return}
  bar.style.width="100%";setTimeout(()=>{bar.style.transition="none";bar.style.width="0%";nv.textContent=p1.n;
   void bar.offsetWidth;bar.style.transition="";bar.style.width=(p1.frac*100).toFixed(1)+"%";setTimeout(fim,900)},800)},350);
 return b}
/* perfil: fundo, estandarte e moldura padrao (artes do jogo) */
Object.assign(IMG,{pf_bg:"data:image/webp;base64,",pf_ban:"data:image/webp;base64,",pf_mold:"data:image/webp;base64,"});
/* ===== Perfil do jogador =====
   za_perfil: o que o jogador equipou (icone, titulo, moldura e fundo). Tudo vem da
   Maestria: icone no 2, titulos no 4/8/10, fundo no 7 (de cada personagem) e as
   molduras gerais (bronze no 5, prata no 7, dourada no 10, com qualquer personagem). */
/* ===== Molduras, bandeiras e fundos de presente (comemoracao do Perfil): liberados para todos =====
   Todas as molduras (a padrao tambem) foram medidas e refeitas no mesmo padrao: o buraco fica no centro
   da arte e sempre do mesmo tamanho, entao o icone encaixa igual em qualquer uma.
   Todas as bandeiras tem a mesma forma (2:3). my: a altura do medalhao de cada uma (fracao da altura);
   sem medalhao, vale a posicao da bandeira padrao. */
Object.assign(IMG,{"pfm_roxa": "data:image/webp;base64,", "pfb_roxa": "data:image/webp;base64,", "pfm_floresta": "data:image/webp;base64,", "pfb_floresta": "data:image/webp;base64,", "pfm_magma": "data:image/webp;base64,", "pfb_magma": "data:image/webp;base64,", "pfm_natal": "data:image/webp;base64,", "pfb_natal": "data:image/webp;base64,", "pfm_praia": "data:image/webp;base64,", "pfb_praia": "data:image/webp;base64,", "pfm_lua": "data:image/webp;base64,", "pfb_lua": "data:image/webp;base64,", "pfm_gelo": "data:image/webp;base64,", "pfb_gelo": "data:image/webp;base64,", "pfm_aurora": "data:image/webp;base64,", "pfb_aurora": "data:image/webp;base64,", "pff_praia": "/_blob/5bc5e67ec0b40d11a58b37fa0d683a4c", "pff_santuario": "/_blob/7434e310c870d2171a590038b8185448", "pff_aurora": "/_blob/35b3d450ae56c8e2cb6913d37580cfa5", "pff_eclipse": "/_blob/fb21461ea83f7123d86552e9ea586b5d", "pff_floresta": "/_blob/80c58755146e326b99309b8b94d37391", "pff_gelo": "/_blob/270b39a9587bc2ee069d05bb7fd81877", "pff_magma": "/_blob/edfc97d78ee61394c14a6ffb320a4959", "pff_natal": "/_blob/a859aa31468de04509c325ebef4da595"});
const PFTEMA={"roxa": {"n": "Violeta"}, "floresta": {"n": "Floresta", "my": 0.2600}, "magma": {"n": "Magma", "my": 0.4492}, "natal": {"n": "Natal", "my": 0.4232}, "praia": {"n": "Maré", "my": 0.4167}, "lua": {"n": "Lua Roxa", "my": 0.3385}, "gelo": {"n": "Gelo", "my": 0.3646}, "aurora": {"n": "Aurora", "my": 0.2767}};
const PFFUNDO=[["bg_praia", "Praia de Cristal"], ["bg_santuario", "Santuário"], ["bg_aurora", "Aurora Boreal"], ["bg_eclipse", "Eclipse"], ["bg_floresta", "Jardim de Jade"], ["bg_gelo", "Palácio de Gelo"], ["bg_magma", "Fortaleza de Magma"], ["bg_natal", "Natal 2026"]];
const pfFuImg=f=>f&&f.indexOf("bg_")===0&&IMG["pff_"+f.slice(3)]?IMG["pff_"+f.slice(3)]:null;
const pfFuOk=f=>!f||(C[f]?1:!!pfFuImg(f));
const PFDEF={ic:"",ti:"",mo:"pad",fu:"",ba:""};
/* o nome que aparece: o nick escolhido; sem nick ainda, so mostra (nao grava nada) */
const pfNick=()=>{try{return String(ls("za_nick")||"").trim()||"Jogador"}catch(e){return "Jogador"}};
const PFMOLD=[["pad","Padrão",0],["bronze","Bronze",5],["prata","Prata",7],["ouro","Dourada",10]].concat(Object.keys(PFTEMA).map(k=>[k,PFTEMA[k].n,0,1]));
const pfRos=()=>ROS.filter(k=>C[k]);
const mxMaiorNv=()=>pfRos().reduce((a,k)=>Math.max(a,mxNivelDe(k)),0);
function pfLer(){let p=null;try{p=JSON.parse(ls("za_perfil")||"null")}catch(e){p=null}
 if(!p||typeof p!="object")p={};return Object.assign({},PFDEF,p)}
/* o que esta equipado e nao esta mais liberado (outro aparelho, regra mudou) volta para o padrao */
function pfVal(p){p=Object.assign({},PFDEF,p||{});
 if(p.ic&&!(C[p.ic]&&mxNivelDe(p.ic)>=2))p.ic="";
 if(p.ti){const [k,n]=String(p.ti).split(":");if(!(C[k]&&MXTIT[n]&&mxNivelDe(k)>=+n))p.ti=""}
 const m=PFMOLD.find(x=>x[0]==p.mo);if(!m||mxMaiorNv()<m[2])p.mo="pad";
 if(p.fu&&!(pfFuImg(p.fu)||(C[p.fu]&&mxNivelDe(p.fu)>=7)))p.fu="";
 if(p.ba&&!PFTEMA[p.ba])p.ba="";
 return p}
function pfGrava(p){p=pfVal(p);ls("za_perfil",JSON.stringify({ic:p.ic,ti:p.ti,mo:p.mo,fu:p.fu,ba:p.ba}));
 try{if(typeof pfPublica=="function")pfPublica()}catch(e){}}
const pfTitTxt=ti=>{if(!ti)return"";const [k,n]=String(ti).split(":");return C[k]?mxTitulo(k,+n):""};
const pfIcSrc=ic=>ic&&IMG[ic+"_f"]?IMG[ic+"_f"]:IMG.ui_marca;
/* moldura da maestria de um personagem: a mesma escada das molduras gerais */
const pfMoNv=n=>n>=10?"ouro":n>=7?"prata":n>=5?"bronze":"pad";
/* o icone dentro da moldura: uma peca so, igual em todo lugar (so muda a largura de .pfav).
   O icone e um circulo que preenche o buraco; a moldura vai por cima e os enfeites passam da caixa.
   As medidas ficam no proprio elemento para nenhuma regra de tela mudar o encaixe. */
const PFK=1.2956,PFBAN_Y=.2438;
const PFAVI="position:absolute!important;left:7.4%!important;top:7.4%!important;width:85.2%!important;height:85.2%!important;margin:0!important;border:0!important;border-radius:50%!important;max-width:none!important;max-height:none!important;box-shadow:none!important";
const PFAVM="position:absolute!important;inset:auto!important;left:"+(-(PFK-1)/2*100).toFixed(2)+"%!important;top:"+(-(PFK-1)/2*100).toFixed(2)+"%!important;width:"+(PFK*100).toFixed(2)+"%!important;height:"+(PFK*100).toFixed(2)+"%!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;max-width:none!important;max-height:none!important;box-shadow:none!important";
const pfMoSrc=mo=>PFTEMA[mo]?IMG["pfm_"+mo]:IMG.pf_mold;
function pfAv(ic,mo,cls){mo=PFTEMA[mo]||PFMOLD.some(x=>x[0]==mo)?mo:"pad";
 return "<span class='pfav mo-"+mo+(ic?"":" pfdef")+(cls?" "+cls:"")+"'><img class='pfavi' src='"+pfIcSrc(ic)+"' alt='' style='"+PFAVI+"'><img class='pfavm' src='"+pfMoSrc(mo)+"' alt='' style='"+PFAVM+"'></span>"}
/* moldura vazia (lugar ainda sem personagem) */
const pfAvVazio=()=>"<span class='pfav pfvz'><img class='pfavm' src='"+IMG.pf_mold+"' alt='' style='"+PFAVM+"'></span>";
/* a bandeira: o icone vai no medalhao dela; nome, titulo, nivel e EXP ficam no mesmo lugar em todas */
const pfBanSrc=ba=>PFTEMA[ba]?IMG["pfb_"+ba]:IMG.pf_ban;
const pfBanY=ba=>(PFTEMA[ba]&&PFTEMA[ba].my)||PFBAN_Y;
/* os 3 personagens com mais pontos de Maestria */
function pfTop(){return pfRos().map(k=>{const r=mxDe(k);return[k,r.pt||0,mxNivelInfDe(k)]}).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,3)}
function pfPos(){try{const L=rkTopLista(),i=L.findIndex(x=>x.eu);return i>=0?i+1:0}catch(e){return 0}}
/* os dados que a tela desenha: os meus (deste aparelho) ou os de um amigo */
function pfMeu(){const p=pfVal(pfLer()),P=ctProg(ctLer().xp);let st=null;try{st=rkLoad()}catch(e){}
 return{nick:pfNick(),ic:p.ic,ti:p.ti,tit:pfTitTxt(p.ti),mo:p.mo,fu:p.fu,ba:p.ba,nv:P.n,no:P.no,passo:P.passo,
  rk:st&&st.n?{rank:st.rank,div:st.div,pc:st.pc,pos:pfPos()}:null,top:pfTop()}}

let PFED=null,PFTAB="ic";
/* tudo o que existe numa aba, liberado ou nao, com o jeito de liberar */
function pfItens(tab){const R=pfRos();
 if(tab=="ic")return[{id:"",n:"Ânima",ok:1,img:IMG.ui_marca,def:1}].concat(R.map(k=>({id:k,n:shn(k),ok:mxNivelDe(k)>=2,req:"Maestria 2 com "+shn(k),img:IMG[k+"_f"]})));
 if(tab=="ti"){const L=[{id:"",n:"Sem título",ok:1}];R.forEach(k=>[4,8,10].forEach(n=>L.push({id:k+":"+n,n:mxTitulo(k,n),ok:mxNivelDe(k)>=n,req:"Maestria "+n+" com "+shn(k)})));return L}
 if(tab=="mo"){const mx=mxMaiorNv();const L=PFMOLD.map(([id,n,nv,pr])=>({id,n,ok:mx>=nv,pr,req:"Maestria "+nv+" com qualquer personagem"}));return[L[0]].concat(L.filter(x=>x.pr),L.slice(1).filter(x=>!x.pr))}
 if(tab=="ba")return[{id:"",n:"Padrão",ok:1,img:pfBanSrc("")}].concat(Object.keys(PFTEMA).map(k=>({id:k,n:PFTEMA[k].n,ok:1,pr:1,img:pfBanSrc(k)})));
 return[{id:"",n:"Padrão",ok:1,img:IMG.pf_bg,def:1}].concat(PFFUNDO.map(([id,n])=>({id,n,ok:1,pr:1,img:pfFuImg(id)})),R.map(k=>({id:k,n:shn(k),ok:mxNivelDe(k)>=7,req:"Maestria 7 com "+shn(k),img:IMG[k+"_s"]})))}
const PFABAS=[["ic","Ícone"],["ti","Título"],["mo","Moldura"],["ba","Bandeira"],["fu","Fundo"]];

/* a tela. V: os dados de outro jogador (so para ver); sem V, o meu perfil */
function showPerfil(V,op){op=op||{};const ed=!!op.ed&&!V;
 if(ed&&!PFED)PFED=pfVal(pfLer());if(!ed)PFED=null;
 const D=V||pfMeu();if(ed)Object.assign(D,PFED,{tit:pfTitTxt(PFED.ti)});
 const se=document.scrollingElement,y0=op.keep&&se?se.scrollTop:0;
 pannOff(1);dClear();G.scr="pf";document.body.classList.remove("bt");document.body.classList.add("dm");
 const r=$("#dr");r.innerHTML="";
 const w=mk("div","pf"+(ed?" ed":"")+(V?" vis":""));
 const sp=D.fu&&IMG[D.fu+"_s"];
 w.innerHTML="<div class='pfbg' style=\"background-image:url('"+(pfFuImg(D.fu)||IMG.pf_bg)+"')\"></div>"+(sp?"<div class='pfsp'><img src='"+sp+"' alt=''></div>":"")+"<div class='pfdim'></div>";
 /* topo: Voltar, a marca do Anima e Personalizar */
 const top=mk("div","pftop");
 const vt=mk("button","pfbt pfvt","<span>←</span> Voltar");vt.onclick=()=>{if(ed){PFED=null;return showPerfil()}if(op.volta)return op.volta();showMenu()};
 top.append(vt,mk("div","pflogo","<img src='"+IMG.ui_marca+"' alt=''><b>PROJETO ÂNIMA</b>"));
 if(!V&&!ed){const pz=mk("button","pfbt pfpz","Personalizar");pz.onclick=()=>showPerfil(null,{ed:1});top.append(pz)}
 else top.append(mk("span","pfsp0"));
 w.append(top);
 /* o estandarte */
 const meio=mk("div","pfmeio");
 const ban=mk("div","pfban");ban.style.backgroundImage="url('"+pfBanSrc(D.ba)+"')";
 ban.innerHTML="<div class='pfbm' style='top:"+(pfBanY(D.ba)*100).toFixed(2)+"%'>"+pfAv(D.ic,D.mo,"pfbav")+"</div><div class='pfbc'><b class='pfnm'>"+escH(D.nick||"Jogador")+"</b>"
  +(D.tit?"<i class='pfti'>"+escH(D.tit)+"</i>":"")
  +(D.nv?"<span class='pfnv'>Nível "+fnum(D.nv)+"</span>":"")
  +(D.passo?"<div class='pfxp'><i style='width:"+(100*Math.min(1,(D.no||0)/D.passo)).toFixed(1)+"%'></i><small class='pfxt'>"+fnum(D.no||0)+" / "+fnum(D.passo)+" EXP</small></div>":"")+"</div>";
 meio.append(ban);
 const lado=mk("div","pflado");
 lado.append(mk("h1","pfh",ed?"Personalizar perfil":V?"Perfil de "+escH(D.nick||"jogador"):"Perfil do jogador"));
 if(ed)lado.append(pfEditor());
 meio.append(lado);w.append(meio);
 /* faixa de baixo: ranqueada e maiores maestrias */
 if(!ed){const bt=mk("div","pfbot");
  const rk=mk("div","pfrk");
  if(D.rk){const st={rank:D.rk.rank||1,div:D.rk.div||5,pc:D.rk.pc==null?null:D.rk.pc};
   rk.innerHTML="<h3>Ranqueada</h3><div class='pfrkb'>"+rkMedalha(st)+"<div><b>"+escH(rkNome(st))+"</b>"+(D.rk.pos?"<small>#"+fnum(D.rk.pos)+" no ranking</small>":"")+"</div></div>"}
  else rk.innerHTML="<h3>Ranqueada</h3><div class='pfrkb'><div><b>Sem classificação</b><small>Ainda não jogou a Fila Ranqueada</small></div></div>";
  const mx=mk("div","pfmx");mx.append(mk("h3","","Maiores maestrias"));
  const row=mk("div","pfmxr"),T=D.top||[];
  for(let i=0;i<3;i++){const t=T[i];
   row.append(mk("div","pfmxi"+(t?"":" vz"),t&&C[t[0]]
    ?pfAv(t[0],pfMoNv(t[2]),"pfmxa")+"<b>"+escH(shn(t[0]))+"</b><small>"+fnum(t[1])+" pts</small><small>Maestria "+t[2]+"</small>"
    :pfAvVazio()+"<small>Jogue para desbloquear</small>"))}
  mx.append(row);bt.append(rk,mx);w.append(bt)}
 r.append(w);zHud();
 try{if(se)se.scrollTop=op.keep?y0:0}catch(e){}
 /* a posicao no ranking chega depois da classificacao carregar */
 if(!V&&!ed&&D.rk&&!D.rk.pos){try{rkBuscaTop()}catch(e){}setTimeout(()=>{if(G.scr=="pf"&&!PFED&&pfPos())showPerfil()},2500)}
 return w}

/* o painel de abas da edicao */
function pfEditor(){const p=mk("div","pfed");
 const tb=mk("div","pftabs");
 PFABAS.forEach(([k,t])=>{const b=mk("button","pftab"+(PFTAB==k?" on":""),t);b.onclick=()=>{PFTAB=k;showPerfil(null,{ed:1,keep:1})};tb.append(b)});
 const hd=mk("div","pfedh");hd.append(tb);p.append(hd);
 const L=pfItens(PFTAB),cur=PFED[PFTAB],g=mk("div","pfgr t-"+PFTAB);
 L.forEach(it=>{const on=it.id===cur;
  let h;
  if(PFTAB=="ic")h="<span class='pfth'>"+pfAv(it.id,PFED.mo,"pfgi")+"</span>";
  else if(PFTAB=="mo")h="<span class='pfth'>"+pfAv(PFED.ic,it.id,"pfgi")+"</span>";
  else if(PFTAB=="fu")h="<span class='pfth pffu'><img src='"+it.img+"' alt=''></span>";
  else if(PFTAB=="ba")h="<span class='pfth pfbaim' style=\"background-image:url('"+it.img+"')\"></span>";
  else h="";
  const b=mk("button","pfit"+(on?" on":"")+(it.ok?"":" lk"),h+"<b>"+(it.ok?"":"<i class='mmcad' aria-hidden='true'>🔒</i>")+escH(it.n)+"</b>"+(PFTAB=="ti"?(it.pr?"<small class='pfpres'>Presente</small>":"")+(it.ok?"":"<small>"+escH(it.req)+"</small>"):"<span class='pfetq'>"+(it.pr?"<small class='pfpres'>Presente</small>":"")+(it.ok?"":"<small>"+escH(it.req)+"</small>")+"</span>"));
  b.title=it.ok?(it.pr?it.n+" · presente de comemoração do Perfil, liberado para todos":it.n):it.req;
  b.onclick=()=>{if(!it.ok)return zToast(it.req);PFED[PFTAB]=it.id;showPerfil(null,{ed:1,keep:1})};
  g.append(b)});
 p.append(g);
 const ft=mk("div","pfft");
 const cc=mk("button","pfbt pfcc","Cancelar");cc.onclick=()=>{PFED=null;showPerfil()};
 const sv=mk("button","pfbt pfsv","Salvar");sv.onclick=()=>{pfGrava(PFED);PFED=null;zToast("Perfil salvo");showPerfil()};
 ft.append(cc,sv);hd.append(ft);
 return p}

/* ===== Perfil fora da tela de perfil: ao lado do nome, na lista de amigos e no perfil do amigo ===== */
/* o resumo que vai junto do nome: icone, titulo (o id), moldura e nivel */
function pfMini(){const p=pfVal(pfLer());return{ic:p.ic,ti:p.ti,mo:p.mo,nv:ctNivel()}}
/* o pacote inteiro, para quem abrir o meu perfil */
function pfPacote(){const D=pfMeu();return{ic:D.ic,ti:D.ti,mo:D.mo,fu:D.fu,ba:D.ba,nv:D.nv,no:D.no,passo:D.passo,rk:D.rk,top:D.top,mx:(()=>{try{return mxPacote()}catch(e){return{}}})(),at:Date.now()}}
/* o que chega de outra conta: so o que o jogo conhece passa */
function pfLimpa(p,nick){p=p&&typeof p=="object"?p:{};const o={nick:String(nick||"Jogador").slice(0,24)};
 o.ic=C[p.ic]?p.ic:"";o.mo=PFMOLD.some(x=>x[0]==p.mo)?p.mo:"pad";o.fu=(C[p.fu]||pfFuImg(p.fu))?p.fu:"";o.ba=PFTEMA[p.ba]?p.ba:"";
 o.ti=typeof p.ti=="string"&&pfTitTxt(p.ti)?p.ti:"";o.tit=pfTitTxt(o.ti);
 o.nv=+p.nv>0?Math.max(1,Math.floor(+p.nv)):null;
 if(+p.passo>0){o.no=Math.max(0,Math.floor(+p.no||0));o.passo=Math.floor(+p.passo)}
 if(p.rk&&typeof p.rk=="object")o.rk={rank:Math.min(RKCFG.ranks,Math.max(1,+p.rk.rank||1)),div:Math.max(1,+p.rk.div||5),pc:p.rk.pc==null?null:+p.rk.pc,pos:Math.max(0,+p.rk.pos||0)};else o.rk=null;
 o.top=Array.isArray(p.top)?p.top.filter(t=>Array.isArray(t)&&C[t[0]]).slice(0,3).map(t=>[t[0],Math.max(0,+t[1]||0),Math.max(1,+t[2]||1)]):[];
 return o}
/* os adversarios da populacao da ranqueada tambem tem perfil: sai das mesmas partidas
   que dao a maestria deles. Mesmo adversario, mesmo perfil, em qualquer aparelho. */
function pfBot(){try{if(!rkEmJogo())return null;
 if(G.csm){const id="c"+String(G.rkNome||""),p=pfDeConta(id,8+Math.floor(rkH(rkSH(id),3,9)*30),.5,rkBotMx);if(p)p.nv=5+Math.floor(rkH(rkSH("cs|"+id),1,1)*14);return p}
 const m=G.rkm||{},id=m.pop!=null?"p"+m.pop:"n"+String(G.rkNome||m.oppNome||"");
 let n=0,wr=.5;if(m.pop!=null){const s=rkPopLoad().st[m.pop];if(s){n=(s.w||0)+(s.l||0);wr=n?(s.w||0)/n:.5}}else n=40+Math.floor(rkH(rkSH(id),3,9)*160);
 return pfDeConta(id,n,wr,rkBotMx)}catch(e){return null}}
/* o resumo de cada lado da partida (draft e batalha) */
function pfEuLado(){try{if(G.online)return mxEuLado();
 if(typeof D!="undefined"&&D&&D.on)return D.spec?2:O.seat;
 return 0}catch(e){return 0}}
function pfDoLado(s){try{
 const on=G.online||(typeof D!="undefined"&&D&&D.on);
 if(!on){if(s===0&&(G.bot||rkEmJogo()))return pfMini();if(s===1&&rkEmJogo())return pfBot()||pfLimpa(null);return null}
 if(s===pfEuLado())return pfMini();
 const d=(typeof O!=="undefined"&&O&&O.d)||null,pid=d&&d["p"+s],m=pid&&d.mem&&d.mem[okey(pid)];
 if(!pid)return null;if(!m||!m.pf)return pfLimpa(null,m&&m.n);return pfLimpa(m.pf,m.n)}catch(e){return null}}
/* icone na moldura + nivel e titulo, para ir ao lado do nome */
function pfChip(p){if(!p)return"";const t=pfTitTxt(p.ti);
 return"<span class='pfch'>"+pfAv(p.ic,p.mo,"pfcha")+"</span>"}
function pfInfo(p){if(!p)return"";const t=pfTitTxt(p.ti);
 return"<span class='pfci'>"+(p.nv?"<i class='pfcn'>Nv "+fnum(p.nv)+"</i>":"")+(t?"<em class='pfct'>"+escH(t)+"</em>":"")+"</span>"}
/* publica o meu perfil (players/<pid>) e o resumo na presenca */
let PFPUB=0;
function pfPublica(){try{if(typeof FR=="undefined"||!FR.pronto||!FR.pid||!FR.code)return;const db=frDb();if(!db)return;
 clearTimeout(PFPUB);PFPUB=setTimeout(()=>{db.doc("players/"+FR.pid).set({n:frNick(),code:FR.code,at:Date.now(),pf:pfPacote()}).catch(()=>{});try{frPres()}catch(e){}},600)}catch(e){}}
/* abre o perfil de um amigo (so para ver) */
async function pfAmigo(id,nome){
 if(G.scr=="p"||G.scr=="d")return zToast("Abra o perfil de "+nome+" fora da partida.");
 let pf=null;try{const sn=await frDb().doc("players/"+id).get();const d=sn&&sn.exists?sn.data():null;pf=d&&d.pf;if(d&&d.n)nome=d.n}catch(e){}
 if(!pf){const p=FR.pres[id];pf=p&&p.pf}
 const volta=G.scr=="pf"?showMenu:(()=>{const f=G.scr=="inv"?showInv:G.scr=="lb"?showLobby:showMenu;return()=>f()})();
 showPerfil(pfLimpa(pf,nome),{volta})}

/* ===== Maestria depois do 10: niveis sem limite =====
   Depois do 10 (com o desafio final concluido), cada nivel pede 250 pontos a mais
   que o anterior: 10->11 2.450, 11->12 2.700, 12->13 2.950... As recompensas ficam no 10. */
const MXPOS0=2450,MXPOSD=250;
function mxProgInf(pt,dn){pt=Math.max(0,+pt||0);const n=mxNivel(pt,dn);
 if(n<MXMAX)return{n,inf:0};
 let x=pt-MXAC[MXMAX-1],k=MXMAX,p=MXPOS0;while(x>=p){x-=p;k++;p+=MXPOSD}
 return{n:k,inf:1,no:x,passo:p}}
const mxNivelInf=(pt,dn)=>mxProgInf(pt,dn).n;
const mxNivelInfDe=k=>{const r=mxDe(k);return mxNivelInf(r.pt,mxDestNv(r))};

/* a maestria de uma conta da populacao da ranqueada, pelas partidas da temporada */
function rkMxCalc(id,n,wr,k){const sea=rkSeasonId(),sd=rkSH("mx|"+sea+"|"+id),L=ROS.filter(x=>C[x]);
 const pe=L.map((x,i)=>{const h=rkH(sd,i,5);return .25+7*Math.pow(h,4)}),tot=pe.reduce((a,b)=>a+b,0);
 const i=L.indexOf(k);if(i<0)return {pt:0,d:0,dn:0};
 const jg=3*n*pe[i]/tot,vit=jg*wr,der=jg-vit;
 const mvp=Math.floor(vit*(.16+.12*rkH(sd,i,11))),svp=Math.floor(der*(.10+.10*rkH(sd,i,13)));
 const pt=Math.round(vit*MXCFG.vit+der*MXCFG.der+mvp*MXCFG.mvp+svp*MXCFG.svp),lim=MXAC[MXMAX-1];
 const dn=pt>lim?Math.floor((mvp+svp)*(pt-lim)/pt):0;
 return {pt,d:mvp+svp,dn}}
/* o perfil de uma conta da populacao (mesma regra do adversario da partida) */
function pfDeConta(id,n,wr,mxDe){const sd=rkSH("pf|"+id);
 const fora=Math.floor(n*(.4+1.6*rkH(sd,1,3)));
 let xp=Math.floor(n*wr*CTCFG.vit+n*(1-wr)*CTCFG.der+fora*(CTCFG.vit+CTCFG.der)/2);
 xp=Math.max(xp,ctTotal(CTCFG.rank)+Math.floor(rkH(sd,2,5)*3000));
 const L=pfRos().map(k=>{const r=mxDe(k)||{pt:0,dn:0};return[k,r.pt||0,mxNivel(r.pt||0,r.dn||0)]}).sort((a,b)=>b[1]-a[1]);
 const top=L[0]||["",0,1],mx=top[2];
 const ic=mx>=2&&rkH(sd,3,7)<.85?top[0]:"";
 const tn=[10,8,4].find(t=>mx>=t);const ti=tn&&rkH(sd,4,7)<.7?top[0]+":"+tn:"";
 const mo=rkH(sd,5,7)<.75?pfMoNv(L.reduce((a,x)=>Math.max(a,x[2]),0)):"pad";
 return{ic,ti,mo,nv:ctProg(xp).n}}

/* ===== Rank de Maestria: os mestres de cada personagem ===== */
const MXRK={lista:null,at:0,em:0,k:""};
async function mxRankBusca(f){const db=(typeof frDb=="function"&&frDb())||(typeof O!="undefined"&&O.db);
 if(!db||MXRK.em||(!f&&Date.now()-MXRK.at<30000))return;MXRK.em=1;
 try{const sn=await db.collection("players").get();
  const nmr=v=>{const n=Math.floor(+v);return isFinite(n)?Math.max(0,Math.min(9e8,n)):0};
  MXRK.lista=(sn.docs||[]).map(d=>{const x=d.data()||{},pf=x.pf||{},mx={};
   if(pf.mx&&typeof pf.mx=="object")Object.keys(pf.mx).forEach(k=>{const v=pf.mx[k];if(C[k]&&Array.isArray(v))mx[k]=[nmr(v[0]),nmr(v[1])]});
   return{id:d.id,nome:String(x.n==null?"":x.n).replace(/[\u0000-\u001f]/g,"").slice(0,24)||"Jogador",pf:pfLimpa(pf,x.n),mx}});
  MXRK.at=Date.now();if(G.scr=="lb"&&LBM=="mx")showLobby()}catch(e){}finally{MXRK.em=0}}
/* a lista de um personagem: contas de verdade, a populacao da temporada e eu */
function mxRankLista(k){const L=[],eu=(typeof FR!="undefined"&&FR.pid)||(typeof O!="undefined"&&O.pid)||"",vis={};
 (MXRK.lista||[]).forEach(x=>{if(x.id===eu)return;const v=x.mx[k];if(!v||!v[0])return;vis[x.nome.toLowerCase()]=1;
  L.push({nome:x.nome,pt:v[0],nv:mxNivelInf(v[0],v[1]),pf:x.pf})});
 try{let P=rkPopLoad();try{if(P.t<rkPopTickAgora()){rkPopSync();P=rkPopLoad()}}catch(e){}const B=rkPopBase().L;
  P.st.forEach((s,i)=>{const n=(s.w||0)+(s.l||0);if(!n||!B[i]||B[i].ent>P.t)return;const nome=(B[i]&&B[i].nome)||"";if(!nome||vis[nome.toLowerCase()])return;
   const wr=(s.w||0)/n,r=rkMxCalc("p"+i,n,wr,k);if(!r.pt)return;
   L.push({nome,pt:r.pt,nv:mxNivelInf(r.pt,r.dn),pop:[i,n,wr]})})}catch(e){}
 const me=mxDe(k);if(me.pt>0)L.push({nome:pfNick(),pt:me.pt,nv:mxNivelInfDe(k),pf:pfMini(),eu:1});
 return L.sort((a,b)=>(b.pt-a.pt)||String(a.nome).localeCompare(String(b.nome),"pt-BR")||(a.eu?-1:b.eu?1:0))}
function mxPainelRank(){const t=mk("div","rktop mxrk");
 if(!MXRK.k||!C[MXRK.k]){const tp=pfTop();MXRK.k=tp[0]?tp[0][0]:pfRos()[0]}
 const k=MXRK.k;
 /* faixa com todos os personagens */
 const fx=mk("div","mxrkf");
 pfRos().forEach(c=>{const b=mk("button","mxrkc"+(c===k?" on":""),"<img src='"+IMG[c+"_f"]+"' alt=''>");b.title=shn(c);
  b.onclick=()=>{MXRK.k=c;showLobby()};fx.append(b)});
 t.append(fx);
 t.append(mk("h3","","Rank de Maestria · "+escH(shn(k))));
 const L=mxRankLista(k),meu=L.findIndex(x=>x.eu),lim=100;
 t.append(mk("p","rknada",(L.length?L.length+" jogador"+(L.length==1?"":"es")+" com Maestria":"Ninguém jogou com "+escH(shn(k))+" ainda.")+(meu>=0?" · você está em "+(meu+1)+"º":"")+(MXRK.em?" · atualizando…":"")));
 if(L.length){const tb=mk("div","rkrol");
  tb.innerHTML="<table class='rktab mxrkt'><thead><tr><th>#</th><th>Jogador</th><th>Maestria</th><th>Pontos</th></tr></thead><tbody>"+
   L.slice(0,lim).map((x,i)=>{const pf=x.pf||(x.pop?pfDeConta("p"+x.pop[0],x.pop[1],x.pop[2],c=>rkMxCalc("p"+x.pop[0],x.pop[1],x.pop[2],c)):null);
    const tit=pf?pfTitTxt(pf.ti):"";
    return "<tr class='"+(x.eu?"eu ":"")+(x.nv>=MXMAX?"mxdz":"")+"'><td>"+(i+1)+"</td>"+
     "<td class='rknm mxrkn'>"+"<span class='pfch'>"+(pf?pfAv(pf.ic,pf.mo):pfAv("","pad"))+"</span>"+"<span><b>"+escH(x.nome)+"</b>"+(tit?"<em>"+escH(tit)+"</em>":"")+"</span></td>"+
     "<td class='mxrkv'>"+(x.nv>=MXMAX?"<img class='mxrks' src='"+mxArte(MXMAX)+"' alt='' title='Maestria 10'>":"")+x.nv+"</td><td class='rkpt'>"+fnum(x.pt)+"</td></tr>"}).join("")+"</tbody></table>";
  t.append(tb)}
 if(meu>=lim)t.append(mk("p","rknada","Você está em "+(meu+1)+"º, fora dos "+lim+" mostrados."));
 t.append(mk("p","mxrkd","Quem chega à Maestria 10 ganha destaque dourado aqui. Depois do 10 os níveis continuam subindo, sem limite."));
 try{mxRankBusca()}catch(e){}
 return t}

/* ===== Retroativo do Nivel da Conta =====
   Uma vez por conta: as partidas ranqueadas ja salvas viram EXP (as mesmas 275/195 das
   partidas novas). A fonte com mais partidas vale: a Maestria (cada partida paga os 4 do
   time) ou o placar da ranqueada (temporada atual e as arquivadas). Garantia: quem ja
   jogava a ranqueada fica no minimo no nivel 10 e quem ja tinha Ecos, no 5. */
let CTRETP=0;
function ctRetro(){try{const c=ctLer();if(c.ret)return c.retro||null;
 const J=k=>{try{return JSON.parse(ls(k)||"null")}catch(e){return null}};
 let mv=0,md=0;const M=J("za_mx");if(M&&M.p)Object.keys(M.p).forEach(k=>{const r=M.p[k]||{};mv+=Math.max(0,+r.v||0);md+=Math.max(0,+r.d||0)});
 const Wm=Math.round(mv/4),Lm=Math.round(md/4);
 let rw=0,rl=0;const st=J("za_rk");if(st){rw+=Math.max(0,+st.w||0);rl+=Math.max(0,+st.l||0)}
 const A=J("za_rk_arq");if(Array.isArray(A))A.forEach(x=>{rw+=Math.max(0,+(x&&x.w)||0);rl+=Math.max(0,+(x&&x.l)||0)});
 const H=J("za_rk_hist"),hn=Array.isArray(H)?H.length:0;
 const [W,L]=Wm+Lm>=rw+rl?[Wm,Lm]:[rw,rl];
 let xp=W*CTCFG.vit+L*CTCFG.der,gar=0;
 const eco=(()=>{const e=J("za_eco");if(e&&typeof e=="object"&&Object.values(e).some(v=>v&&(v.aw||v.cl||v.rt||(Array.isArray(v.cb)&&v.cb.length))))return 1;
  const q=J("za_eq");return q&&typeof q=="object"&&Object.values(q).some(v=>Array.isArray(v)?v.some(Boolean):!!v)?1:0})();
 if(W+L>0||hn>0){if(xp<ctTotal(CTCFG.rank)){xp=ctTotal(CTCFG.rank);gar=CTCFG.rank}}
 else if(eco&&xp<ctTotal(CTCFG.ecos)){xp=ctTotal(CTCFG.ecos);gar=CTCFG.ecos}
 c.xp=(c.xp||0)+xp;c.ret=1;
 c.retro={at:Date.now(),xp,partidas:W+L,gar,visto:xp>0?0:1};
 ctGrava(c);if(xp>0)CTRETP=1;
 try{pfPublica()}catch(e){}
 return c.retro}catch(e){return null}}
function ctRetroShow(dps){const fim=()=>{if(dps)try{dps()}catch(e){}};
 const c=ctLer(),R=c.retro;if(!R||R.visto||!R.xp){fim();return}
 if(document.getElementById("mxrt")){CTRETP=1;return}   /* outro aviso aberto: volta para a fila */
 const nv=ctNivel(),ov=mk("div","ctrt");ov.id="mxrt";
 const bx=mk("div","mxrtbx");bx.setAttribute("role","dialog");
 bx.innerHTML="<div class='ctrtz'>"+pfAv(pfVal(pfLer()).ic,pfVal(pfLer()).mo)+"</div><h2>Nível da Conta</h2>"+
  "<p class='ctrtg'>Você recebeu <b>"+fnum(R.xp)+" de EXP</b>"+(R.partidas?" pelas suas <b>"+fnum(R.partidas)+" partida"+(R.partidas==1?"":"s")+" anterior"+(R.partidas==1?"":"es")+"</b>":" pelo que você já jogava")+"! Nível atual: <b>"+fnum(nv)+"</b>.</p>"+
  (R.gar?"<p>Como você já "+(R.gar>=CTCFG.rank?"jogava a Fila Ranqueada":"usava Ecos")+", a sua conta começa no mínimo no <b>nível "+R.gar+"</b>, para nada do que você já usava ficar trancado.</p>":"")+
  "<p>"+(nv>=CTCFG.rank?"A aba <b>Ecos</b>, a <b>Fila Casual</b> e a <b>Fila Ranqueada</b> estão liberadas.":nv>=CTCFG.ecos?"A aba <b>Ecos</b> e a <b>Fila Casual</b> estão liberadas. A Fila Ranqueada libera no nível 10.":"A aba Ecos e a Fila Casual liberam no nível 5, e a Fila Ranqueada no 10.")+"</p>";
 /* as recompensas de Maestria que ja estao liberadas */
 const L=pfRos().map(k=>({k,n:mxNivelDe(k)})).filter(x=>x.n>=2).sort((a,b)=>b.n-a.n);
 if(L.length){bx.append(mk("p","mxrtt","Recompensas de Maestria liberadas para o seu <b>Perfil</b>:"));
  const l=mk("div","mxrtl");
  L.slice(0,document.body.classList.contains("ph")?2:5).forEach(x=>{const n=x.n,ps=["Ícone"];const t=mxSeloTier(n);if(t)ps.push("Selo "+["","I","II","III"][t]);
   const tn=[10,8,4].find(v=>n>=v);if(tn)ps.push("Título “"+mxTitulo(x.k,tn)+"”");if(n>=7)ps.push("Fundo");if(n>=9)ps.push("Efeito de entrada");
   const r=mk("div","mxrti");
   r.innerHTML="<img class='mxrtf' src='"+(IMG[x.k+"_f"]||"")+"' alt=''><div class='mxrtd'><b>"+escH(shn(x.k))+" · Maestria "+x.n+"</b><span class='ctrtp'>"+ps.map(escH).join(" · ")+"</span></div>";
   l.append(r)});bx.append(l);
  const mais=L.length-(document.body.classList.contains("ph")?2:5);if(mais>0)bx.append(mk("p","mxrtt","E mais <b>"+mais+"</b> personage"+(mais==1?"m":"ns")+". Tudo aparece no <b>Personalizar</b> do Perfil."));
  const mo=PFMOLD.filter(m=>m[2]&&mxMaiorNv()>=m[2]).map(m=>m[1].toLowerCase());
  if(mo.length)bx.append(mk("p","mxrtt","Molduras: <b>"+mo.join(", ")+"</b>"))}
 const ft=mk("div","mxrtft"),ok=mk("button","lam lam-g","<b>Valeu!</b>"),pf=mk("button","lam","<b>Ver meu perfil</b>");
 const fecha=ir=>{ov.remove();document.removeEventListener("keydown",tec,true);
  try{const x=ctLer();if(x.retro){x.retro.visto=1;ctGrava(x)}}catch(e){}if(ir)showPerfil();else{if(G.scr=="m")try{showMenu()}catch(e){}fim()}};
 const tec=e=>{if(e.key=="Escape"){e.stopPropagation();fecha()}};
 ok.onclick=()=>fecha();pf.onclick=()=>fecha(1);ft.append(pf,ok);bx.append(ft);ov.append(bx);
 document.body.append(ov);document.addEventListener("keydown",tec,true);
 try{sfx("ok")}catch(e){}}

