let ECOAVP=0;
function ecoAvisoCheca(){try{if(ls("za_ecoav")==="1")return;
 const J=k=>{try{return JSON.parse(ls(k)||"null")}catch(e){return null}};
 const e=J("za_eco"),q=J("za_eq");
 const tinha=(e&&typeof e=="object"&&Object.values(e).some(v=>v&&(v.aw||v.cl||v.rt||(Array.isArray(v.cb)&&v.cb.length))))||
  (q&&typeof q=="object"&&Object.values(q).some(v=>Array.isArray(v)?v.some(Boolean):!!v));
 if(!tinha){ls("za_ecoav","1");return}
 if(ctLiberado("ecos"))ECOAVP=1}catch(e){}}
