function hovPos(el){const t=document.getElementById("tip");if(!t)return;const r=el.getBoundingClientRect(),w=t.offsetWidth,h=t.offsetHeight;let x=r.left+r.width/2-w/2,y=r.top-h-10;if(y<6)y=r.bottom+10;if(y+h>innerHeight-6)y=Math.max(6,innerHeight-h-6);x=Math.max(6,Math.min(x,innerWidth-w-6));t.style.left=x+"px";t.style.top=y+"px"}
