const BOTWAIT=3900;
/* na fila ranqueada o adversário de bot leva de 10 a 30 segundos por turno, como um jogador de verdade.
   O 1100 é o tempo que a jogada já leva entre planejar e encerrar o turno. */
const RKTHINK=[10000,30000];
/* enquanto o bot "pensa" por dezenas de segundos, o jogador precisa ver que a partida não travou.
   O aviso mora no painel do meio e se redesenha sozinho, para um render() no meio do caminho não apagá-lo. */
let RKPT=null;
function rkPensa(on){try{
 if(RKPT){clearInterval(RKPT);RKPT=null}
 const fora=()=>{const e=document.getElementById("rkpn");if(e)e.remove()};
 if(!on){fora();return}
 const draw=()=>{if(G.scr!="p"||G.win!=null||G.cur!=1||!((G.rkm&&G.rkm.bot)||G.csm)){fora();if(RKPT){clearInterval(RKPT);RKPT=null}return}
  const bar=document.getElementById("bar");if(!bar)return;
  const e0=document.getElementById("rkpn");if(e0&&e0.parentNode===bar)return;if(e0)e0.remove();
  const e=mk("div","rkpn");e.id="rkpn";
  const nb=document.createElement("b");nb.textContent=G.rkNome||"Adversário";
  const dt=document.createElement("span");dt.className="rkpd";dt.innerHTML="<i></i><i></i><i></i>";
  e.append(nb,document.createTextNode(" está jogando"),dt);
  bar.insertBefore(e,bar.firstChild)};
 draw();RKPT=setInterval(draw,500)}catch(x){}}
function botWait(){if(G.rkm&&G.rkm.bot&&G.t>0)return Math.max(900,Math.round(RKTHINK[0]+Math.random()*(RKTHINK[1]-RKTHINK[0]))-1100);
 /* o adversario da Fila Casual tambem pensa como gente, um pouco mais rapido que o da ranqueada */
 if(G.csm&&G.t>0)return Math.max(900,Math.round(CSTHINK[0]+Math.random()*(CSTHINK[1]-CSTHINK[0]))-1100);
 return G.t>1?BOTWAIT:700}
function botPlay(){const go=()=>G.bot&&G.cur==1&&G.win==null&&G.scr=="p"&&!G.inOn&&!G.g2v;if(!go())return;G.u.filter(x=>x.c=="bj"&&x.s==1&&x.alive).forEach(b=>{const o=G.u.filter(x=>x.s==1&&x.alive&&x!==b).sort((p,q)=>q.hp-p.hp)[0];b.bjp=o&&b.hp<=60&&o.hp>b.hp+20?G.u.indexOf(o):null});const hw=(G.holdT||0)-Date.now();if(hw>0){clearTimeout(G._bpw);G._bpw=setTimeout(botPlay,hw+200);return}if(G._bpp)return;G._bpp=1;const bw=botWait();if(bw>5000)rkPensa(1);setTimeout(()=>{G._bpp=0;rkPensa(0);if(!go())return;if((G.holdT||0)>Date.now())return botPlay();botPlan(1);render();setTimeout(()=>{if(go())endTurn()},1100)},bw)}
function dm0(u,k){const r=[];if(u.cp){const cv=ecoV("of1")*cpn(u,"of1")+ecoV("of2")*cpn(u,"of2")*(u.cpt||0)+5*cpn(u,"as2")-5*cpn(u,"as1")+(cpn(u,"lu2")&&u.hp*2<=u.mx?5:0);if(cv)r.push({v:Math.round(cv*10)/10,src:"Ecos equipados"})}if(has(u,"EXAU"))r.push({v:-15,src:"Exaustão"});if(u.cln&&u.c=="nar"){const v=uq(u,"uq_nar_1")?0:5;if(v)r.push({v:-v,src:"Clones das Sombras"})}if(u.lb)r.push({v:u.lb,src:"Líder: Gohan SSJ2 (acumulado, máx. "+25+")"});if(G.cf=="konoha"&&!fdI(u)){const n=knhN(u.s);if(n)r.push({v:KNHDANO*n,src:"Campo: Konoha ("+n+" aliado"+(n>1?"s":"")+" derrotado"+(n>1?"s":"")+")"})}if(G.lead[u.s]=="beast")r.push({v:10,src:"Líder: Gohan Beast"});if(G.lead[1-u.s]=="tu")r.push({v:-10,src:"Líder inimigo: Turles"});if(u.bn&&!np(u))r.push({v:u.bn,src:"Passiva: "+C[u.c].ps.n+" (acumulado)"});if(u.jwB)r.push({v:u.jwB,src:"Invocar - Igris (Jin Woo)"});if(has(u,"RAIVA"))r.push({v:10,src:"Raiva"});
 if(u.c=="black"&&!np(u)){const v=10*Math.floor((u.mx-u.hp)/30);if(v)r.push({v,src:"Passiva: Apogeu da Beleza. ("+(u.mx-u.hp)+" de HP perdido)"})}
 if(u.c=="mv"&&!np(u)){const t=G.tc[u.s];if(t<=5)r.push({v:10,src:"Passiva: O poder do SSJ3! (restam "+(6-t)+" turno(s))"});else r.push({v:-Math.min(10,(uq(u,"uq_mv_1")?5:10)*(t-5)),src:"Passiva: O poder do SSJ3! ("+(t-5)+"º turno perdendo força, limite -10)"})}
 if(u.c=="lv"&&!np(u)&&(u.lvk||0))r.push({v:5*(u.lvk||0),src:"Passiva: Não subestime a humanidade. ("+u.lvk+" abate"+(u.lvk>1?"s":"")+")"});
 if(k&&G.lead[u.s]=="rd")r.push({v:15,src:"Líder: Raditz (2 ou mais alvos)"});if(k&&G.zd&&G.zd[1-u.s])r.push({v:20,src:"Zona inimiga: A verdadeira luta começa agora"});return r}
