function heal(x,n){if(has(x,"BCURA")||!x.alive)return 0;const S=G.su;if(G.lead&&G.lead[1-x.s]=="nar")n=n/2;/* Lider Naruto: cura inimiga pela metade */n=Math.max(0,Math.floor(n));const h0=x.hp;x.hp=Math.min(x.mx,x.hp+n);const g=x.hp-h0;if(g>0)x.hld=1;if(g>0&&!G.sim){(G.fx||(G.fx=[])).push({i:G.u.indexOf(x),h:g});const hl=G.su&&G.su.s==x.s?G.su:x;sx(hl,"heal",g);sx(x,"hrec",g,null)}return g}
function pst(u,k,v){if(!u||G.sim)return;u.pst=u.pst||{};u.pst[k]=(u.pst[k]||0)+(v==null?1:v)}const pg=(u,k)=>(u.pst&&u.pst[k])||0;
function low(u){return ally(u).filter(x=>x!=u).sort((a,b)=>a.hp-b.hp)[0]}
function nl(tg){if(G.su&&G.su.c=="tr"&&G.su.s!=tg.s&&has(tg,"ANUL"))pst(G.su,"ign");if(!G.su||G.su.s==tg.s||G.su.c=="tr"||G.nan)return 0;if(G.nul.includes(tg))return 1;if(has(tg,"NVP")&&!G.bp){G.nul.push(tg);nvpHit(tg);return 1}if(has(tg,"TROC")&&!G.bp){G.nul.push(tg);trocHit(tg);return 1}if(has(tg,"ANUL")){rm(tg,"ANUL");G.nul.push(tg);log(C[tg.c].n+" anulou a habilidade");return 1}return 0}





