  ["Líder","Ativo 1","Ativo 2","Ativo 3"].forEach((n,i)=>{if(t[i]&&!C[t[i]])t[i]=null;const e=mk("div","slot"+(t[i]?"":" e"),(t[i]?"<img src='"+IMG[t[i]+"_f"]+"'>":"")+"<small>"+n+(t[i]?"<br><b>"+C[t[i]].n+"</b>":"")+"</small>");if(t[i])att(e,()=>card(t[i]),()=>{t[i]=null;build()});sl.append(e)});
  /* filtros iguais aos da aba Personagens */
  const ft=mk("div","bft"),q=mk("input","chq"),cs=clSel("Todas as classes"),cs2=clSel("+ 2ª classe"),cnt=mk("small","chcnt");
  q.type="search";q.placeholder="Buscar personagem…";q.value=BF2.q;q.setAttribute("aria-label","Buscar personagem");
  cs.setAttribute("aria-label","Filtrar por classe");cs2.setAttribute("aria-label","Filtrar por segunda classe");
  const RK=ROS.filter(x=>C[x]),nc=v=>v=="all"?RK.length:RK.filter(x=>cls(x).includes(v)).length;
  cs.setItems([["all","Todas as classes"]].concat(CLS.map(x=>[x,x])).map(([v,n])=>({v:v,n:n+" ("+nc(v)+")"})));cs.value=BF2.c;
  const fill2=()=>{const c1=BF2.c;if(c1=="all"||BF2.c2==c1)BF2.c2="all";
   const L=[{v:"all",n:c1=="all"?"+ 2ª classe (escolha a 1ª)":"+ 2ª classe (qualquer)"}];
   if(c1!="all")CLS.filter(x=>x!=c1).forEach(x=>{const n=RK.filter(y=>cls(y).includes(c1)&&cls(y).includes(x)).length;L.push({v:x,n:x+" ("+n+")",disabled:!n})});
   cs2.setItems(L);cs2.disabled=c1=="all";const op=L.find(o=>o.v==BF2.c2);if(!op||op.disabled)BF2.c2="all";cs2.value=BF2.c2};fill2();
  const fs=fxSel(BF2.f,v=>{BF2.f=v;build()});
  const clr=mk("button","chclr","✕ Limpar");clr.onclick=()=>{BF2={c:"all",c2:"all",f:"all",q:""};build()};
  q.oninput=()=>{BF2.q=q.value;clearTimeout(window._bftt);window._bftt=setTimeout(()=>{const foco=document.activeElement===q;build();if(foco){const n=document.querySelector(".bft .chq");if(n){n.focus();n.setSelectionRange(n.value.length,n.value.length)}}},260)};
  cs.onchange=()=>{BF2.c=cs.value;build()};cs2.onchange=()=>{BF2.c2=cs2.value;build()};
  const qq=(BF2.q||"").trim().toLowerCase(),ativo=BF2.c!="all"||BF2.c2!="all"||BF2.f!="all"||!!qq;clr.hidden=!ativo;
  const vis=ROS.filter(k=>!C[k]||((BF2.c=="all"||cls(k).includes(BF2.c))&&(BF2.c2=="all"||cls(k).includes(BF2.c2))&&hasFx(k,BF2.f)&&(!qq||C[k].n.toLowerCase().includes(qq))));
  cnt.textContent=ativo?vis.filter(k=>C[k]).length+(vis.filter(k=>C[k]).length==1?" personagem":" personagens"):"";
  {const r2=mk("div","bftr");r2.append(cs,cs2,fs,clr);ft.append(q,r2,cnt)}/* busca em cima, os tres filtros embaixo */
  vis.forEach(k=>{const e=mk("img","ic"+(C[k]?" on":" off")+(t.includes(k)?" sel":""));e.src=IMG[k+"_f"];
   att(e,()=>card(k),C[k]?()=>{const i=t.indexOf(k);if(i>=0)t[i]=null;else{const j=[0,1,2,3].find(x=>!t[x]);if(j!=null)t[j]=k}build()}:null);rs.append(e)});
  if(!ativo)LCKV.forEach(([k,n])=>{const e=mk("div","rslk","<img src='"+IMG["lk_"+k+"_f"]+"' alt='"+n+"'><i class='lki'>🔒</i>");att(e,()=>lkCard(k),null);rs.append(e)});
  if(!vis.filter(k=>C[k]).length)rs.append(mk("p","ivfnada","Nenhum personagem com esse filtro."));
