function predict(){const s=G.cur,cap=()=>G.u.map(x=>({hp:Math.max(0,x.hp),br:x.br,ar:arm(x),alive:x.alive,st:x.st.filter(y=>y.k!="ARM").map(y=>y.k),rv:x.rv}));
 const S=snap(),Q=G.q.map(a=>Object.assign({},a,{ts:a.ts?a.ts.slice():a.ts})),sv={sim:G.sim,bp:G.bp,rn:G.rn,fx:G.fx,kz:G.kz},cp=n=>Q.slice(0,n).map(a=>Object.assign({},a,{ts:a.ts?a.ts.slice():a.ts}));
 const states=[cap()],reps=G.rep.filter(r=>r.u.s==s).map(r=>({c:r.u.c,i:r.i||0}));let err=null;
 const W=[];try{G.sim=1;G.bp=1;let prev=0;for(let n=1;n<=Q.length;n++){G.pvw=[];G.q=cp(n);run();states.push(cap());W.push(G.pvw.slice(prev));prev=G.pvw.length;rs(S)}G.pvw=[];G.q=cp(Q.length);run();const pr=G.pvw.length;fireReps(s);W.push(G.pvw.slice(pr));states.push(cap())}catch(e){err=e}G.pvw=null;
 rs(S);G.q=Q;Object.assign(G,sv);if(err)throw err;return{states,Q,reps,W}}
