function decAud(src){return audBytes(src).then(ab=>new Promise((ok,no)=>{
 /* decodeAudioData aceita os dois feitios de chamada conforme o navegador */
 try{const r=ACX.decodeAudioData(ab,ok,no);if(r&&r.then)r.then(ok,no)}catch(e){no(e)}}))}
