function splay(k,at,g){const c=ACX,bf=SBUF[k];if(!bf||bf===1)return 0;const s=c.createBufferSource(),gg=c.createGain(),n=SFXN;s.buffer=bf;const lv=(g||1)/Math.sqrt(1+n*.6);gg.gain.setValueAtTime(0,at);gg.gain.linearRampToValueAtTime(lv,at+.008);s.connect(gg);gg.connect(BUS);SFXN++;STOCA[k]=s;s.onended=()=>{SFXN=Math.max(0,SFXN-1);if(STOCA[k]===s)delete STOCA[k]};s.start(at);return 1}
