function sfx(kind,delay){if(vol("e")<=0)return;const c=acx();if(!c)return;const t=c.currentTime+(delay||0)/1000;
 if(SLAST[kind]!=null&&Math.abs(t-SLAST[kind])<.2&&kind!="sel")return;SLAST[kind]=t;
 const o=c.createGain();o.gain.value=.9;o.connect(BUS);
 const noise=(d,f,q,g,at)=>{const b=c.createBuffer(1,Math.ceil(c.sampleRate*d),c.sampleRate),x=b.getChannelData(0);for(let i=0;i<x.length;i++)x[i]=(Math.random()*2-1)*Math.pow(1-i/x.length,2.2);const s=c.createBufferSource();s.buffer=b;const bp=c.createBiquadFilter();bp.type="bandpass";bp.frequency.value=f;bp.Q.value=q;const gg=c.createGain();gg.gain.value=g;s.connect(bp);bp.connect(gg);gg.connect(o);s.start(at)};
 const osc=(type,f0,f1,d,g,at)=>{const s=c.createOscillator(),gg=c.createGain();s.type=type;s.frequency.setValueAtTime(f0,at);s.frequency.exponentialRampToValueAtTime(Math.max(20,f1),at+d);gg.gain.setValueAtTime(g,at);gg.gain.exponentialRampToValueAtTime(.001,at+d);s.connect(gg);gg.connect(o);s.start(at);s.stop(at+d+.02)};
 const spark=at=>{osc("triangle",1300,700,.25,.22,at);osc("square",2200,1800,.12,.05,at+.03)};
 if(kind=="melee"||kind=="mcrit"){let i;do{i=Math.floor(Math.random()*SFXM.length)}while(i===SLAST._m&&SFXM.length>1);SLAST._m=i;if(!splay("m"+i,t)){osc("sine",150,45,.18,.9,t);noise(.14,900,.8,1.1,t)}if(kind=="mcrit")spark(t+.04)}
 else if(kind=="hit"){if(!splay("rng",t)){osc("sine",150,45,.18,.9,t);noise(.14,900,.8,1.1,t)}}
 else if(kind=="crit"){if(!splay("rngc",t)){osc("sine",120,35,.28,1,t);noise(.22,1400,.6,1.4,t);spark(t+.02)}}
 else if(kind=="ban"){splay("ban",t,1.1)}
 else if(kind=="cd10"){splay("cd10",t,1)}
 else if(kind=="achou"){splay("achou",t,1)}
 else if(kind=="ergase"){splay("ergase",t,1)}
 else if(kind=="heal"){[660,880,1320].forEach((f,i)=>osc("sine",f,f*1.01,.35,.22,t+i*.07))}
 else if(kind=="sel"){osc("triangle",880,1200,.06,.25,t)}
 else if(kind=="ok"){osc("triangle",660,660,.08,.25,t);osc("triangle",990,990,.12,.25,t+.07)}}
