const CFGT=[
 ["cta","Conta","O seu nick e a conta onde o progresso fica guardado"],
 ["som","Som","Volume geral, vozes, música, efeitos e a dublagem dos vídeos"],
 ["vid","Vídeo","O visual do jogo, quando os vídeos tocam e a velocidade deles"],
 ["img","Imagem","Fundo do menu, tamanho e transparência do menu e modo desempenho"],
 ["fon","Tamanho da letra","Deixe o texto do jogo maior ou menor"],
 ["cur","Cursor","A setinha do mouse dentro do jogo"],
 ["par","Partida","O nível do bot quando você joga contra o computador"],
 ["dir","Direitos autorais","As obras e os personagens que aparecem no jogo e de quem eles são"],
 ["ter","Termos e Privacidade","Os Termos de Uso e a Política de Privacidade do Projeto Ânima"]];
function mmOpts(tema){
 const velho=document.querySelector(".mmopt");
 if(velho&&!velho.dataset.cfg)return;
 if(velho)velho.remove();
 const ov=mk("div","mmopt"),bx=mk("div","mmobox cfg");
 ov.dataset.cfg="1";
 bx.setAttribute("role","dialog");bx.setAttribute("aria-label","Configurações");
 const close=()=>{ov.remove();document.removeEventListener("keydown",esc,true)},
  esc=e=>{if(e.key=="Escape"){e.stopPropagation();tema?mmOpts():close()}};
 const item=CFGT.find(x=>x[0]===tema);
 bx.append(mk("h2","",item?item[1]:"Configurações"));
 if(!item){
  bx.append(mk("p","cfgint","Escolha o que você quer ajustar."));
  const L=mk("div","cfglist");
  CFGT.forEach(([k,n,d])=>{const ico=icHTML("ui_cfg_"+k,"","");const b=mk("button","cfgit",(ico?"<em class='cfgic'>"+ico+"</em>":"")+"<span><b>"+n+"</b><small>"+d+"</small></span><i>›</i>");
   b.onclick=()=>mmOpts(k);L.append(b)});
  bx.append(L);
  /* o rodape fica grudado no fim da caixa: no celular deitado a lista de
     assuntos e mais alta que a tela e o "Sair da conta" ficava escondido
     la embaixo, so alcancavel rolando */
  const ft=mk("div","mmoft");
  const cl=mk("button","mmocl lam","Voltar");cl.onclick=close;ft.append(cl);
  /* "Sair da conta" fica só na aba Conta */
  bx.append(ft);
 }else{
  bx.append(mk("p","cfgint",item[2]));
  const d=mk("section","cfgs");
  if(tema=="cta"){ctaRows(d)}
  if(tema=="som"){const w=mk("div","mmosnd");sndRows(w);d.append(w)}
  else if(tema=="vid"){const w=mk("div","mmosnd");vidRows(w);d.append(w)}
  else if(tema=="img"){const w=mk("div","mmosnd");grfRows(w);d.append(w)}
  else if(tema=="fon"){if(window.ZFS)try{d.append(window.ZFS())}catch(e){}}
  else if(tema=="cur"){d.append(curUI())}
  else if(tema=="dir"){const t=mk("div","tmtx");t.innerHTML=termosHtml(TERMOS.direitos);d.append(t)}
  else if(tema=="ter"){d.append(termosCorpo());const t=termosLer();if(t&&t.v===TERMOS.versao&&t.at)d.append(mk("p","tmver","Você aceitou esta versão em "+new Date(t.at).toLocaleDateString("pt-BR")+"."))}
  else if(tema=="par"){const r=mk("div","blvrow");r.append(mk("span","","Nível do bot:"),blvSel());d.append(r)}
  bx.append(d);
  const ft=mk("div","cfgft");
  const vb=mk("button","mmocl lam","◀ Configurações");vb.onclick=()=>mmOpts();
  const cl=mk("button","mmocl lam lam-g","Pronto");cl.onclick=close;
  ft.append(vb,cl);bx.append(ft);
 }
 ov.onclick=e=>{if(e.target===ov)close()};
 ov.append(bx);document.body.append(ov);
 document.addEventListener("keydown",esc,true);
 setTimeout(()=>{const x=bx.querySelector("button");x&&x.focus()},50);
 return ov}

