const bTxt=k=>{const c=C[k];return c?[c.ld,c.ps&&c.ps.t].concat(c.sk.map(s=>s.t)).join(" \n "):""};
const bFx=k=>new Set((typeof fxOf=="function"?fxOf(k):[]).map(f=>f.n));
const BTAG={};function bTag(k){if(BTAG[k])return BTAG[k];const t=bTxt(k),fx=bFx(k),T={};
 T.pur=fx.has("PURIFICAR")||fx.has("IMUNIDADE");T.deb=[...fx].filter(n=>{const v=strx().m.get(n);return v&&v[1]}).length;T.buf=[...fx].filter(n=>{const v=strx().m.get(n);return v&&!v[1]&&!/^DANO|BARREIRA|ARMADURA|PURIFIC/.test(n)}).length;
 T.rmb=/REMOVE (TODOS OS|1) BUFF|Remove 1 buff|ANTI-BUFF/i.test(t);T.def=fx.has("BARREIRA")||fx.has("ARMADURA");T.pen=fx.has("DANO DIRETO")||fx.has("DANO PERFURANTE")||fx.has("DANO ENERGIZADO")||/QUEBRA/i.test(t);
 T.heal=/CURA|recupera|REVIVE/i.test(t);T.bcura=fx.has("BLOQUEIO DE CURA");T.esq=fx.has("ESQUIVA");T.aoe=C[k].sk.some(s=>s.tg=="E")||/IGNORA ESQUIVA/i.test(t);
 T.inv=fx.has("INALVEJÁVEL");T.iinv=/IGNORA INALVEJÁVEL/i.test(t);T.ki=/Energia/.test(t)&&fx.has("BLOQUEIO DE ENERGIA")||fx.has("DRENAGEM DE ENERGIA");
 T.tank=cls(k).some(c=>c=="Tanque"||c=="Suporte");
 /* mecanicas que mudam com o campo */
 const ld=String(C[k].ld||"");
 T.nf=/n[aã]o s[aã]o afetados pelo efeito de campo/i.test(ld);          /* lider que anula o campo */
 T.rev=/REVIVE|REVIVER/i.test(t.replace(ld,""));                          /* depende de reviver */
 T.hpmx=/N[aã]o pode ter seu HP m[aá]ximo reduzido/i.test(t);             /* imune a perda de HP maximo */
 T.ult=(C[k].sk||[]).length?1:0;
 return BTAG[k]=T}
function bCounter(k,opp){if(!opp.length)return 0;const a=bTag(k);let v=0;opp.forEach(o=>{const b=bTag(o);
 if(a.pur&&b.deb>=2)v+=.5;if(a.rmb&&b.buf>=2)v+=.5;if(a.pen&&b.def)v+=.45;if(a.bcura&&b.heal)v+=.35;if(a.aoe&&b.esq)v+=.4;if(a.iinv&&b.inv)v+=.4;
 if(b.pur&&a.deb>=3)v-=.35;if(b.rmb&&a.buf>=3)v-=.35;if(b.pen&&a.def&&!a.heal)v-=.25});return v}
const bD=(m,a,b)=>((m[a]||{})[b])||0;
const BW={lw:1.2,f:1.1,syn:.5,vs:4,b:0,lf:1.1,ls:.5,fs:.5,nfb:.8};
/* Regras genericas por etiqueta: so entram quando a tabela medida nao tem o
   personagem naquele campo (personagem novo, ainda sem simulacao). */
const BFDT={aincrad:{rev:-.05},maria:{hpmx:.03}};
function bFd(fd,k){const S=DSTAT,f=S.f[fd];if(f&&typeof f[k]=="number")return f[k];
 const r=BFDT[fd];if(!r)return 0;const t=bTag(k);let v=0;for(const n in r)if(t[n])v+=r[n];return v}
const bNf=L=>!!(L&&C[L]&&bTag(L).nf);
/* quanto o campo atrapalha os personagens fortes: o que um lider que anula o campo "devolve" */
function bNfGanho(fd){const S=DSTAT;if(!fd||!S.f[fd])return 0;
 const top=ROS.filter(k=>C[k]).sort((a,b)=>(S.w[b]||0)-(S.w[a]||0)).slice(0,10);
 return Math.max(0,-top.reduce((a,k)=>a+Math.min(0,bFd(fd,k)),0)/top.length)}
/* L = lider do time de quem esta sendo avaliado (quando ja e conhecido) */
function bVal(k,mine,opp,fd,asLead,L){const S=DSTAT;let v=asLead?(S.lw[k]||0)*BW.lw:(S.w[k]||0);v+=BW.b*((asLead?LRV[k]:DRV[k])||5)/100;
 const lid=asLead?k:(L||null),semCampo=bNf(lid);
 if(fd){
  if(asLead){v+=bD(S.lf||{},fd,k)*BW.lf;if(semCampo)v+=bNfGanho(fd)*BW.nfb}
  else if(!semCampo)v+=bFd(fd,k)*BW.f}
 mine.forEach(m=>{if(m===k)return;
  if(asLead)v+=bD(S.ls||{},k,m)*BW.ls;                 /* candidato a lider com os ativos */
  else if(lid&&m===lid)v+=bD(S.ls||{},lid,k)*BW.ls;    /* ativo com o lider do time */
  else{v+=bD(S.syn,k,m)*BW.syn;
   if(fd&&!semCampo&&S.fs&&S.fs[fd]){const a=k<m?k:m,b=k<m?m:k;v+=bD(S.fs[fd],a,b)*BW.fs}}});
 opp.forEach(o=>{v+=bD(S.vs,k,o)*BW.vs});
 v+=bCounter(k,opp)*.06;
 if(!asLead){const tk=mine.some(m=>bTag(m).tank);if(!tk&&bTag(k).tank)v+=.025;const mc=mine.map(m=>cls(m)[0]);if(mc.includes(cls(k)[0]))v-=.012}
 return v}
function bState(X,s){const o=1-s,rev=["fban","fbanrev","newlead","done"].includes(X.ph);
 const mine=(X.picks[s]||[]).concat(X.lead&&X.lead[s]?[X.lead[s]]:[]),opp=(X.picks[o]||[]).concat(rev&&X.lead&&X.lead[o]?[X.lead[o]]:[]);
 return{mine,opp,fd:X.fd||null,o,L:(X.lead&&X.lead[s])||null,oL:rev&&X.lead?X.lead[o]||null:null}}
function bBest(arr,f){let b=null,bv=-1e9;arr.forEach(k=>{const v=f(k)+Math.random()*.004;if(v>bv){bv=v;b=k}});return b}
function bChoose(X,s,op,lv){const st=bState(X,s),nzz=lv>=4?.004:.02,R=()=>Math.random()*nzz;
 switch(X.ph){
  case"fvote":{const core=ROS.filter(k=>C[k]).map(k=>[k,(DSTAT.w[k]||0)+(DSTAT.lw[k]||0)*.5]).sort((a,b)=>b[1]-a[1]).slice(0,8).map(x=>x[0]);
   const sc=f=>core.reduce((a,k)=>a+((DSTAT.f[f]||{})[k]||0),0)+R();return op.slice().sort((a,b)=>sc(b)-sc(a)).slice(0,2)}
  case"pre":{const n=typeof npre=="function"&&X.cfg?npre(X):3;return op.slice().sort((a,b)=>(bVal(b,[],[],st.fd,1)+R())-(bVal(a,[],[],st.fd,1)+R())).slice(0,n)}
  case"lead":return bBest(op,k=>bVal(k,st.mine,st.opp,st.fd,1)+R());
  case"seq":{const t=X.seq[X.si];
   if(t.t=="ban"){const myPl=(X.pre&&X.pre[s])||[];return bBest(op,k=>bVal(k,st.opp,st.mine,st.fd,0,st.oL)+.6*Math.max(0,bD(DSTAT.vs,k,st.mine[0]||"")+st.mine.reduce((a,m)=>a+bD(DSTAT.vs,k,m),0))+R())}
   const oppNext=op.slice().sort((a,b)=>bVal(b,st.opp,st.mine,st.fd,0,st.oL)-bVal(a,st.opp,st.mine,st.fd,0,st.oL)).slice(0,3);
   return bBest(op,k=>bVal(k,st.mine,st.opp,st.fd,0,st.L)+(lv>=4&&oppNext.includes(k)?.015:0)+R())}
  case"fban":{const myT=st.mine;return bBest(op,k=>{const isL=X.lead&&X.lead[st.o]===k;return(isL?bVal(k,st.opp.filter(x=>x!==k),myT,st.fd,1)*1.1:bVal(k,st.opp.filter(x=>x!==k),myT,st.fd,0,st.oL))+myT.reduce((a,m)=>a+bD(DSTAT.vs,k,m),0)+R()})}
  case"newlead":return bBest(op,k=>bVal(k,st.mine.filter(x=>x!==k),st.opp,st.fd,1)-bVal(k,st.mine.filter(x=>x!==k),st.opp,st.fd,0)*.7+R())}
 return null}

const bOn=()=>typeof blv=="function"&&blv()>=3;
function botFv(){if(bOn())return bChoose(D,1,FDS.map(f=>f.k),blv());return FDS.map(f=>f.k).sort(()=>Math.random()-.5).slice(0,2)}
function resFv(){D.fd=fvPick(D.fv);D.ph="field";D.who=0;D.hide=0;D.sel=[];D.rolled=0;D.fa=0;D.rd=[0,0];dClear();dRender()}
function fieldVote(){const w=mk("div","fvw"),my=D.on?O.seat:D.who;w.append(mk("div","dhead t"+my,"Escolha 2 campos que você gostaria de jogar. Os campos escolhidos pelos jogadores têm mais chance de cair no sorteio."));
 const g=mk("div","fvg");FDS.forEach(f=>{const on=D.sel.includes(f.k),e=mk("button","fvc"+(on?" s":""));e.disabled=!on&&D.sel.length>=2;e.style.backgroundImage='url("'+IMG["fd_"+f.k]+'")';e.append(mk("div","fvt","<b>"+f.n+"</b><small>"+f.d+"</small>"));if(on)e.append(mk("span","fvk","✓"));e.onclick=()=>dToggle(f.k);g.append(e)});w.append(g);
 const cf=mk("button","dcf","Confirmar ("+D.sel.length+"/2)");cf.disabled=D.sel.length<2;cf.onclick=dConfirm;w.append(cf);return w}
function dClear(){try{const e=document.getElementById("rkpn");if(e)e.remove();if(RKPT){clearInterval(RKPT);RKPT=null}}catch(x){}
 try{cdPara()}catch(x){}
 clearInterval(DT);DT=null}
