function dball(n){let s="";const P=[[50,50],[35,50,65,50],[50,32,34,62,66,62],[35,35,65,35,35,65,65,65],[50,50,30,30,70,30,30,70,70,70],[33,30,67,30,33,52,67,52,33,74,67,74],[50,50,50,24,50,76,28,37,72,37,28,63,72,63]][n-1];for(let i=0;i<P.length;i+=2)s+="<i style='left:"+P[i]+"%;top:"+P[i+1]+"%'>★</i>";return"<span class='dbb'>"+s+"</span>"}
