 ITENS.forEach((it,i)=>{const b=mk("button","cfabi"+(i===CFAB?" on":""),(it.ic?"<img src='"+it.ic+"' alt=''>":"<i class='cfnoic'></i>")+"<em>"+escH(it.ab||it.r)+"</em>");
  b.onclick=()=>{CFAB=i;pinta()};abas.append(b)});
 L.append(abas,box);pinta();
