 const linha=([a,p])=>{const b=mk("button","cfcl","<img src='"+(IMG[a+"_f"]||"")+"' alt=''><div><b>"+escH(C[a].n)+"</b><span>"+skIcons(p,a)+"</span></div>");
  b.onclick=()=>{CFAB=0;showFicha(a)};return b};
