const ctrOf=k=>(CTR[k]||[]).filter(x=>C[x[0]]);
const ctrGood=k=>Object.keys(CTR).filter(t=>C[t]&&(CTR[t]||[]).some(x=>x[0]==k)).map(t=>[t,CTR[t].find(x=>x[0]==k)[1]]);
let CHFULL=(()=>{try{return localStorage.getItem("za_chfull")==="1"}catch(e){return false}})();
function resBox(k,onFull){const R=RES[k];if(!R)return null;const w=mk("div","chres"),fc=x=>"<img src='"+IMG[x+"_f"]+"' alt='' title='"+shn(x)+"'>";
 const good=ctrGood(k),bad=ctrOf(k),dc=["","Fácil","Média","Difícil"][R.dc||2];
 w.innerHTML="<div class='chrh'><b>Em poucas palavras</b><span class='dc d"+(R.dc||2)+"'>Dificuldade: "+dc+"</span></div><p class='chrt'>"+skIcons(R.t,k)+"</p><p class='chrl'><small>Como líder</small>"+skIcons(R.lg,k)+"</p>"+
  "<div class='chrv'>"+(good.length?"<div><small>Lida bem com</small><div class='chrf'>"+good.map(x=>"<span data-why=\""+x[1].replace(/"/g,"&quot;")+"\">"+fc(x[0])+"</span>").join("")+"</div></div>":"")+(bad.length?"<div><small>Cuidado com</small><div class='chrf b'>"+bad.map(x=>"<span data-why=\""+x[1].replace(/"/g,"&quot;")+"\">"+fc(x[0])+"</span>").join("")+"</div></div>":"")+"</div>";
 w.querySelectorAll(".chrf span").forEach(e=>{const x=e.querySelector("img").title;att(e,()=>"<b>"+x+"</b><p>"+e.dataset.why+"</p>",null)});
 const b=mk("button","chfb",CHFULL?"▴ Ocultar detalhes":"▾ Ver completo");b.onclick=()=>{CHFULL=!CHFULL;try{localStorage.setItem("za_chfull",CHFULL?"1":"0")}catch(e){}onFull()};w.append(b);return w}
/* ===== Sugestão de escolha (draft): quem é bom contra os picks do oponente ===== */
let FXRE=null;const fxRe=()=>FXRE||(FXRE=new RegExp("("+[...new Set(Object.values(SI).map(x=>x[2]).concat(["DANO PERFURANTE","DANO ENERGIZADO","DANO DIRETO","DANO FIXO","DANO CRÍTICO","ARMADURA","BARREIRA","PURIFICAR","PURIFICA","QUEBRA TODA A ARMADURA","QUEBRA TODA A BARREIRA","EXECUTA","INALVEJÁVEL","RAJADAS DIVINAS","RAJADA DIVINA","FINAL NOVA","HERANÇA"]))].filter(Boolean).sort((a,b)=>b.length-a.length).map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|")+")","g"));
let SUGON=(()=>{try{return localStorage.getItem("za_sug")!=="0"}catch(e){return true}})();
/* primeira frase de um texto, para a justificativa caber na caixa */
const fr1=t=>{const x=String(t||"").trim(),m=x.match(/^[^.!?]*[.!?]/);return m?m[0].trim():x};
function sugList(){if(!D||D.ph!="seq")return[];const cur=D.seq[D.si];if(!cur||cur.t!="pick")return[];const me=D.who,op=1-me,E=D.picks[op].filter(k=>C[k]),M=D.picks[me].filter(k=>C[k]),A=dOpts().filter(k=>C[k]),S=typeof DSTAT!="undefined"?DSTAT:{w:{},vs:{},syn:{},f:{}};
 const L=A.map(k=>{let v=0;const why=[];
  E.forEach(e=>{const m=ctrOf(e).find(x=>x[0]==k);if(m){v+=1;why.push({e,t:m[1],m:1})}v+=(((S.vs[k]||{})[e])||0)*4});
  M.forEach(m=>{v+=(((S.syn[k]||{})[m])||0)*2});
  if(!E.length)v+=(S.w[k]||0)*2+((S.f[D.fd]||{})[k]||0)*2;
  /* sem contra escrito, a justificativa e o que o personagem faz */
  if(!why.length&&RES[k]&&RES[k].t)why.push({t:fr1(RES[k].t),m:0});
  return{k,v,why}}).filter(x=>x.why.length).sort((a,b)=>b.v-a.v);return L.slice(0,3)}
/* a partir do Desafiante a sugestão some: quem chegou até ali já sabe montar time.
   Volta sozinha se o jogador cair de rank. */
const SUGRK=3;
function sugOff(){try{return ((rkLoad()||{}).rank||1)>=SUGRK}catch(e){return false}}
function sugBox(){const bt=isBot(D.who);if(bt||D.spec||D.hide||sugOff())return null;const cur=D.seq&&D.seq[D.si];if(D.ph!="seq"||!cur||cur.t!="pick")return null;
 if(!SUGON){const b=mk("button","sugon","💡 Mostrar sugestão de escolha");b.onclick=()=>{SUGON=true;try{localStorage.setItem("za_sug","1")}catch(e){}dRender()};return b}
 const L=sugList(),w=mk("div","sugb"),E=D.picks[1-D.who].filter(k=>C[k]);
 const h=mk("div","sugh","<b>💡 Sugestão de escolha</b><small>"+(E.length?"Bons contra "+E.map(shn).join(", "):"O oponente ainda não escolheu: estes vão bem agora")+"</small>");const x=mk("button","sugx","Desativar");x.title="Desativar a sugestão de escolha";x.onclick=()=>{SUGON=false;try{localStorage.setItem("za_sug","0")}catch(e){}dRender()};h.append(x);w.append(h);
 if(!L.length){w.append(mk("p","sugn","Nenhuma sugestão clara agora. Escolha quem combina com o seu time!"));return w}
 L.forEach(s=>{const it=mk("button","sugi"+(D.sel.includes(s.k)?" on":""));it.innerHTML="<img src='"+IMG[s.k+"_f"]+"' alt=''><div><b>"+shn(s.k)+"</b>"+s.why.slice(0,2).map(y=>"<p>"+(y.e?"<i>vs "+shn(y.e)+":</i> ":"")+y.t.replace(fxRe(),"<b>$1</b>")+"</p>").join("")+"</div>";it.onclick=()=>{if(!D.sel.includes(s.k))dToggle(s.k)};w.append(it)});return w}
function dSelRes(){const k=D.sel&&D.sel.length==1?D.sel[0]:null;if(!k||!RES[k]||!["seq","fban","lead","newlead"].includes(D.ph))return null;const R=RES[k],w=mk("div","dres");
 w.innerHTML="<img src='"+IMG[k+"_f"]+"' alt=''><div><small>Em poucas palavras · "+shn(k)+"</small><p>"+(["lead","newlead"].includes(D.ph)?"Como líder: "+R.lg:R.t).replace(fxRe(),"<b>$1</b>")+"</p></div>";const b=mk("button","dresb","Ver completo");b.onclick=()=>card(k);w.append(b);return w}

function chDetail(k,dt){const c=C[k];dt.innerHTML="";dt.scrollTop=0;
  const top=mk("div","chtop");top.innerHTML="<img class='chsp' src='"+(IMG[k+"_s"]||IMG[k+"_f"])+"' alt='Splash art de "+shn(k)+"' title='Ver em destaque'>";top.querySelector(".chsp").onclick=()=>spZoom(k);const inf=mk("div","chinf");
  inf.innerHTML="<h2>"+c.n+"</h2><div class='chtags'>"+c.cl.split("/").map(x=>x.trim()).filter(Boolean).map(x=>"<span style='--ck:"+clsCor(x)+"'>"+clsIc(x)+x+"</span>").join("")+(sphere(k)?"<span class='sp'>"+sphere(k)+"</span>":"")+(c.fms?"<span class='sp'>Formas: "+c.fms.join(" / ")+"</span>":"")+"</div>";
  top.append(inf);dt.append(top);
  /* Ecos Despertados do personagem, logo abaixo da classe e do anime */
  {const U=CAP.filter(x=>x.c=="un"&&x.ck==k);
   if(U.length){const uw=mk("div","chun");uw.innerHTML="<small>Ecos Despertados</small>";
    U.forEach(x=>{const e=mk("div","chunit");e.innerHTML=capIco(x.i)+"<div><b>"+x.n+(x.rm?"<em>"+x.rm+"</em>":"")+"</b><p>"+skIcons(x.t,k)+"</p></div>";uw.append(e)});
    dt.append(uw)}}
  {const rb=resBox(k,()=>chDetail(k,dt));if(rb){dt.append(rb);if(!CHFULL)return}}
  const sec=(t,ic,n,sub,txt)=>{const e=mk("div","chsk");e.innerHTML=(ic?"<img src='"+ic+"' alt=''>":"<i class='noic'>⇄</i>")+"<div><small>"+t+"</small><b>"+n+"</b>"+(sub?"<em>"+sub+"</em>":"")+"<p>"+skIcons(txt,k)+"</p>"+gl(txt)+"</div>";dt.append(e)};
  sec("Habilidade de líder",IMG[k+"_b"]||IMG[k+"_f"],"Quando é o líder",null,c.ld.replace(/ ?\(ainda não implementado\)/,""));
  sec("Passiva",IMG[k+"_p"],c.ps.n,null,c.ps.t);
  {let no=0;c.sk.forEach((s,i)=>{const rep=(!c.fms&&s.fm===1)||!!s.rp;if(!rep)no++;
   const ult=!!(s.zk||s.kz||s.vz);/* habilidade com custo de Essência é a ultimate */
   sec(ult?("Ultimate"+(rep?" (substituta)":"")):(rep?"Habilidade "+no+" (substituta)":"Habilidade "+no),IMG[k+"_"+i],s.n,skCost(s)+" · "+s.cl,s.t)})}}
