function spZoom(k){const o=document.getElementById("spz");if(o)o.remove();const ov=mk("div","");ov.id="spz";const im=mk("img","");im.src=IMG[k+"_s"]||IMG[k+"_f"];if(IMG[k+"_h"]){const hi=new Image();hi.onload=()=>{im.src=hi.src};hi.src=IMG[k+"_h"]}im.alt=C[k]?C[k].n:"";const nm=mk("b","",C[k]?C[k].n:"");const x=mk("button","chzx","✕");x.setAttribute("aria-label","Fechar");ov.append(im,nm,x);const close=()=>{ov.remove();document.removeEventListener("keydown",esc,true)},esc=e=>{if(e.key=="Escape"){e.stopPropagation();close()}};ov.onclick=close;document.body.append(ov);document.addEventListener("keydown",esc,true)}
function chPop(k,onc){if(!C[k])return;const old=document.getElementById("chpop");if(old)old.remove();const ov=mk("div","chpop");ov.id="chpop";const bx=mk("div","chpbx chs"),dt=mk("div","chdt");const x=mk("button","chzx","✕");x.setAttribute("aria-label","Fechar");bx.append(x,dt);ov.append(bx);chDetail(k,dt);
 const close=()=>{ov.remove();document.removeEventListener("keydown",esc,true);if(onc)onc()},esc=e=>{if(e.key=="Escape"){e.stopPropagation();close()}};x.onclick=close;ov.onclick=e=>{if(e.target===ov)close()};document.body.append(ov);document.addEventListener("keydown",esc,true)}
const TUTV=(()=>{try{const v=localStorage.getItem("za_tutv2");if(v)return JSON.parse(v);const o=JSON.parse(localStorage.getItem("za_tutv")||"{}"),N=["Bem-vindo!","Conhecendo a tela","Seu primeiro turno","Energia e Essência","Vida e defesas","Lendo as habilidades","Tipos de dano","Buffs e debuffs","Recarga e duração","Previsão da Vovó","Líder e passiva","Campos","Treino","Modo Draft","Jogar online","Dicas de iniciante"],r={};Object.keys(o).forEach(i=>{if(o[i]&&N[i])r[N[i]]=1});return r}catch(e){return{}}})();
Object.assign(IMG,{"dr_tela": "data:image/webp;base64,", "dr_fvote": "data:image/webp;base64,", "dr_field": "data:image/webp;base64,", "dr_pre": "data:image/webp;base64,", "dr_prerev": "data:image/webp;base64,", "dr_lead": "data:image/webp;base64,", "dr_ban": "data:image/webp;base64,", "dr_banrev": "data:image/webp;base64,", "dr_pick": "data:image/webp;base64,", "dr_fban": "data:image/webp;base64,", "dr_fbanrev": "data:image/webp;base64,", "dr_done": "data:image/webp;base64,", "tv_dr1": "data:image/webp;base64,", "tv_dr2": "data:image/webp;base64,"});
