 if(c.dataset.k!==k){c.dataset.k=k;c.innerHTML="<img src='"+(IMG.ui_baba||"")+"' alt=''><p>"+t+"</p><div>"+(k=="win"?"<button data-a='again'>Jogar de novo</button><button data-a='menu'>Menu</button>":(btn?"<button class='cgo' data-a='next'>"+btn+"</button>":"")+"<button data-a='off'>Sair do guia</button>")+"</div>"}
