/* VERSÕES: antes do lançamento online tudo é 0.x (0.2, 0.2.1, 0.2.2...). Sobe para 0.3 quando juntar +3 personagens novos e o próximo patch de balanceamento. 1.0 só no lançamento online. PATCH: cada mudança é [personagem,[textos],tipo]; tipo: "b"=buff, "n"=nerf, "r"=rework/rebalanceamento (buff+nerf ou mudança drástica), "nw"=personagem novo */
/* ===== Patch 0.2.7 (07/11/2026) ===== */
(()=>{const S=(c,i,o)=>Object.assign(C[c].sk[i],o);
 // Gohan Beast
 S("beast",2,{t:"Causa 20 de DANO em um inimigo. Concede a si mesmo LIMITADOR e IMUNIDADE por 1 turno. (Não podem ser removidos)",fn:(u,t)=>{if(uq(u,"uq_beast_2"))pur(u,99);hit(u,t,20);add(u,"LIM",1);add(u,"IMUN",1);u.st.forEach(y=>{if(y.k=="LIM"||y.k=="IMUN")y.nr=1})}});
 S("beast",3,{zk:3,cd:5,t:"Causa 35 de DANO em um inimigo. Causa DESTRUIÇÃO no alvo e concede a si mesmo INALVEJÁVEL por 2 turnos.",fn:(u,t)=>{const bn=(uq(u,"uq_beast_3")&&has(t,"EXP"))?15:0;G.dst=1;try{hit(u,t,35+bn)}finally{G.dst=0}add(u,"INV",2)}});
 // Raditz
 S("rd",1,{t:"Causa 20 de DANO PERFURANTE em dois inimigos. Se o alvo tiver 50 de HP ou mais, essa habilidade causará 25 de DANO PERFURANTE.",fn:(u,ts)=>ts.forEach(t=>hit(u,t,t.hp>=50?25:20,"p"))});
 S("rd",2,{t:"Causa 25 de DANO em todos os inimigos por 2 turnos. Se o alvo tiver 50 de HP ou mais, essa habilidade causará 15 de DANO DIRETO por 2 turnos.",fn:u=>foes(u).forEach(t=>{const hi=t.hp>=50,ty=hi?"d":"n",v=hi?15:25;hit(u,t,v,ty);G.rep.push({u,t,n:1,v,ty,i:2})})});
 S("rd",3,{t:"Concede RAIVA a si mesmo por 2 turnos. Causa 30 de DANO em todos os inimigos.",fn:u=>{add(u,"RAIVA",uq(u,"uq_rd_3")?3:2);foes(u).forEach(t=>hit(u,t,30))}});
 // Trunks do Futuro SSJ
 S("tr",0,{ki:0,cd:99,t:"PURIFICA 2 debuffs de si mesmo antes de conceder a si mesmo RAIVA e AURA por 2 turnos. HERANÇA fica ativa pelo resto da batalha. (Uso único)",fn:u=>{pur(u,2);add(u,"HER",999);{const y=u.st.find(z=>z.k=="HER");if(y)y.nr=1};add(u,"RAIVA",2);add(u,"AURA",2);if(uq(u,"uq_tr_1"))add(u,"ARM",999,15)}});
 S("tr",1,{cd:1,t:"Essa habilidade só pode ser usada se “HERANÇA” estiver ativa. Causa 25 de DANO ENERGIZADO em um inimigo. Aplica BLOQUEIO DE CURA por 2 turnos.",fn:(u,t)=>{hit(u,t,25,"e");add(t,"BCURA",2)}});
 S("tr",3,{zk:3,cd:3,t:"EXECUTA o alvo caso ele esteja com 25 de HP ou menos. Ao EXECUTAR o alvo com esta habilidade, restaura toda a Essência gasta e concede a si mesmo ANULADOR.",fn:(u,t,a)=>{if(t.hp<=(uq(u,"uq_tr_3")?30:25)){if(die(t,u)){log(C[t.c].n+" foi executado");G.zk[u.s]+=cz(u,C.tr.sk[3],a);add(u,"ANUL",99)}}}});
 // Gohan SSJ2
 S("g2",0,{ki:2,t:"Causa 20 de DANO em um inimigo. Cada vez que causar dano com essa habilidade, aumenta em +10 o dano de “GOLPE EXPLOSIVO”.",fn:(u,t)=>{const r=hit(u,t,20);if(r.d>0)g2gx(u,uq(u,"uq_g2_2")?15:10)}});
 S("g2",1,{t:"Causa 20 de DANO em um inimigo. O dano dessa habilidade aumenta em +5 para cada 10 de HP que o alvo tenha perdido. Cada vez que causar dano com essa habilidade, aumenta em +10 o dano de “GOLPE EXPLOSIVO”.",dpv:(u,b)=>hpLostPv(u,C.g2.sk[1],20,b),fn:(u,t)=>{const lost=Math.max(0,t.mx-t.hp),r=hit(u,t,20+5*Math.floor(lost/10));if(r.d>0)g2gx(u,10)}});
 S("g2",2,{t:"Causa 15 de DANO DIRETO em todos os inimigos por 2 turnos. Sempre que essa habilidade for usada e causar dano, aumenta em +5 o dano de “GOLPE EXPLOSIVO”.",fn:u=>{const F=foes(u);G.ar=F.length>1;let ok=0;F.forEach(t=>{const r=hit(u,t,15,"d");if(r.d>0)ok=1;G.rep.push({u,t,n:1,v:15,ty:"d",i:2})});if(ok)g2gx(u,5)}});
 S("g2",3,{t:"Causa 10 de DANO DIRETO em um inimigo. IGNORA ESQUIVA. O custo de Essência dessa habilidade é reduzido em 3 se essa habilidade estiver causando 60 de DANO ou mais.",zr:u=>{let d=10+(u.gx||0);try{d+=dm0(u,C.g2.sk[3]).reduce((a,x)=>a+x.v,0)}catch(e){}return (d>=60?3:0)+(uq(u,"uq_g2_3")?1:0)}});
 // Goku SSJ Blue Kaioken
 S("gbk",2,{t:"Causa 25 de DANO PERFURANTE em um inimigo. Aplica 2 SANGRAMENTOS. Consome todos os SANGRAMENTOS aplicados no alvo, fazendo com que eles ativem.",
  fn:(u,t)=>{const s0=t.st.find(y=>y.k=="SANG");add(t,"SANG",(s0?s0.t:0)+2);let sgN=0;const s=t.st.find(y=>y.k=="SANG");if(s){const n=Math.max(1,Math.min(s.t,20));sgN=n;if(t.c!="sak"){t.mx=Math.max(1,t.mx-10*n);t.hp=Math.min(t.hp,t.mx)}t.st=t.st.filter(y=>y!==s);log("Sangramento de "+C[t.c].n+" ativado: -"+10*n+" de HP máximo");if(t.hp<=0&&t.alive)die(t,u)}if(t.alive)hit(u,t,25+(uq(u,"uq_gbk_3")?Math.min(25,5*sgN):0),"p")}});
 // Turles
 S("tu",3,{zk:4,t:"Causa 20 de DANO em um inimigo. Se Turles possuir BARREIRA ou ARMADURA, essa habilidade causa DANO CRÍTICO.",fn:(u,t)=>hit(u,t,20,u.br>0||arm(u)>0?"c":"n")});
 // Zamasu Fundido
 C.za.ps.t="Cura-se em 15 de HP no início de cada turno aliado. No início do turno se estiver com 50 de HP ou menos, cura-se em +25.";
 S("za",1,{cd:3,t:"REMOVE TODOS OS BUFFS DO ALVO. Aplica ANTI-BUFF e SANGRAMENTO por 2 turnos em todos os inimigos.",fn:u=>foes(u).forEach(t=>{t.st=t.st.filter(y=>!bf(y));add(t,"ANTIB",2);add(t,"SANG",2);if(uq(u,"uq_za_1"))add(t,"FRAG",1)})});
 S("za",2,{tg:"E",t:"Causa 15 de DANO em todos os inimigos. Aplica PARALISIA por 2 turnos. Estende a duração dos debuffs em +1 turno.",fn:u=>{G.ar=1;foes(u).forEach(t=>{hit(u,t,15);t.st.forEach(y=>{if(deb(y)&&y.t<99)y.t++});add(t,"PARAL",2)});if(uq(u,"uq_za_2"))gvBr(u,15,2)}});
 // Arale
 S("ar",0,{t:"Causa 15 de DANO PERFURANTE em todos os inimigos. Para cada personagem ATORDOADO em batalha, essa habilidade causa +10 de DANO (máximo de 35 de DANO). Aplica ANTI-BUFF por 2 turnos.",
  dm:u=>{const n=G.u.filter(x=>x.alive&&has(x,"ATORD")).length,cp=uq(u,"uq_ar_1")?30:20;return n?[{v:Math.min(cp,10*n),src:n+" personagem(ns) atordoado(s) em batalha (máx. +"+cp+")"}]:[]},
  fn:u=>{const n=G.u.filter(x=>x.alive&&has(x,"ATORD")).length,cp=uq(u,"uq_ar_1")?30:20;foes(u).forEach(t=>{hit(u,t,15+Math.min(cp,10*n),"p");add(t,"ANTIB",2)})}});
 // Reflexo agora causa DANO DIRETO
 GL.REFLEXO="Devolve metade do dano recebido como DANO DIRETO.";
})();

