/* ===== Notícias (estilo painel de notícias de jogo de celular) ===== */
const NWT=[["pers","Novos personagens e Em breve"],["bal","Balanceamentos"],["ev","Eventos"]];
/* SYOFF=1 tira a secao "Sistemas" das notas do patch. Desde 22/11 ela nao vai
   a lugar nenhum - nem ao site, nem ao link de testes: o patch leva so Buffs,
   Nerfs, Ajustes e Novidades. Sem a coluna da direita a capa vira coluna unica
   e a arte dos personagens cabe inteira. O conteudo de Sistemas continua sendo
   escrito no campo sy; so nao e exibido. O build.py confere a chave. */
const SYOFF=1;
const syOf=p=>SYOFF?[]:((p&&p.sy)||[]);
const nwD=s=>{const m=/(\d+)\/(\d+)\/(\d+)/.exec(s||"");return m?new Date(+m[3],+m[2]-1,+m[1]).getTime():0};
function nwItems(){const L={pers:[],bal:[],ev:[]};
 TEASE.forEach(t=>L.pers.push({ty:"sn",k:t.k,t,id:"sn_"+t.k,d:t.d||PATCH[0].d,tag:"Em breve",tc:"sn",h:"Em breve: "+t.n+(t.co?" · "+t.co:""),img:IMG[t.imc||t.im],baked:!!t.imc,sub:t.tx}));
 PATCH.forEach(p=>(p.nw||[]).forEach(k=>{if(C[k])L.pers.push({ty:"nw",k,p,id:"nw_"+k,d:p.d,tag:"Novo personagem",tc:"nw",h:shn(k)+" chegou ao Projeto Ânima!",img:IMG[k+"_h"]||IMG[k+"_s"]||IMG[k+"_f"],bny:BNY[k],sub:clsFmt(C[k].cl)+" · "+p.t})}));
 PATCH.forEach((p,pi)=>{const E=p.ch.filter(x=>C[x[0]]);if(!E.length&&!syOf(p).length)return;
  L.bal.push({ty:"bal",ps:[p],id:"bal_"+p.t,d:p.d,tag:"Balanceamento",tc:"bal",h:p.t+(E.length?" · "+E.length+" "+(E.length>1?"personagens":"personagem"):" · Sistema"),faces:E.map(x=>x[0]),pt:p.t,last:pi==0,sub:E.length?E.slice(0,4).map(x=>shn(x[0])).join(", ")+(E.length>4?" e mais "+(E.length-4):""):"Mudanças nas regras do jogo"})});
 COLLAB.forEach(c=>{const it={ty:"co",k:c.k,c,id:"co_"+c.k,d:c.d,tag:"Collab",tc:"co",h:"Anunciada: collab "+c.n,img:IMG[c.imc],sub:(()=>{const f=c.ch.filter(x=>!coRel(x)).map(x=>x.split(" ")[0]);
   if(!f.length)return c.ch.map(x=>x.split(" ")[0]).join(", ").replace(/, ([^,]*)$/," e $1")+" já estão jogáveis";
   return f.join(", ").replace(/, ([^,]*)$/," e $1")+(f.length>1?" chegam em breve":" chega em breve")})()};L.ev.push(it);L.pers.push(it)});
 FEAT.forEach(f=>L.ev.push({ty:"ft",k:f.k,f,id:"ft_"+f.k,d:f.d||PATCH[0].d,tag:"Novidade",tc:"ft",h:f.n+(f.sb?" · "+f.sb:""),img:IMG[f.im],sub:f.h}));
 Object.values(L).forEach(a=>a.sort((x,y)=>nwD(y.d)-nwD(x.d)));return L}
const nwGet=k=>{try{return JSON.parse(localStorage.getItem(k)||"[]")}catch(e){return[]}},nwPut=(k,a)=>{try{localStorage.setItem(k,JSON.stringify(a))}catch(e){}};
function nwFresh(L){L=L||nwItems();const all=[...new Map([].concat(L.pers,L.bal,L.ev).map(i=>[i.id,i])).values()],top=Math.max(...all.map(i=>nwD(i.d))),seen=new Set(nwGet("za_nws"));return all.filter(i=>!seen.has(i.id)&&nwD(i.d)>=top)}
function nwBadge(){const n=nwFresh().length;document.querySelectorAll(".mmnwb").forEach(e=>{e.textContent=n;e.hidden=!n})}
function nwPending(){try{if(localStorage.getItem("za_nwoff")===new Date().toDateString())return false}catch(e){}const L=nwItems(),ntf=new Set(nwGet("za_nwn"));return[].concat(L.pers,L.bal,L.ev).some(i=>!ntf.has(i.id))}
/* Altura do enquadramento do banner de noticia, por personagem. A arte e
   vertical e o banner e uma faixa: o ponto certo muda de arte para arte, entao
   nao existe valor unico que sirva para todos (a Sakura some com 30%, o Mini
   Goku so mostra cabelo com 22%). Valor = posicao vertical do CSS. */
const BNY={lv:"18%",a17:"24%",ab:"22%",ar:"40%",beast:"12%",bj:"6%",black:"22%",bo:"22%",
 cl:"16%",g2:"12%",gbk:"40%",gd:"10%",gg:"10%",gi:"10%",gu:"6%",
 jw:"14%",kf:"12%",kir:"30%",mg:"30%",mv:"30%",nar:"22%",rd:"4%",
 sak:"14%",sas:"30%",tr:"12%",tu:"22%",za:"22%"};
function nwOpen(auto){if(document.getElementById("nws"))return;const L=nwItems(),all=[].concat(L.pers,L.bal,L.ev);nwPut("za_nwn",all.map(i=>i.id));
 const fresh=new Set(nwFresh(L).map(i=>i.id)),ov=mk("div","");ov.id="nws";const bx=mk("div","nwbox");ov.append(bx);
 bx.append(mk("div","nwhd",icHTML("ui_nwhd","","Notícias","<span>Notícias</span>")));const tabs=mk("div","nwtabs"),lst=mk("div","nwlst");bx.append(tabs,lst);
 let cur=NWT.findIndex(([k])=>L[k].some(i=>fresh.has(i.id)));if(cur<0)cur=0;
 const draw=()=>{tabs.innerHTML="";NWT.forEach(([k,n],x)=>{const nf=L[k].filter(i=>fresh.has(i.id)).length,b=mk("button","nwtab"+(x==cur?" on":""),"<b>"+n+"</b>"+(nf?"<i>"+nf+"</i>":""));b.type="button";b.onclick=()=>{cur=x;draw();lst.scrollTop=0};tabs.append(b)});
  lst.innerHTML="";const A=L[NWT[cur][0]];if(!A.length){lst.append(mk("p","nwvz","Nada por aqui ainda."));return}
  A.forEach(it=>{const c=mk("button","nwc"+(fresh.has(it.id)?" fr":""));c.type="button";
   const hd=mk("div","nwch","<span class='nwtg "+it.tc+"'>"+it.tag+"</span><b>"+it.h+"</b>"+(fresh.has(it.id)?"<em>NOVO</em>":""));
   const ban=mk("div","nwban "+it.tc+(it.baked?" bk":""));
   if(it.img){ban.style.backgroundImage='url("'+it.img+'")';if(it.bny)ban.style.backgroundPosition="center "+it.bny;if(it.ty!="ft"&&it.ty!="co"&&!it.baked){ban.append(mk("div","nwbt","<small>"+(it.ty=="sn"?(it.t.co||"Em breve no Projeto Ânima"):it.ty=="nw"?"Novo personagem":"Novidade")+"</small><strong>"+(it.ty=="ft"?it.f.n:it.ty=="sn"?it.t.n:shn(it.k))+"</strong>"));
    /* o rosto tambem no cartao de personagem novo e de "em breve": antes so o
       cartao de balanceamento tinha a fileira de rostos */
    if((it.ty=="nw"||it.ty=="sn")&&it.k&&IMG[it.k+"_f"]){const fc1=mk("div","nwfc");
     const im1=mk("img","");im1.src=IMG[it.k+"_f"];im1.alt="";fc1.append(im1);ban.append(fc1)}}}
   else{const fc=mk("div","nwfc");const nf=matchMedia("(max-width:560px)").matches?3:5;it.faces.slice(0,nf).forEach(k=>{const im=mk("img","");im.src=IMG[k+"_f"];im.alt="";fc.append(im)});if(it.faces.length>nf)fc.append(mk("span","","+"+(it.faces.length-nf)));
    ban.append(mk("div","nwbt","<small>Patch de Balanceamento</small><strong>"+it.pt.replace("Patch ","PATCH ")+"</strong>"),fc)}
   c.append(hd,ban,mk("div","nwft","<span>"+it.sub+"</span><time>"+it.d+"</time>"));
   c.onclick=()=>{const s=new Set(nwGet("za_nws"));s.add(it.id);nwPut("za_nws",[...s]);fresh.delete(it.id);draw();nwBadge();
    bnShow(it.ty=="bal"?{ty:"bal",ps:it.ps}:it.ty=="nw"?{ty:"nw",k:it.k,p:it.p}:it.ty=="sn"?{ty:"sn",k:it.k,t:it.t}:it.ty=="co"?{ty:"co",k:it.k,c:it.c}:{ty:"ft",k:it.k,f:it.f});
    const br=document.getElementById("bnr");if(br){br.classList.add("fromnw");const vm=br.querySelector(".bnvm");if(vm)vm.addEventListener("click",()=>close(),true)}};
   lst.append(c)})};
 const ft=mk("div","nwfoot"),off=mk("label","bnck","<input type=checkbox> Não abrir sozinho hoje"),cl=mk("button","nwcl","Fechar");cl.type="button";
 const close=()=>{if(off.querySelector("input").checked)try{localStorage.setItem("za_nwoff",new Date().toDateString())}catch(e){}ov.remove();document.removeEventListener("keydown",esc,true);nwBadge();setTimeout(()=>{try{bnNext()}catch(e){}},250)},
  esc=e=>{if(e.key=="Escape"&&!document.getElementById("bnr")&&!document.getElementById("chpop")){e.stopPropagation();close()}};
 cl.onclick=close;ov.onclick=e=>{if(e.target===ov)close()};ft.append(auto?off:mk("span",""),cl);bx.append(ft);draw();document.body.append(ov);document.addEventListener("keydown",esc,true);cl.focus()}
/* ---- patch detalhado: antes ⇒ depois, com o motivo de cada mudança ---- */
function pkIco(k,i){return i=="ps"?(IMG[k+"_p"]||IMG[k+"_f"]):i=="ld"?IMG[k+"_f"]:(IMG[k+"_"+i]||IMG[k+"_f"])}
function pkNm(k,i){if(i=="ps")return (C[k].ps&&C[k].ps.n)||"Passiva";if(i=="ld")return "Líder";const x=C[k].sk[i];return x?x.n:""}
function pkLn(ln,k){return "<ul class='pkl'>"+ln.map(a=>"<li><span>"+a[0]+"</span><div><s>"+skIcons(a[1],k)+"</s><em class='pkn'><i>&#8594;&#65038;</i><b>"+skIcons(a[2],k)+"</b></em></div></li>").join("")+"</ul>"}
function pkIt(k,x){return "<div class='pki'><img src='"+pkIco(k,x.i)+"' alt=''><div><b>"+(x.n||pkNm(k,x.i))+"</b>"+(x.ln?pkLn(x.ln,k):"")+(x.tx?"<p>"+skIcons(x.tx,k)+"</p>":"")+"</div></div>"}
function pkChar(k,o,ty,id){const c=mk("div","ptc pkb "+ty);if(id)c.id=id;
 c.innerHTML="<span class='ptf'><img src='"+IMG[k+"_f"]+"' alt=''>"+ptIco(ty)+"</span><div class='pkbd'><b>"+C[k].n+"<em class='pkt "+ty+"'>"+PTY[ty][1]+"</em></b><small>"+clsFmt(C[k].cl)+"</small>"+(o.q?"<p class='pkq'>"+skIcons(o.q,k)+"</p>":"")+(o.it||[]).map(x=>pkIt(k,x)).join("")+"</div>";
 const im=c.querySelector(".ptf img");if(im){im.onclick=()=>chPop(k);im.title="Ver personagem"}return c}
function pkCap(o,id){const x=CAPM[o.i];if(!x)return null;const ty=o.ty||"r",c=mk("div","ptc pkb cap "+ty);if(id)c.id=id;
 c.innerHTML="<span class='ptf'>"+capIco(o.i)+ptIco(ty)+"</span><div class='pkbd'><b>"+x.n+"<em class='pkt "+ty+"'>"+PTY[ty][1]+"</em></b><small>"+CAPC[x.c].t+(x.c=="sp"?" · "+capClTxt(o.i):"")+"</small>"+(o.q?"<p class='pkq'>"+skIcons(o.q)+"</p>":"")+(o.ln?pkLn(o.ln):"")+"</div>";return c}
/* ---- capa do patch: resumo com retratos, sistemas e novidades ---- */
const PCT={n:"Nerfs",b:"Buffs",r:"Ajustes",nw:"Novos personagens"};
function pcPort(k,ty,go){return "<button class='pcp "+ty+"' data-go='"+go+"'><span class='ptf'><img src='"+IMG[k+"_f"]+"' alt=''>"+ptIco(ty)+"</span><small>"+shn(k)+"</small></button>"}
function pcCapB(o,go){const x=CAPM[o.i],ty=o.ty||"r",cor=(x.c=="sp"&&CLCOR[x.g])||"";
 return "<button class='pcq "+ty+"' data-go='"+go+"'"+(cor?" style='--qc:"+cor+"'":"")+"><span class='ptf'>"+capIco(o.i)+ptIco(ty)+"</span><small>"+x.n+"</small></button>"}
function pcNov(o){const im=o.img||IMG[o.k+"_b"]||IMG[o.k+"_s"]||IMG[o.k+"_f"]||"";
 return "<figure class='pcn'><img src='"+im+"' alt=''><figcaption>"+(o.t||(C[o.k]?C[o.k].n:""))+"</figcaption></figure>"}
/* Um patch tem o que mostrar se sobrou personagem, novidade ou (quando a secao
   Sistemas esta ligada) item de sistema. */
function pcTem(p){if(!p)return false;
 if((p.ch||[]).some(x=>C[x[0]]))return true;
 if((p.nw||[]).some(k=>C[k]))return true;
 if((p.nvc||[]).some(o=>o.img||C[o.k]))return true;
 if((p.nv||[]).length)return true;/* nv e nvc sao listas diferentes de novidades */
 return syOf(p).length>0}
/* Capa do patch com mais de um lancamento: a arte e dividida por barras "/".
   LEAN e a inclinacao (a mesma do recorte de fora) e GAP a folga da barra,
   os dois em porcentagem da largura da arte. */
const PCLEAN=38,PCGAP=2.6;
function pcArtes(A){const n=A.length,L=n>2?Math.round(PCLEAN*2/n*10)/10:PCLEAN,G=n>2?PCGAP*.45:PCGAP;
 const bnd=i=>({t:i*100/n+L/2,b:i*100/n-L/2});/* divisa entre a fatia i-1 e a i */
 const r1=v=>Math.round(v*10)/10;
 let h="";
 for(let i=0;i<n;i++){
  /* A caixa de cada fatia tem a largura da arte inteira e fica centrada no meio
     da fatia VISIVEL (a primeira ja comeca cortada pela diagonal de fora, por
     isso o 10). Assim o enquadramento e o mesmo de quando ha um lancamento so,
     e o personagem fica no meio do pedaco dele em vez de encostar na barra. */
  const ini=i==0?10:i*100/n,fim=(i+1)*100/n,c=(ini+fim)/2;
  const left=c-50+(n>2&&i==n-1?3.5:0);/* a ultima fatia ficava com o personagem encostado na barra */
  const px=v=>v-left,gb=G/2;
  const l=i==0?{t:-60,b:-60}:bnd(i),d=i==n-1?{t:160,b:160}:bnd(i+1);
  const g1=i==0?0:gb,g2=i==n-1?0:gb;
  h+="<i class='pcah' style='left:"+r1(left)+"%;width:100%;clip-path:polygon("
   +r1(px(l.t)+g1)+"% 0,"+r1(px(d.t)-g2)+"% 0,"+r1(px(d.b)-g2)+"% 100%,"+r1(px(l.b)+g1)+"% 100%)'>"
   +"<img src='"+A[i]+"' alt=''></i>"}
 for(let i=1;i<n;i++){const b=bnd(i);
  h+="<i class='pcasl' style='clip-path:polygon("+r1(b.t-G/2)+"% 0,"+r1(b.t+G/2)+"% 0,"
   +r1(b.b+G/2)+"% 100%,"+r1(b.b-G/2)+"% 100%)'></i>"}
 return h}
function pcCover(p,pi){const cov=mk("section","pcov");
 /* esquerda: tudo que mudou de balanceamento, agrupado como nas notas de atualizacao */
 const L=["nw","b","n","r"].map(ty=>{/* mesma ordem das secoes: novidades, buffs, nerfs, ajustes */
  const E=p.ch.filter(x=>C[x[0]]&&(x[2]||"r")==ty).map(x=>pcPort(x[0],ty,"pk"+pi+"_"+x[0]));
  const Q=(p.cp||[]).filter(o=>CAPM[o.i]&&(o.ty||"r")==ty).map(o=>pcCapB(o,"pkc"+pi+"_"+o.i));
  if(!E.length&&!Q.length)return"";
  return "<section class='pcs "+ty+"'><h3>"+ptIco(ty)+"<span>"+PCT[ty]+"</span><b>"+(E.length+Q.length)+"</b></h3><div class='pcg'>"+E.join("")+Q.join("")+"</div></section>"}).join("");
 /* direita: sistemas e novidades.
    SYOFF=1 esconde a secao Sistemas: o site publico leva so Buffs, Nerfs,
    Ajustes e Novidades. O build.py liga essa chave ao gerar o site; aqui no
    link de testes ela fica 0 e a secao aparece inteira. */
 const SY=syOf(p),NV=(p.nvc||[]).filter(o=>o.img||C[o.k]);
 const R=(SY.length?"<section class='pcs sy'><h3><i class='pti cp'>⚙</i><span>Sistemas</span></h3><ul class='pcsl'>"+SY.map(x=>"<li>"+skIcons(x)+"</li>").join("")+"</ul></section>":"")
  +(NV.length?"<section class='pcs nv'><h3><i class='pti nv'>+</i><span>Novidades</span></h3><div class='pcgn'>"+NV.map(pcNov).join("")+"</div></section>":"");
 const TT="<div class='pcti'><small>Notas da atualização</small><b>"+p.t.replace(/^Patch\s*/i,"")+"</b><em>"+p.d+(pi==0?" · Mais recente":"")+"</em></div>";
 const LG=pi==0?"<div class='ptlg pcleg'>"+["b","n","r","nw"].map(t=>"<span>"+ptIco(t)+PTY[t][1]+"</span>").join("")+"</div>":"";
 /* Sem Sistemas nem Novidades a coluna da direita so teria a legenda: nesse caso
    a capa vira coluna unica, senao fica meia tela em branco (acontece no site,
    com SYOFF). */
 if(!R)cov.classList.add("so1");
 /* personagem novo do patch: a arte grande entra na capa, cortada em diagonal.
    Com mais de um lancamento no mesmo patch a arte e dividida ao meio por uma
    barra "/", com um personagem de cada lado. Regra do usuario: sempre que
    houver dois ou mais lancamentos, dividir. */
 const arteDe=k=>IMG[k+"_h"]||IMG[k+"_s"];
 /* lancamento e so o que esta marcado como novo: o "nvc" entra apenas quando
    nao ha nenhum, porque ele tambem guarda novidade de personagem antigo */
 let NOVOS=[].concat((p.ch||[]).filter(x=>C[x[0]]&&(x[2]||"r")=="nw").map(x=>x[0]),
   (p.nw||[]).filter(k=>C[k]))
   .filter((k,i,a)=>a.indexOf(k)===i&&arteDe(k));
 if(!NOVOS.length)NOVOS=(p.nvc||[]).filter(o=>o.k&&C[o.k]&&arteDe(o.k)).map(o=>o.k)
   .filter((k,i,a)=>a.indexOf(k)===i).slice(0,1);
 let ART="";
 /* o desenho antigo nao tinha splash na capa, e o CSS que posiciona o .pcart
    mora no a2v (desligado no Legado): sem isso a arte vira um bloco solto e
    toma a tela toda no banner de entrada */
 const semArte=(typeof temaLer=="function"&&temaLer()==="leg");
 if(semArte)NOVOS.length=0;
 if(NOVOS.length>1){const A=NOVOS.slice(0,3);
  ART="<div class='pcart du"+(A.length>2?" tri":"")+"'>"
   +pcArtes(A.map(arteDe))
   +"<div class='pcartt'><small>Neste patch</small><b>"
   +A.map(shn).join("<em>/</em>")+"</b></div></div>";
  cov.classList.add("temart","temart"+(A.length>2?"3":"2"))}
 else if(NOVOS.length){const k=NOVOS[0];
  ART="<div class='pcart'><img src='"+arteDe(k)+"' alt=''><div class='pcartt'><small>Neste patch</small><b>"+shn(k)+"</b></div></div>";
  cov.classList.add("temart")}
 cov.innerHTML=ART+"<div class='pccol'>"+TT+(L||"<p class='pcvz'>Sem mudanças de kit neste patch.</p>")+"</div><div class='pccol'>"+R+LG+"</div>";
 cov.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>{const el=document.getElementById(b.dataset.go);if(!el)return;
  el.scrollIntoView({behavior:"smooth",block:"center"});el.classList.add("pkfx");setTimeout(()=>el.classList.remove("pkfx"),1300)});
 return cov}
function showPatch(){G.scr="pt";const w=pgShell("Patch de Balanceamento","pat"),bd=mk("div","ptbd");w.append(bd);
 PATCH.forEach((p,pi)=>{
  /* Com SYOFF (site publico) tres patches antigos ficam sem nada para mostrar,
     porque so tinham a secao Sistemas. Melhor some-los do que exibir um cartao
     vazio com titulo e data. */
  if(!pcTem(p))return;
  const s=mk("section","ptv"+(pi==0?" new":""));s.append(pcCover(p,pi));
  /* ordem do patch: Novidades, Buffs, Nerfs, Ajustes/Reworks */
  if(p.nv&&p.nv.length){s.append(mk("div","ptg nv","<i class='pti nw'>✦</i><span>Novidades</span><small>"+p.nv.length+"</small>"));p.nv.forEach(x=>{const c=mk("div","ptc pnv"+(x.hl?" hl":""));c.innerHTML=scic((x.im&&IMG[x.im]?"<img class='pnvim' src='"+IMG[x.im]+"' alt=''>":"<i>"+x.i+"</i>")+"<div><b>"+x.n+(x.hl?" <em>Destaque</em>":"")+"</b><p>"+x.t+"</p>"+(x.li?"<ul>"+x.li.map(y=>"<li>"+y+"</li>").join("")+"</ul>":"")+"</div>");s.append(c)})}
  ["nw","b","n","r"].forEach(ty=>{const E=p.ch.filter(x=>C[x[0]]&&(x[2]||"r")==ty);if(!E.length)return;s.append(mk("div","ptg "+ty,ptIco(ty)+"<span>"+PTY[ty][0]+"</span><small>"+E.length+"</small>"));
   E.forEach(([k,L])=>{if(L&&!Array.isArray(L)){s.append(pkChar(k,L,ty,"pk"+pi+"_"+k));return}
    const c=mk("div","ptc "+ty);c.id="pk"+pi+"_"+k;c.innerHTML="<span class='ptf'><img src='"+IMG[k+"_f"]+"' alt=''>"+ptIco(ty)+"</span><div><b>"+C[k].n+"</b><ul>"+L.map(x=>"<li>"+skIcons(x,k)+"</li>").join("")+"</ul></div>";c.querySelector("img").onclick=()=>chPop(k);c.querySelector("img").title="Ver personagem";s.append(c)})});
  {const CP=(p.cp||[]).filter(o=>CAPM[o.i]);if(CP.length){s.append(mk("div","ptg cp","<i class='pti cp'><img src='"+(IMG.ui_eco||"")+"' alt='' style='width:100%;height:100%;object-fit:contain'></i><span>Ecos</span><small>"+CP.length+"</small>"));CP.forEach(o=>{const c=pkCap(o,"pkc"+pi+"_"+o.i);if(c)s.append(c)})}}
  if(syOf(p).length){const c=mk("div","ptc sys");c.innerHTML="<i>⚙️</i><div><b>Sistema</b><ul>"+syOf(p).map(x=>"<li>"+skIcons(x)+"</li>").join("")+"</ul></div>";s.append(c)}
  bd.append(s)})}
const PTY={nw:["Novos personagens","Novo"],b:["Buffs","Buff"],n:["Nerfs","Nerf"],r:["Ajustes e reworks","Ajuste"]};
function ptIco(t){if(t=="b")return"<i class='pti b' title='Buff'><svg viewBox='0 0 16 16' aria-hidden='true'><path d='M8 2.5 13.5 9H10v4.5H6V9H2.5z'/></svg></i>";
 if(t=="n")return"<i class='pti n' title='Nerf'><svg viewBox='0 0 16 16' aria-hidden='true'><path d='M8 13.5 2.5 7H6V2.5h4V7h3.5z'/></svg></i>";
 if(t=="r")return"<i class='pti r' title='Rework / rebalanceamento'><svg viewBox='0 0 16 16' aria-hidden='true'><circle cx='8' cy='8' r='4.2'/></svg></i>";
 return"<i class='pti nw' title='Novo'><svg viewBox='0 0 16 16' aria-hidden='true'><path d='m8 1.8 1.9 4 4.3.5-3.2 3 .9 4.3L8 11.4l-3.9 2.2.9-4.3-3.2-3 4.3-.5z'/></svg></i>"}
