function capFit(id,ck){const x=CAPM[id];if(!x)return 0;if(x.c=="un")return x.ck==ck?1:0;if(x.c!="sp")return 1;const L=CAPG[x.g]||[];return cls(ck).some(y=>L.includes(y))?1:0}
