/* ---- Ecos equipados ----
   Cada personagem: {aw: Eco Despertado, cl: Eco de Classe, rt: Eco de Ritmo,
   lado: "of" (Ofensivo) ou "df" (Defensivo), cb: os 2 Ecos de Combate desse lado} */
const ECOK="za_eco";
const ecoVazio=()=>({aw:"",cl:"",rt:"",lado:"",cb:[]});
function ecoSan(e,ck){const o=ecoVazio();if(!e||typeof e!="object")return o;
 const ok=(id,c)=>{const x=CAPM[id];return x&&x.c==c&&(!ck||capFit(id,ck))?id:""};
 o.aw=UNOFF?"":ok(e.aw,"un");o.cl=ok(e.cl,"sp");o.rt=ok(e.rt,"ut");
 o.lado=(e.lado=="of"||e.lado=="df")?e.lado:"";
 if(o.lado){const v=[];(Array.isArray(e.cb)?e.cb:[]).forEach(id=>{if(v.length<CAPSL&&ok(id,o.lado)&&!v.includes(id))v.push(id)});o.cb=v}
 return o}
/* ecos antigas viram Ecos uma vez: a Única vira o Despertado, a Especial vira o
   de Classe e a Utilidade vira o de Ritmo. O Combate fica vazio para o jogador escolher o lado. */
function ecoMigra(){try{if(localStorage.getItem(ECOK)!=null)return;
 const old=zJ("za_eq",{}),o={};
 for(const k in old){if(!C[k])continue;const e=old[k]||{},n=ecoSan({aw:e.un,cl:e.sp,rt:e.ut},k);if(n.aw||n.cl||n.rt)o[k]=n}
 zSJ(ECOK,o)}catch(e){}}
function eqAll(){ecoMigra();return zJ(ECOK,{})}
function eqGet(ck){return ecoSan(eqAll()[ck],ck)}
function eqSet(ck,v){const a=eqAll();a[ck]=ecoSan(v,ck);zSJ(ECOK,a)}
/* quantos dos 5 Ecos estao equipados */
const ecoN=e=>(e.aw?1:0)+(e.cl?1:0)+(e.rt?1:0)+(e.cb||[]).length;
function capMap(ld){const m={};if(!ld)return m;[ld.aw,ld.cl,ld.rt].concat(ld.cb||[]).forEach(i=>{if(i)m[i]=1});return m}
/* Ecos que chegam de outro aparelho (inclusive de versao antiga, com ecos):
   passam pelas mesmas regras antes de valer na partida */
function ecoMapSan(m,ck){if(!m||typeof m!="object")return null;
 const ids=Object.keys(m).filter(i=>CAPM[i]&&(m[i]|0)>0);
 const pick=c=>ids.find(i=>CAPM[i].c==c&&capFit(i,ck))||"";
 const qt=c=>ids.filter(i=>CAPM[i].c==c).reduce((a,i)=>a+(m[i]|0),0),nof=qt("of"),ndf=qt("df");
 const lado=nof||ndf?(nof>=ndf?"of":"df"):"";
 const cb=lado?ids.filter(i=>CAPM[i].c==lado).sort((a,b)=>(m[b]|0)-(m[a]|0)):[];
 const r=capMap(ecoSan({aw:pick("un"),cl:pick("sp"),rt:pick("ut"),lado,cb},ck));return Object.keys(r).length?r:null}
function capLoad(){const e=eqAll(),o={};if(!ctLiberado("ecos"))return o;for(const k in e){if(!C[k])continue;const m=capMap(eqGet(k));if(Object.keys(m).length)o[k]=m}return o}
/* o bot monta os Ecos recomendados de cada personagem */
function ecoBot(){const o={};ROS.forEach(k=>{if(!C[k])return;const m=capMap(capRecEq(k));if(Object.keys(m).length)o[k]=m});return o}
const cpn=(u,i)=>(u&&u.cp&&u.cp[i])||0;
