/* personagem sem receita escrita (um que entre depois): monta pela classe */
function capRec(ck){if(CAPREC[ck])return CAPREC[ck];
 const L=cls(ck)||[],segura=L.some(n=>/Tanque|Suporte/.test(n));
 const cl=(CAPN("sp").find(x=>capFit(x.i,ck))||{}).i||"";
 const aw=(CAPN("un").find(x=>x.ck===ck)||{}).i||"";
 return segura?{aw,cl,rt:"ut1",lado:"df",cb:["df5","df3"],w:"Defesa e cura, para aguentar a linha de frente."}
              :{aw,cl,rt:"ut1",lado:"of",cb:["of1","of2"],w:"Dano, para resolver a luta antes de apanhar."}}
/* monta o conjunto recomendado sem salvar */
function capRecEq(ck){const r=capRec(ck);return ecoSan({aw:r.aw,cl:r.cl,rt:r.rt,lado:r.lado,cb:r.cb},ck)}
/* equipa de uma vez o conjunto recomendado (substitui o que estava) */
function capAplicaRec(ck){eqSet(ck,capRecEq(ck));return capRec(ck)}
/* coloca um Eco no conjunto d, seguindo as regras dos slots (Combate: mesmo lado, sem repetir) */
function ecoPoe(d,id,ck){const x=CAPM[id];if(!x||!capFit(id,ck))return d;d=ecoSan(d,ck);
 if(x.c=="un")d.aw=id;else if(x.c=="sp")d.cl=id;else if(x.c=="ut")d.rt=id;
 else{if(d.lado!=x.c){d.lado=x.c;d.cb=[]}if(!d.cb.includes(id)){if(d.cb.length>=CAPSL)d.cb=[d.cb[0]];d.cb=d.cb.concat(id)}}
 return ecoSan(d,ck)}
function ecoTira(d,id,ck){d=ecoSan(d,ck);["aw","cl","rt"].forEach(k=>{if(d[k]==id)d[k]=""});d.cb=d.cb.filter(x=>x!=id);return ecoSan(d,ck)}
function capFxH(e){return"<div class='cpmx'>"+(UNOFF?ECOSL.slice(1):ECOSL).map(([k,t])=>{const x=CAPM[e[k]];return"<p class='k-"+ECOCT[k]+"'><i></i><b>"+t+(x?": "+x.n:"")+"</b><span>"+(x?x.t:"Vazio")+"</span></p>"}).join("")+
 "<p class='k-"+(e.lado||"of")+"'><i></i><b>Eco de Combate"+(e.lado?" ("+CAPC[e.lado].n+")":"")+"</b><span>"+(e.cb.length?e.cb.map(i=>CAPM[i].n+": "+CAPM[i].t).join("<br>"):"Vazio")+"</span></p></div>"}
