const sakSt=u=>Math.max(0,Math.min(uq(u,"uq_sak_1")?5:4,u.byk||0));
function sakUse(u){
 if(!u||u.c!="sak"||sakSt(u)<1)return 0;
 if(!(u.bya||(G.bot&&u.s==1)))return 0;
 u.byk=sakSt(u)-1;u.bya=0;pst(u,"byu");
 log(C.sak.n+" usou Byakugou ("+u.byk+" acúmulo(s) restante(s))");
 return 1;
}
function sakDr(u,d){
 if(!(d>0))return;
 const t=ally(u).filter(x=>x.alive).sort((a,b)=>a.hp-b.hp)[0];
 if(!t)return;const g=heal(t,d);
 if(g)log("Byakugou: "+g+" de HP transferido para "+C[t.c].n);
}
function sakLd(tg){
 if(G.lead[tg.s]!="sak"||tg.sld||!tg.alive)return 0;
 tg.sld=1;tg.rec=0;tg.hp=Math.min(tg.mx,Math.floor(75));
 log(C[tg.c].n+" resistiu com "+tg.hp+" de HP (liderança de Sakura)");
 return 1;
}
