Object.assign(IMG,{"kir_f": "data:image/webp;base64,", "kir_s": "data:image/webp;base64,", "kir_h": "data:image/webp;base64,", "kir_b": "data:image/webp;base64,", "kir_p": "data:image/webp;base64,", "kir_0": "data:image/webp;base64,", "kir_1": "data:image/webp;base64,", "kir_2": "data:image/webp;base64,", "kir_3": "data:image/webp;base64,", "kir_4": "data:image/webp;base64,", "co_sao": "/_blob/3fb0715e3adb3e6dea371abc598acdcd", "co_sao_c": "/_blob/df4b98e32b938cb8254dff02d658a6f0"});
IMG.kir_f2=IMG.kir_f;

/* Kirito: as duas espadas se substituem; cada troca barateia a habilidade que entra */
function kirSw(u){u.swc=(u.swc||0)+1;u.dw=1;u.fm=u.fm?0:1;pst(u,"sw");
 const a=u.crc||0;u.crc=Math.min(100,a+25);if(u.crc!=a&&!G.sim)log(C.kir.n+": +25% de chance de CRÍTICO (Empunhadura Dupla) — agora "+u.crc+"%")}
/* Troca!: quando a anulação acontece, o aliado passa a gastar -1 de Energia */
function trocHit(tg){if(!tg.trk){tg.trk=1;log(C[tg.c].n+" trocou de posição: as habilidades custam −1 de Energia")}
 else log(C[tg.c].n+" trocou de posição e anulou a habilidade");
 const y=tg.st.find(z=>z.k=="TROC"),k=(y&&y.src!=null)?G.u[y.src]:null;
 if(k&&k.alive&&k.c=="kir"&&uq(k,"uq_kir_1"))k.cd[2]=0}
/* Ecos Despertados do Jin Woo: a invocação já vem feita no começo da batalha, e
   a habilidade nasce como o COMANDO correspondente. O efeito aplicado é o mesmo
   da invocação normal — menos no Bellion, cuja Única troca o BLOQUEIO DE ENERGIA
   em todos por um inimigo sorteado. */
function jwCapStart(u){if(!u||!u.cp)return;
 if(uq(u,"uq_jw_1")&&!u.jwIg){u.jwIg=1;ally(u).forEach(a=>{a.jwB=(a.jwB||0)+5});
  log("Eco Despertado: Invocar - Igris já em campo (+5 de dano na equipe)")}
 if(uq(u,"uq_jw_2")&&!u.jwBe){u.jwBe=1;ally(u).forEach(a=>{a.mx+=25;a.hp+=25});
  log("Eco Despertado: Invocar - Beru já em campo (+25 de HP máximo na equipe)")}
 if(uq(u,"uq_jw_3")&&!u.jwBl){u.jwBl=1;
  const F=foes(u).filter(x=>x.alive);
  F.forEach(t=>{t.st=t.st.filter(y=>!bf(y))});
  const alvo=F[Math.floor(grnd()*F.length)];
  if(alvo)add(alvo,"BKI",1);
  log("Eco Despertado: Invocar - Bellion já em campo (buffs removidos; Energia bloqueada em "+(alvo?C[alvo.c].n:"ninguém")+")")}}
BF.push("REVV","TROC");
