/* Abate: o lider da Energia a equipe, a passiva engorda o proprio Levi.
   Chamado de dentro do die(), depois de o inimigo cair de verdade. */
function lvAbate(u,by){
 if(!u||!by||u.sb||by.sb||!by.alive||by.s===u.s)return;
 if(G.lead[by.s]=="lv"){G.lvki=G.lvki||[0,0];G.lvki[by.s]=(G.lvki[by.s]||0)+1;
  log("L\u00edder Levi Ackerman: a equipe passa a gerar +"+G.lvki[by.s]+" de Energia por turno")}
 if(by.c=="lv"&&!np(by)){by.lvk=(by.lvk||0)+1;try{pst(by,"forte")}catch(e){}
  log("N\u00e3o subestime a humanidade: Levi est\u00e1 com +"+(5*by.lvk)+" de DANO e +"+(10*by.lvk)+"% de REDU\u00c7\u00c3O DE DANO")}}
const lvKi=s=>(G.lvki&&G.lvki[s])||0;

