 S("za",3,{t:"Consome todos os debuffs de um inimigo. Cada debuff consumido causa +45 de DANO.",
  fn:(u,t)=>{const d=t.st.filter(y=>deb(y)&&!y.nr);t.st=t.st.filter(y=>!deb(y)||y.nr);if(d.length)hit(u,t,(uq(u,"uq_za_3")?55:45)*d.length)}});
