const RKCFG={
 ranks:7,divs:5,                      /* 7 ranks, divisões V..I (5 = a menor) */
 prDiv:100,                           /* PR para passar de divisão */
 prRank:120,                          /* PR para sair da divisão I e subir de rank */
 /* pontuação base por rank: [vitória, derrota] — a derrota é a magnitude */
 base:[[40,13],[36,15],[30,16],[24,17],[19,16],[14,13],[9,10]],
 baseTop:[5,7],                       /* quem está dentro do Top 100 */
 /* influência da diferença de MMR */
 fator:[.5,.75,1,1.25,1.5,1.5,1.5],fatorTop:.5,
 /* limites [ganhoMin,ganhoMax,perdaMin,perdaMax] */
 lim:[[37,45,10,17],[32,41,11,19],[25,35,12,20],[19,29,13,21],[14,24,12,20],[10,19,9,17],[6,13,7,14]],
 limTop:[4,5,6,7],
 mmr0:1000,kNovo:32,kVelho:20,kCorte:20,  /* Elo: K=32 nas 20 primeiras partidas */
 prot:3,                              /* derrotas protegidas ao subir de rank */
 divProt:1,                           /* derrotas protegidas logo depois de subir de divisão (0 = regra crua do documento) */
 pen:10,                              /* penalidades para rebaixar de rank */
 top:100,                             /* tamanho da classificação */
 resetMmr:.75,                        /* MMR_novo = 1000 + (antigo-1000) × fator */
 resetRank:[1,1,2,2,3,3,4],resetTop:4,/* rank final anterior → rank da nova temporada */
 seasonMeses:3,seasonMes0:0,          /* trimestres a partir de janeiro */
 filaBot:60000,filaBotMin:40000,                       /* 1 minuto na fila antes de cair para o bot */
 aceite:20000,                        /* tempo para os dois aceitarem */
 mmBandas:[100,200,300],              /* faixas de busca por MMR */
 mmTempos:[0,15000,30000],            /* quando cada faixa abre */
 botAceita:[1200,4200],               /* o bot aceita entre esses tempos */
 repetido:3                           /* confrontos seguidos com a mesma conta antes de evitar */,
 fichas:10                            /* quantas partidas o histórico guarda, cada uma com a ficha completa */
};
const RKN=["Aprendiz","Discípulo","Desafiante","Guardião","Conquistador","Ascendente","Monarca"];
const RKDV=["","I","II","III","IV","V"];
const rkDivN=d=>RKDV[d]||String(d);
const rkNome=st=>st&&st.pc!=null?RKN[RKCFG.ranks-1]+" · Classificação":RKN[(st?st.rank:1)-1]+" "+rkDivN(st?st.div:5);
/* precisa de 120 PR só na divisão I; nas outras, 100 */
const rkNeed=st=>st.div==1?RKCFG.prRank:RKCFG.prDiv;
const rkComp=st=>st.pc!=null;                /* já está na classificação competitiva */
const rkClamp=(v,a,b)=>Math.max(a,Math.min(b,v));
/* arredondamento consistente em todo o sistema: metade sempre para cima */
const rkRound=v=>Math.floor(v+.5);

/* zerada da temporada: quando este número muda, todo aparelho recomeça do Aprendiz V.
   Serve para apagar o rank de teste sem depender do servidor. */
const RKZERO="2026-11-20a";
let RKZOK=0;
function rkZeradaCheca(){if(RKZOK)return;RKZOK=1;try{
 if(ls("za_rk_zero")===RKZERO)return;
 ["za_rk","za_rk_hist","za_rk_arq","za_rk_pop","za_rk_bag","za_rk_promo"].forEach(k=>{try{ls(k,null)}catch(e){}});
 ls("za_rk_zero",RKZERO);
 RKPS=null;RKPB=null;for(const k in RKBAG)delete RKBAG[k];
}catch(e){}}
function rkNovo(sea){return{sea:sea||rkSeasonId(),rank:1,div:RKCFG.divs,pr:0,pc:null,mmr:RKCFG.mmr0,
 n:0,w:0,l:0,prot:0,dprot:0,pen:0,hiRank:1,hiDiv:RKCFG.divs,hiTop:null,ult:[],t0:Date.now()}}

/* ---- temporada: meses de calendário, nunca 90 dias ---- */
function rkSeasonId(d){d=d||new Date();const y=d.getUTCFullYear(),m=d.getUTCMonth();
 const q=Math.floor(((m-RKCFG.seasonMes0+12)%12)/RKCFG.seasonMeses);
 const ini=new Date(Date.UTC(y,RKCFG.seasonMes0+q*RKCFG.seasonMeses,1));
 if(ini.getTime()>d.getTime())ini.setUTCFullYear(y-1);
 return ini.getUTCFullYear()+"-T"+(Math.floor(ini.getUTCMonth()/RKCFG.seasonMeses)+1)}
function rkSeasonFim(d){d=d||new Date();const y=d.getUTCFullYear(),m=d.getUTCMonth();
 const q=Math.floor(((m-RKCFG.seasonMes0+12)%12)/RKCFG.seasonMeses);
 return new Date(Date.UTC(y,RKCFG.seasonMes0+(q+1)*RKCFG.seasonMeses,1))}

/* ---- MMR (Elo) ---- */
const rkEsperado=(meu,dele)=>1/(1+Math.pow(10,(dele-meu)/400));
function rkMmr(st,oppMmr,win){const K=st.n<RKCFG.kCorte?RKCFG.kNovo:RKCFG.kVelho;
 const E=rkEsperado(st.mmr,oppMmr),v=st.mmr+K*((win?1:0)-E);
 return Math.max(0,Math.round(v*100)/100)}

/* ---- quanto a partida vale, antes de aplicar ---- */
function rkValor(st,oppMmr,win,noTop){
 const top=rkComp(st)&&!noTop,i=Math.min(RKCFG.ranks,Math.max(1,st.rank))-1;
 const base=top?RKCFG.baseTop:RKCFG.base[i];
 const fat=top?RKCFG.fatorTop:RKCFG.fator[i];
 const L=top?RKCFG.limTop:RKCFG.lim[i];
 const dif=oppMmr-st.mmr,aj=rkRound((dif/100)*fat);
 const v=win?rkClamp(base[0]+aj,L[0],L[1]):rkClamp(base[1]-aj,L[2],L[3]);
 return{v:Math.max(1,rkRound(v)),aj,dif:rkRound(dif),base:win?base[0]:base[1],lim:win?[L[0],L[1]]:[L[2],L[3]]}}

/* ---- aplica o resultado. Função pura: devolve o estado novo e o relatório ---- */
function rkApply(st0,oppMmr,win,opt){
 opt=opt||{};
 const st=Object.assign({},st0);if(Array.isArray(st0.ult))st.ult=st0.ult.slice();
 const r={win:!!win,promo:null,demo:null,prot:0,pen:0,comp:null};
 const comp0=rkComp(st);
 /* na classificação, quem está fora do Top 100 usa a pontuação de referência do Rank 7 */
 const val=rkValor(st,oppMmr,win,comp0&&!opt.top100);r.pts=val.v;r.aj=val.aj;r.base=val.base;r.difMmr=val.dif;
 r.mmrAnt=st.mmr;r.prAnt=comp0?st.pc:st.pr;r.rankAnt=st.rank;r.divAnt=st.div;
 st.n++;if(win)st.w++;else st.l++;
 st.mmr=rkMmr(st0,oppMmr,win);r.mmrDep=st.mmr;   /* sempre a partir do MMR anterior */

 if(comp0){                                      /* ---- classificação competitiva (PC) ---- */
  if(win){st.pc+=val.v;r.comp="pc"}
  else{
   const zero=st.pc<=0;st.pc=Math.max(0,st.pc-val.v);
   if(zero){
    if(st.prot>0){st.prot--;r.prot=1}
    else{st.pen++;r.pen=1;
     if(st.pen>=RKCFG.pen){st.pen=0;st.pc=null;st.div=1;st.pr=0;r.demo="comp";r.comp="saiu"}}}}
 }else{                                          /* ---- PR por divisão ---- */
  if(win){
   st.pr+=val.v;
   if(st.pr>=rkNeed(st)){
    r.excedente=st.pr-rkNeed(st);st.pr=0;        /* excedente sempre descartado */
    if(st.div>1){st.div--;st.dprot=RKCFG.divProt;r.promo="div"}  /* fôlego para não cair de volta na derrota seguinte */
    else if(st.rank<RKCFG.ranks){st.rank++;st.div=RKCFG.divs;st.prot=RKCFG.prot;st.pen=0;r.promo="rank"}
    else{st.pc=0;st.prot=RKCFG.prot;st.pen=0;r.promo="comp";r.comp="entrou"}  /* Rank 7 I completo */
   }
  }else{
   const zero=st.pr<=0;st.pr=Math.max(0,st.pr-val.v);
   if(zero){
    if(st.div<RKCFG.divs){                                 /* divisões I..IV caem de divisão */
     if(st.dprot>0){st.dprot--;r.dprot=1}                  /* acabou de subir: segura a queda uma vez */
     else{st.div++;st.pr=0;r.demo="div"}}
    else if(st.prot>0){st.prot--;r.prot=1}                 /* divisão V: proteção segura o rank */
    else if(st.rank>1){st.pen++;r.pen=1;   /* Rank 1 V não tem rebaixamento */
     if(st.pen>=RKCFG.pen){st.pen=0;st.rank--;st.div=1;st.pr=0;r.demo="rank"}}
   }
  }
 }
 /* maior rank da temporada */
 if(st.pc!=null){st.hiRank=RKCFG.ranks;st.hiDiv=1}
 else if(st.rank>st.hiRank||(st.rank==st.hiRank&&st.div<st.hiDiv)){st.hiRank=st.rank;st.hiDiv=st.div}
 r.dprotRest=st.dprot;r.prDep=rkComp(st)?st.pc:st.pr;r.rankDep=st.rank;r.divDep=st.div;r.protRest=st.prot;r.penTot=st.pen;
 return{st,r}}

/* ---- reset de temporada ---- */
function rkReset(st0,sea){const st=rkNovo(sea);
 st.mmr=Math.max(0,Math.round((RKCFG.mmr0+(st0.mmr-RKCFG.mmr0)*RKCFG.resetMmr)*100)/100);
 const fim=st0.pc!=null?RKCFG.resetTop:RKCFG.resetRank[Math.min(RKCFG.ranks,Math.max(1,st0.rank))-1];
 st.rank=fim;st.div=RKCFG.divs;st.pr=0;st.pc=null;st.hiRank=fim;st.hiDiv=RKCFG.divs;
 return st}

/* ---- nível do bot pelo rank: quanto mais alto o rank, mais difícil ---- */
const RKBOT=[3,3,3,4,4,4,4];
const rkBotLv=st=>RKBOT[Math.min(RKCFG.ranks,Math.max(1,(st&&st.rank)||1))-1];

/* ===== estado do jogador, guardado por temporada ===== */
function rkLoad(){rkZeradaCheca();let st=null;try{st=JSON.parse(ls("za_rk")||"null")}catch(e){}
 const sea=rkSeasonId();
 if(!st||!st.sea){st=rkNovo(sea);rkSave(st);return st}
 if(st.sea!==sea){const velho=JSON.parse(JSON.stringify(st));rkArquiva(velho);st=rkReset(velho,sea);rkSave(st)}
 if(st.dprot==null)st.dprot=0;
 return st}
function rkSave(st){try{ls("za_rk",JSON.stringify(st))}catch(e){}}
function rkArquiva(st){try{const h=JSON.parse(ls("za_rk_arq")||"[]");h.unshift({sea:st.sea,rank:st.rank,div:st.div,pc:st.pc,hiRank:st.hiRank,hiDiv:st.hiDiv,w:st.w,l:st.l,n:st.n});ls("za_rk_arq",JSON.stringify(h.slice(0,12)))}catch(e){}}
function rkHist(){try{return JSON.parse(ls("za_rk_hist")||"[]")}catch(e){return[]}}
/* uma partida só pode ser processada uma vez: o id fica guardado com o histórico */
function rkJaFoi(id){return rkHist().some(x=>x.id===id)}
/* foto da partida: o bastante para a tela de estatísticas rodar de novo depois */
function rkFicha(){try{
 const u=G.u.map(x=>({s:x.s,c:x.c,fm:x.fm||0,alive:!!x.alive,hp:Math.round(x.hp),mx:x.mx,
  sx:Object.assign({},x.sx||{}),sxk:JSON.parse(JSON.stringify(x.sxk||{}))}));
 const f={u:u,t:G.t,win:G.win,sth:(G.sth||[]).slice(),lk:G.lk?G.lk.slice():null,
  lead:(G.lead||[]).slice(),tm:[((G.tm||[])[0]||[]).slice(),((G.tm||[])[1]||[]).slice()],cf:G.cf};
 try{const q=G.dsnap||((typeof D!="undefined"&&D&&D.bans)?D:null);if(q&&q.bans){
  f.ban=[(q.bans[0]||[]).filter(Boolean),(q.bans[1]||[]).filter(Boolean)];
  f.pre=[((q.pre||[])[0]||[]).filter(Boolean),((q.pre||[])[1]||[]).filter(Boolean)];
  f.dup=(q.dup||[]).filter(Boolean);
  f.fbs=[(q.fb||[])[0]||null,(q.fb||[])[1]||null];f.lbs=[(q.lban||[])[0]||null,(q.lban||[])[1]||null];
  f.fb=(q.fb||[]).filter(Boolean);f.lb=(q.lban||[]).filter(Boolean)}}catch(e){}
 return f}catch(e){return null}}
/* desistiu no draft: guarda o que ja tinha sido escolhido, sem batalha nenhuma */
function rkFichaDraft(){try{if(typeof D=="undefined"||!D)return null;
 const lead=(D.lead||[]),fb=(D.fb||[]);
 const f={u:[],t:0,win:null,des:1,sth:[],lk:null,lead:lead.slice(),cf:D.fd,
  tm:[0,1].map(t=>[lead[t]||"none"].concat(((D.picks||[])[t]||[]).filter(k=>k&&k!==lead[t]&&k!==fb[1-t])))};
 if(D.bans)f.ban=[(D.bans[0]||[]).filter(Boolean),(D.bans[1]||[]).filter(Boolean)];
 f.pre=[((D.pre||[])[0]||[]).filter(Boolean),((D.pre||[])[1]||[]).filter(Boolean)];
 f.dup=(D.dup||[]).filter(Boolean);
 f.fbs=[fb[0]||null,fb[1]||null];f.lbs=[(D.lban||[])[0]||null,(D.lban||[])[1]||null];
 f.fb=fb.filter(Boolean);f.lb=(D.lban||[]).filter(Boolean);
 return f}catch(e){return null}}
/* troca o estado do jogo pela foto, abre a tela de sempre e devolve tudo ao fechar */
function rkVerPartida(f,nome){if(!f||!f.u||!f.u.length)return;
 const ks=["u","t","win","sth","lk","lead","tm","cf","online","bot","me","sim"];
 const bak={};ks.forEach(k=>bak[k]=G[k]);
 const volta=()=>ks.forEach(k=>{G[k]=bak[k]});
 try{Object.assign(G,{u:f.u,t:f.t,win:f.win,sth:f.sth||[],lk:f.lk||null,
   lead:f.lead||["none","none"],tm:f.tm||[[],[]],cf:f.cf,online:0,bot:1,me:null,sim:0});
  showStats()}catch(e){volta();return}
 const ov=document.getElementById("stv");
 if(!ov){volta();return}
 /* a tela diz "Bot" porque não sabe de quem era a conta; aqui sabemos */
 const nomeia=()=>{if(!nome)return;const w=document.createTreeWalker(ov,NodeFilter.SHOW_TEXT),L=[];
  while(w.nextNode())if(w.currentNode.nodeValue.trim()==="Bot")L.push(w.currentNode);
  L.forEach(n=>{n.nodeValue=n.nodeValue.replace("Bot",nome)})};
 nomeia();
 const mo=new MutationObserver(()=>{if(!document.body.contains(ov)){mo.disconnect();volta();return}nomeia()});
 mo.observe(document.body,{childList:true,subtree:true})}
function rkGrava(reg){try{const h=rkHist();h.unshift(reg);
 /* só as últimas partidas ficam guardadas, para não pesar no navegador */
 const L=h.slice(0,RKCFG.fichas);
 let j=JSON.stringify(L),corte=L.length;
 while(j.length>350000&&corte>1){corte--;L.forEach((x,i)=>{if(i>=corte&&x.sn)delete x.sn});j=JSON.stringify(L)}
 ls("za_rk_hist",j)}catch(e){}}

