/* ===== informações da batalha: o draft inteiro de uma partida guardada ===== */
function rkBatalha(x){
 const velho=document.getElementById("rkbt");if(velho)velho.remove();
 const f=x.sn,ov=mk("div","");ov.id="rkbt";
 const fecha=()=>{ov.remove();document.removeEventListener("keydown",escKey,true)},
  escKey=e=>{if(e.key=="Escape"){e.stopPropagation();fecha()}};   /* nome proprio: "esc" aqui escondia o escapador de texto */
 document.addEventListener("keydown",escKey,true);
 ov.onclick=e=>{if(e.target===ov)fecha()};
 const bx=mk("div","rkbtbx");bx.setAttribute("role","dialog");
 const fd=(f&&f.cf&&typeof FDS!="undefined")?(FDS.find(y=>y.k===f.cf)||null):null;
 const eu=ls("za_nick")||"Você";
 const medEu=IMG["rk_"+(x.rank||1)+"_"+(x.div||5)];
 const medOp=(x.oppPc!=null)?IMG["rk_"+RKCFG.ranks+"_1"]:(x.oppRank?IMG["rk_"+x.oppRank+"_"+(x.oppDiv||1)]:null);
 const carta=(c,rot,ban)=>{if(!C[c])return"";
  return"<div class='rkbc"+(ban?" ban":"")+(rot?" ld":"")+"'><img src='"+(IMG[c+"_f"]||IMG[c+"_p"]||"")+"' alt=''>"+
   "<b>"+shn(c)+"</b>"+(rot?"<em>"+rot+"</em>":"")+(ban?"<em class='bn'>Banido</em>":"")+"</div>"};
 const completo=!!(f&&f.fbs);           /* partidas novas guardam o draft inteiro */
 const lado=s2=>{const tm=(f&&f.tm&&f.tm[s2])||[],ld=tm[0],ch=tm.slice(1);
  const ban=completo?[]:(f&&f.ban&&f.ban[s2]||[]).filter(c=>C[c]);
  return(ld&&ld!=="none"&&C[ld]?carta(ld,"Líder"):"")+ch.map(c=>carta(c)).join("")+ban.map(c=>carta(c,"",1)).join("")};
 const pre=completo?[]:[].concat((f&&f.fb)||[],(f&&f.lb)||[]).filter(c=>C[c]);
 /* o draft inteiro: pré-líderes, bans e ban final dos dois lados */
 const face=c=>C[c]?"<img src='"+(IMG[c+"_f"]||IMG[c+"_p"]||"")+"' alt='' title='"+shn(c)+"'>":"";
 const cel=L=>{const v=(L||[]).filter(c=>C[c]);return v.length?v.map(face).join(""):"<i class='rkbdn'>—</i>"};
 const lin=(lab,a,b2)=>"<div class='rkbdr'><span class='rkbdl'>"+lab+"</span><span class='rkbds eu'>"+cel(a)+"</span><span class='rkbds op'>"+cel(b2)+"</span></div>";
 const P=(f&&f.pre)||[[],[]],B=(f&&f.ban)||[[],[]],FS=(f&&f.fbs)||[],LS=(f&&f.lbs)||[],DUP=((f&&f.dup)||[]).filter(c=>C[c]);
 const temBan=((B[0]||[]).concat(B[1]||[])).filter(c=>C[c]).length;
 const draftHtml=!completo?"":
  "<div class='rkbdraft'><b class='rkbdt'>Como foi o draft</b>"+
   "<div class='rkbdr hd'><span class='rkbdl'></span><span class='rkbds eu'>"+esc(eu)+"</span><span class='rkbds op'>"+esc(x.opp||"Adversário")+"</span></div>"+
   lin("Pré-líderes",P[0],P[1])+
   (temBan?lin("Bans",B[0],B[1]):"")+
   lin("Ban final",[FS[0]],[FS[1]])+
   "<p class='rkbdnote'>Nas linhas de ban, cada coluna mostra quem aquele jogador tirou do adversário."+
    (DUP.length?" · Pré-líderes escolhidos pelos dois e anulados: "+DUP.map(face).join(""):"")+
    (LS.filter(c=>C[c]).length?" · Líder derrubado pelo ban final: "+LS.filter(c=>C[c]).map(face).join(""):"")+
   "</p></div>";
 bx.innerHTML=
  "<div class='rkbhd'><h2>Informações da Batalha</h2>"+
   "<button class='rkbx' aria-label='Fechar'>✕</button></div>"+
  "<div class='rkbgr'>"+
   "<div class='rkbcol eu'>"+lado(0)+"</div>"+
   "<div class='rkbmid'>"+
    "<div class='rkbvs'>"+
     "<div class='rkbp'>"+(medEu?"<img src='"+medEu+"' alt=''>":"")+"<b>"+eu+"</b></div>"+
     "<span class='rkbvsx'>VS</span>"+
     "<div class='rkbp'>"+(medOp?"<img src='"+medOp+"' alt=''>":"")+"<b>"+(x.opp||"Adversário")+"</b></div>"+
    "</div>"+
    "<p class='rkbid'>#"+String(x.id||"").replace(/^rk-/,"").slice(0,14)+"</p>"+
    "<p class='rkbrt'>Resultado</p>"+
    "<h3 class='rkbres "+(x.win?"v":"d")+"'>"+(x.win?"Vitória":"Derrota")+"</h3>"+
    "<p class='rkbsub'>Fila Ranqueada · "+rkQuando(x.at)+"</p>"+
    "<div class='rkchips rkbchips'>"+
     "<span class='rkch'>Pontos <b>"+x.prAnt+" → "+x.pr+"</b></span>"+
     "<span class='rkch'>Rank <b>"+RKN[(x.rank||1)-1]+" "+rkDivN(x.div||5)+"</b></span>"+
     (f&&f.t?"<span class='rkch'>Turnos <b>"+f.t+"</b></span>":"")+
     (fd?"<span class='rkch'>Campo <b>"+fd.n+"</b></span>":(f&&f.cf==="x"?"<span class='rkch'>Campo <b>Arena</b></span>":""))+
    "</div>"+
   "</div>"+
   "<div class='rkbcol op'>"+lado(1)+"</div>"+
  "</div>"+
  draftHtml+
  (pre.length?"<div class='rkbpre'><b>Banidos no draft</b><span>"+
    pre.map(c=>"<img src='"+(IMG[c+"_f"]||"")+"' alt='' title='"+shn(c)+"'>").join("")+"</span></div>":"")+
  "<div class='rkbft'></div>";
 bx.querySelector(".rkbx").onclick=fecha;
 const ft=bx.querySelector(".rkbft");
 if(f&&f.u&&f.u.length){const b=mk("button","lam lam-g","Ver estatísticas da partida");
  b.onclick=()=>{fecha();rkVerPartida(f,x.opp)};ft.append(b)}
 else ft.append(mk("p","rknada",f&&f.des?"A partida terminou no draft: não houve batalha.":"Esta partida é anterior ao histórico detalhado."));
 const v=mk("button","lam","Voltar");v.onclick=fecha;ft.append(v);
 ov.append(bx);document.body.append(ov);return ov}

/* ===== instalar o jogo como aplicativo =====
   O navegador avisa quando a instalação é possível, e esse aviso só pode ser
   usado uma vez, num clique de verdade. Por isso ele fica guardado aqui até o
   jogador apertar o botão. O iPhone não tem esse aviso: a Apple não deixa o
   site oferecer instalação, então lá mostramos o passo a passo. */
let PWAC=null;
const pwaInstalado=()=>{try{return !!(window.matchMedia&&matchMedia("(display-mode: standalone)").matches)||window.navigator.standalone===true}catch(e){return false}};
const pwaIOS=()=>{try{return /iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1)}catch(e){return false}};
/* dentro de um quadro (o link de testes) não existe instalação: nem oferece */
const pwaEmQuadro=()=>{try{return window.self!==window.top}catch(e){return true}};
const pwaPode=()=>!pwaInstalado()&&!pwaEmQuadro()&&(!!PWAC||pwaIOS());
if(typeof window!="undefined"){
 window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();PWAC=e;if(G.scr=="m")try{showMenu()}catch(x){}});
 window.addEventListener("appinstalled",()=>{PWAC=null;try{zToast("Jogo instalado. Agora ele abre direto pelo ícone.")}catch(x){}if(G.scr=="m")try{showMenu()}catch(x){}});
}
async function pwaInstala(){
 if(pwaIOS()&&!PWAC)return pwaAjudaIOS();
 if(!PWAC)return;
 const c=PWAC;PWAC=null;
 try{c.prompt();const r=await c.userChoice;
  if(r&&r.outcome!=="accepted"){PWAC=c;try{zToast("Sem problema. O botão continua aqui quando quiser.")}catch(e){}}
 }catch(e){PWAC=c}
 if(G.scr=="m")try{showMenu()}catch(e){}}
