function resPre(){const a=D.pre[0],b=D.pre[1];D.dup=a.filter(k=>b.includes(k));D.ex=[...new Set(a.concat(b))];D.pl=D.ex.filter(k=>!D.dup.includes(k));
 D.av=ROS.filter(k=>!D.ex.includes(k)).length;D.nb=Math.max(0,Math.min(2,Math.floor((D.av-8)/2)));D.noLead=D.pl.length?0:1;D.ph="prerev";D.who=0;D.hide=0;dRender()}
