async function oPoll(){const esp=(typeof D!="undefined"&&D&&D.spec)||O.seat==null;/* quem assiste busca o estado com mais frequência */
 if(!O.ref||O.busy||O.polling||Date.now()-(O.last||0)<(esp?1500:4000))return;const ref=O.ref;O.polling=1;try{const sn=await ref.get();if(ref!==O.ref||!sn.exists)return;const nd=sn.data();if(O.d&&JSON.stringify(nd)===JSON.stringify(O.d))return;O.d=nd;O.last=Date.now();oApply()}catch(e){}finally{O.polling=0}}
function oLeave(){if(O.ref&&O.d&&O.d.ph=="lobby"){const up={};OSL.forEach(k=>{if(O.d[k]===O.pid)up[k]=null});if(Object.keys(up).length){if(O.d.p0===O.pid||O.d.p1===O.pid){up.lr0=false;up.lr1=false;up.cd=0}O.ref.update(up).catch(()=>{})}}O.left=1;if(typeof D!="undefined"&&D&&D.on)D=null;if(O.unsub){try{O.unsub()}catch(e){}}O.unsub=null;O.ref=null;O.d=null;O.code="";O.seat=null;O.err="";O.msg="";O.ask=null;O.retry=null;clearTimeout(O.slowT);G.online=0;if(G.botPrev!=null)G.bot=G.botPrev}
/* o jogo abriu e havia uma partida em andamento: volta para ela sozinho */
async function oVolta(){try{
 const cod=roomCod();
 /* Antes isto desistia quando o jogador estava na tela do draft ou da partida
    - que e exatamente onde a conexao costuma cair. Agora o que importa e nao
    haver sala ligada: sem O.code, nao ha o que atrapalhar. */
 if(!cod||O.code||!O.db||!O.pid||O.voltando)return;
 if(G.win!=null&&G.scr!="d"&&G.scr!="p")return;
 const sn=await O.db.doc("rooms/"+cod).get();
 if(!sn||!sn.exists){roomEsquece();return}
 const d=sn.data()||{};let meu=(d.p0===O.pid)?0:(d.p1===O.pid)?1:null;
 if(d.ph!="draft"&&d.ph!="battle"){if(d.ph=="lobby"&&!d.rk)roomEsquece();return}
 if(txAcabou(d)){roomEsquece();return}
 /* O id da conta pode trocar entre uma carga e outra (entrou ou saiu da conta,
    perdeu o cache). Quando isso acontece o assento ainda e o mesmo jogador:
    o codigo da sala e o assento ficaram guardados aqui no aparelho, entao ele
    retoma o lugar em vez de ficar de fora da propria partida. */
 if(meu==null){const sv=roomSeat();
  if(sv=="0"||sv=="1"){const q=+sv,dono=d["p"+q];
   if(!dono||dono===O.pid||d.p0===dono&&d.p1===dono){meu=q}
   else{try{await O.db.doc("rooms/"+cod).update({["p"+q]:O.pid});meu=q}catch(e){}}}}
 if(meu==null)return;
 try{zToast("Reconectando à sua partida…")}catch(e){}
 O.voltando=1;try{dClear();G.mode="o";O.rkSala=0;ss("za_seat_"+cod,String(meu));oSub(cod)}finally{setTimeout(()=>{O.voltando=0},4000)}
 /* se em 9 segundos a partida nao abriu, a barra volta a aparecer com o botao */
 setTimeout(()=>{try{if(G.scr!="p"&&G.scr!="d")reconOlha()}catch(e){}},9000);
}catch(e){O.voltando=0}}
/* apaga a partida guardada: um lugar so, para nunca sobrar meia informacao */
/* a partida guardada ja terminou: nao ha para onde voltar */
function txAcabou(d){try{return !!(d&&d.st&&/"win":\s*[01]\b/.test(d.st))}catch(e){return 0}}
function roomEsquece(){try{ls("za_room",null);ls("za_room_seat",null)}catch(e){}try{sessionStorage.removeItem("za_room_t");sessionStorage.removeItem("za_room_seat_t")}catch(e){}try{reconBarra(0)}catch(e){}}
/* a partida em andamento fica guardada tambem na aba: se o navegador perder a gravacao ao recarregar, a volta ainda acha a sala */
function roomCod(){const c=ls("za_room");if(c)return c;try{return sessionStorage.getItem("za_room_t")||null}catch(e){return null}}
function roomSeat(){const c=ls("za_room_seat");if(c!=null)return c;try{return sessionStorage.getItem("za_room_seat_t")}catch(e){return null}}
/* o jogador pediu para voltar: desliga o que estiver pendurado e tenta de novo */
function oVoltaForce(){try{
 reconBarra(0);
 if(O.unsub){try{O.unsub()}catch(e){}}
 O.unsub=null;O.ref=null;O.d=null;O.code="";O.seat=null;O.voltando=0;O.left=0;O.err="";
 if(O.st!="ready"){oInit();return}
 oVolta();
}catch(e){}}
/* Barra "voltar para a partida": aparece fora da partida sempre que existe uma
   sala guardada que ainda esta no draft ou na batalha. E a saida de quem a
   reconexao automatica nao alcancou - navegador que bloqueia, aba restaurada
   sem rede, id da conta que trocou. */
function reconBarra(liga,txt){let b=document.getElementById("rcbar");
 if(!liga){if(b)b.remove();return}
 if(!b){b=mk("div","");b.id="rcbar";
  const t=mk("span","",txt||"Partida em andamento");
  const v=mk("button","","Voltar para a partida"),x=mk("button","rcx","✕");
  x.title="Dispensar";x.onclick=()=>{RCOFF=1;reconBarra(0)};
  v.onclick=()=>{reconBarra(0);oVoltaForce()};
  b.append(t,v,x);document.body.append(b)}
 else if(txt)b.querySelector("span").textContent=txt;}
let RCOFF=0,RCVER=0;
async function reconOlha(){try{
 if(RCOFF)return reconBarra(0);
 const cod=roomCod();
 if(!cod||!O.db||!O.pid){return reconBarra(0)}
 if(G.scr=="p"||G.scr=="d"){return reconBarra(0)}
 /* o jogador esta dentro desta sala (no lobby, por exemplo) e recebendo os dados: quem cuida dela e o oApply */
 if(O.code===cod&&O.d)return reconBarra(0);
 if(Date.now()-RCVER<5000)return;RCVER=Date.now();
 const sn=await O.db.doc("rooms/"+cod).get();
 if(!sn||!sn.exists){roomEsquece();return}
 const d=sn.data()||{};
 if(O.code===cod&&O.d)return reconBarra(0);
 if(d.ph!="draft"&&d.ph!="battle"){if(d.ph=="lobby"&&!d.rk)roomEsquece();else reconBarra(0);return}
 if(txAcabou(d)){roomEsquece();return}
 const sv=roomSeat(),meu=(d.p0===O.pid)?0:(d.p1===O.pid)?1:(sv=="0"||sv=="1"?+sv:null);
 if(meu==null){roomEsquece();return}
 reconBarra(1,d.ph=="draft"?"Draft em andamento":"Partida em andamento");
}catch(e){}}
/* Fica de olho: enquanto houver uma partida guardada e nenhuma sala ligada,
   tenta voltar sozinho. Cobre o draft, a apresentacao dos times e a batalha. */
function oVoltaVigia(){
 if(O.vigia)return;
 O.vigia=setInterval(()=>{try{
  if(!O.db||!O.pid)return;
  if(!roomCod()){reconBarra(0);return}
  if(G.scr=="p"||G.scr=="d"){reconBarra(0);return}
  if(!O.code&&!O.voltando)oVolta();
  reconOlha();
 }catch(e){}},6000);
 ["online","focus"].forEach(ev=>{try{addEventListener(ev,()=>{
  try{if(!O.code&&roomCod())oVolta()}catch(e){}},{passive:true})}catch(e){}});
 try{document.addEventListener("visibilitychange",()=>{
  if(document.visibilityState==="visible"){try{if(!O.code&&roomCod())oVolta()}catch(e){}}},{passive:true})}catch(e){}}
/* ===== Transmissao de partida local =====
   Quem cai contra um bot na fila, treina ou joga offline nao tem sala nenhuma
   no servidor - e era por isso que o amigo nao conseguia assistir. Agora o jogo
   abre uma sala de leitura com o estado da partida e publica o codigo dela na
   presenca: o amigo entra como espectador pelo mesmo caminho das partidas
   online. A sala so nasce quando ha algum amigo online, e morre com a partida. */
const TX={code:"",env:"",seq:0,mand:0,criando:0,fim:0};
function frAmigoOn(){try{const n=Date.now();return Object.keys(FR.pres||{}).some(k=>{const q=FR.pres[k];return q&&n-(q.at||0)<FRGAP})}catch(e){return 0}}
function txNomeOp(){try{
 if(G.rkm&&G.rkm.oppNome)return String(G.rkm.oppNome).slice(0,24);
 if(typeof G.rkNome=="string"&&G.rkNome)return String(G.rkNome).slice(0,24);
 return G.bot?"Jogador 2":"Jogador 2"}catch(e){return "Jogador 2"}}
/* draft local (contra o bot da ranqueada, por exemplo) ou batalha local */
const txDraft=()=>{try{return !G.online&&G.scr=="d"&&typeof D!="undefined"&&D&&!D.on&&!!D.ph}catch(e){return false}};
function txViva(){try{return txDraft()||(!G.online&&G.scr=="p"&&G.u&&G.u.length>0)}catch(e){return 0}}
/* abre com qualquer amigo na lista: quem entra no meio da partida tambem consegue assistir */
function txDeveLigar(){try{return !!(txViva()&&G.win==null&&O.db&&O.pid&&((FR.list&&FR.list.length)||frAmigoOn()))}catch(e){return 0}}
/* o que vai para a sala: o draft no mesmo formato do draft online, ou o estado da batalha */
const TXDR=["ph","fd","fv","pre","pl","dup","ex","bans","picks","lead","lban","fb","nl","seq","si","bf","nb","av","noLead","ann","act"];
function txCarga(){
 if(txDraft()){const R={cfg:Object.assign({},CFGD)};TXDR.forEach(k=>{if(D[k]!==undefined)R[k]=D[k]});
  if(!D._txd)D._txd="tx"+Date.now().toString(36);
  return {ph:"draft",dr:JSON.stringify(R),did:D._txd,rd0:false,rd1:false,b0:"",b1:"",st:"",gid:"",
   _t:Math.max(0,+D.t||0)}}
 return {ph:"battle",st:ser(),gid:G.gid||"",dr:""}}
const txChave=c=>JSON.stringify(Object.assign({},c,{_t:0}));
async function txAbre(){if(TX.code||TX.criando)return;TX.criando=1;
 try{let code,ok=0;
  for(let i=0;i<5&&!ok;i++){code=newCode();const sn=await O.db.doc("rooms/"+code).get();ok=!sn.exists}
  if(ok){const op="tx"+Math.random().toString(36).slice(2,10),cg=txCarga(),st=cg.st;
   await O.db.doc("rooms/"+code).set({v:2,tx:1,host:O.pid,p0:O.pid,p1:op,
    s0:null,s1:null,s2:null,s3:null,s4:null,s5:null,
    mem:{[okey(O.pid)]:oMeMem(),[okey(op)]:Object.assign({n:txNomeOp()},(()=>{const x=rkBotMxPac();return x?{mx:x}:{}})(),(()=>{const b=pfBot();return b?{pf:b}:{}})())},
    ru:JSON.stringify({m:"p"}),lr0:false,lr1:false,cp0:"",cp1:"",cd:0,t0:"",t1:"",r0:false,r1:false,
    fd:G.cf||"r",ph:cg.ph,st:st,dr:cg.dr,did:cg.did||"",rd0:false,rd1:false,b0:"",b1:"",
    dseq:1,dms:(cg._t||0)*1000,seq:1,gid:cg.gid,at:Date.now()});
   TX.code=code;TX.seq=1;TX.env=txChave(cg);TX.fim=0;try{frPres()}catch(e){}}
 }catch(e){}
 TX.criando=0}
async function txManda(){if(!TX.code||TX.mand)return;let cg;try{cg=txCarga()}catch(e){return}
 const ch=txChave(cg);if(ch===TX.env)return;TX.mand=1;const n=TX.seq+1;
 const up={ph:cg.ph,st:cg.st,dr:cg.dr,gid:cg.gid,seq:n,dseq:n,at:Date.now()};
 if(cg.ph=="draft"){up.did=cg.did;up.dms=(cg._t||0)*1000;up.rd0=false;up.rd1=false;up.b0="";up.b1=""}
 try{await O.db.doc("rooms/"+TX.code).update(up);TX.seq=n;TX.env=ch}catch(e){}
 TX.mand=0}
async function txApaga(){const c=TX.code;if(!c)return;TX.code="";TX.env="";TX.seq=0;TX.fim=0;
 try{frPres()}catch(e){}
 try{await O.db.doc("rooms/"+c).delete()}catch(e){try{await O.db.doc("rooms/"+c).update({ph:"lobby",st:"",at:Date.now()})}catch(e2){}}}
function txTick(){if(!O.db||!O.pid)return;
 if(txDeveLigar()){if(!TX.code)txAbre();else txManda();return}
 if(!TX.code)return;
 /* acabou: manda o resultado e deixa a sala viva por mais um pouco, para quem
    estava assistindo ver o fim */
 if(txViva()&&G.win!=null){txManda();if(!TX.fim){TX.fim=1;setTimeout(()=>{try{txApaga()}catch(e){}},25000)}return}
 txApaga()}

/* ===== Batalha limpa =====
   Uma flechinha no canto esconde os botoes flutuantes da batalha. No celular a
   partida ja comeca com eles escondidos; a flecha mostra uma bolinha quando
   chega mensagem no chat. */
function hudSet(min){try{document.body.classList.toggle("hudmin",!!min);const t=document.getElementById("hudtg");
 if(t){t.textContent=min?"›":"‹";t.title=min?"Mostrar os botões":"Esconder os botões";t.setAttribute("aria-label",t.title)}}catch(e){}}
function hudIni(){if(document.getElementById("hudtg"))return;
 const t=document.createElement("button");t.id="hudtg";t.type="button";
 t.onclick=e=>{e.stopPropagation();hudSet(!document.body.classList.contains("hudmin"))};
 document.body.append(t);hudSet(document.body.classList.contains("hudmin"));
 /* ao entrar numa partida (o corpo da pagina ganha a classe "bt"), no celular comeca escondido */
 let emBt=document.body.classList.contains("bt");
 new MutationObserver(()=>{const b=document.body.classList.contains("bt");
  if(b&&!emBt&&(document.body.classList.contains("ph")||document.body.classList.contains("php")))hudSet(1);emBt=b}).observe(document.body,{attributes:true,attributeFilter:["class"]});
 setInterval(()=>{try{t.classList.toggle("nv",document.body.classList.contains("hudmin")&&typeof CH!="undefined"&&CH.unread>0)}catch(e){}},1500)}
try{if(document.body)hudIni();else document.addEventListener("DOMContentLoaded",hudIni)}catch(e){}

/* ===== Atualizacao obrigatoria (so no site) =====
   O site publica versao.json com a versao no ar; a pagina sabe a propria
   (window.ZA_VER, carimbada no build). Se mudar, o jogador tem de recarregar:
   na hora, se estiver fora de partida; ou quando a partida dele terminar.
   No link de testes nao existe ZA_VER e nada disso liga. */
let ATZ=0,ATZFIM=0;
async function atzChecar(){try{if(!window.ZA_VER||ATZ)return;
 const r=await fetch("versao.json?t="+Date.now(),{cache:"no-store"});if(!r.ok)return;
 const j=await r.json();if(j&&j.v&&j.v!==window.ZA_VER){ATZ=1;atzTalvez()}}catch(e){}}
function atzEmJogo(){try{
 if(G.scr=="d")return true;
 if(G.scr=="p"){if(G.win==null){ATZFIM=0;return true}
  /* acabou: deixa ver o resultado (e a ranqueada registrar) antes */
  if(!ATZFIM)ATZFIM=Date.now();return Date.now()-ATZFIM<12000}
 if(typeof RKQ!="undefined"&&RKQ.on)return true;               /* procurando partida */
 if(typeof O!="undefined"&&O.code&&O.d&&(O.d.ph=="draft"||O.d.ph=="battle"))return true;
 return false}catch(e){return false}}
function atzTalvez(){if(atzEmJogo()){setTimeout(atzTalvez,3000);return}atzMostra()}
function atzMostra(){if(document.getElementById("atzov"))return;
 const ov=document.createElement("div");ov.id="atzov";const b=mk("div","surbox nim");
 b.append(mk("div","surt","Nova atualização disponível"),
  mk("p","surp","O Projeto Ânima foi atualizado. Atualize a página para continuar jogando."));
 const bt=mk("div","qobt"),y=mk("button","qok","Atualizar agora");bt.append(y);b.append(bt);ov.append(b);
 y.onclick=async()=>{y.disabled=true;y.textContent="Atualizando…";
  try{const rg=await navigator.serviceWorker.getRegistration();if(rg)await Promise.race([rg.update(),new Promise(r=>setTimeout(r,3000))])}catch(e){}
  location.reload()};
 /* ela cobre a tela inteira; o clique nela nao chega ao jogo */
 ov.onclick=e=>e.stopPropagation();
 document.body.append(ov);try{y.focus()}catch(e){}}
try{if(window.ZA_VER){setTimeout(atzChecar,8000);setInterval(atzChecar,60000);
 document.addEventListener("visibilitychange",()=>{if(!document.hidden)atzChecar()});
 addEventListener("focus",atzChecar);addEventListener("online",atzChecar)}}catch(e){}

/* ===== Nao sair sem querer =====
   No celular o botao Voltar do aparelho fechava o jogo na hora. Agora o jogo
   mantem um passo extra no historico: quando o Voltar e apertado, esse passo e
   consumido, o jogo repoe o passo e pergunta antes de deixar sair. No PC vale o
   mesmo para o Voltar do navegador, e fechar a aba ou recarregar durante uma
   partida pede a confirmacao do proprio navegador.
   Minimizar nao da para interceptar (nenhuma pagina recebe esse aviso); o que o
   jogo faz nesse caso e voltar para a partida sozinho quando a tela reaparece. */
let SAIRON=0,SAIRQ=0;
function emPartidaViva(){try{return (G.scr=="p"||G.scr=="d"||G.scr=="b")&&G.win==null}catch(e){return 0}}
function askSaida(){if(SAIRQ)return;SAIRQ=1;
 const dentro=emPartidaViva();
 askConf("Sair do jogo?",
  dentro?"Sua partida continua em andamento. Se sair agora, o tempo do turno não para, e se você não voltar em 1 minuto perde a partida."
        :"Você vai fechar o Projeto Ânima e voltar para a página anterior.",
  dentro?"Sair mesmo assim":"Sair",
  ()=>{SAIRQ=0;SAIRON=0;try{removeEventListener("popstate",sairPop)}catch(e){}
   try{history.go(-2)}catch(e){try{history.back()}catch(e2){}}},
  ()=>{SAIRQ=0})}
function sairPop(){
 /* o passo extra acabou de ser consumido: repoe antes de qualquer coisa */
 try{history.pushState({za:1},"",location.href)}catch(e){}
 /* se havia uma caixa aberta, o Voltar serve para fechar ela */
 if(document.getElementById("atzov"))return;
 const o=document.getElementById("surc");
 if(o&&!SAIRQ){o.remove();return}
 askSaida()}
function sairGuarda(){if(SAIRON)return;SAIRON=1;
 try{history.pushState({za:1},"",location.href)}catch(e){SAIRON=0;return}
 try{addEventListener("popstate",sairPop)}catch(e){}
 try{addEventListener("beforeunload",e=>{if(!emPartidaViva())return;e.preventDefault();e.returnValue=""})}catch(e){}}
function oSub(code){O.eaSeen=undefined;if(O.unsub){try{O.unsub()}catch(e){}}O.code=code;O.ref=O.db.doc("rooms/"+code);O.d=null;O.slow=0;clearTimeout(O.slowT);O.slowT=setTimeout(()=>{if(!O.d){O.slow=1;oRender()}},10000);
 O.unsub=O.ref.onSnapshot(sn=>{O.last=Date.now();O.slow=0;O.busy=0;clearTimeout(O.slowT);if(!sn.exists){O.d=null;O.err="Essa sala não existe mais.";return oRender()}const nd=sn.data();if(O.d&&JSON.stringify(nd)===JSON.stringify(O.d))return;O.d=nd;oApply()},e=>{O.err="A conexão com a sala caiu ("+(e&&e.code||"erro")+"). Saia e entre de novo.";oRender()})}
function oApply(){const d=O.d;if(!d)return;if(O.eaSeen===undefined)O.eaSeen=d.ea||"";if(d.ea&&d.ea!==O.eaSeen){O.eaSeen=d.ea;endClose();if(d.ea.startsWith("menu")){oLeave();return showMenu()}}
 {const a0=d.p0===O.pid,a1=d.p1===O.pid,sv=ss("za_seat_"+O.code);if(a0&&a1){if(sv=="0"||sv=="1"){O.seat=+sv;O.ask=null}else O.ask="seat"}else{O.ask=null;O.seat=a0?0:a1?1:null}}
 O.inRoom=OSL.some(k=>d[k]===O.pid);
 if(O.seat!=null)ss("za_seat_"+O.code,String(O.seat));
 /* a sala fica guardada enquanto a partida existe - antes isso era escrito so
    na entrada, e quem entrava por outro caminho (a fila monta a sala no
    servidor) ficava sem o registro e nao tinha para onde voltar */
 if(O.seat!=null&&(d.ph=="draft"||d.ph=="battle")){try{if(ls("za_room")!==O.code)ls("za_room",O.code);if(ls("za_room_seat")!==String(O.seat))ls("za_room_seat",String(O.seat));RCOFF=0}catch(e){}try{if(sessionStorage.getItem("za_room_t")!==O.code||sessionStorage.getItem("za_room_seat_t")!==String(O.seat)){sessionStorage.setItem("za_room_t",O.code);sessionStorage.setItem("za_room_seat_t",String(O.seat))}}catch(e){}}
 G.me=O.seat==null?-1:O.seat;
 /* sala da fila ranqueada: entrou ou voltou, a partida continua valendo rank */
 if(d.rk&&d.rkp&&O.seat!=null&&(!G.rkm||G.rkm.id!==d.rkp)){const q=1-O.seat,me=rkLoad();
  G.rkm={id:d.rkp,oppMmr:+d["mm"+q]||RKCFG.mmr0,oppNome:oName(d,d["p"+q]),bot:0,pop:null,
   sea:me.sea,mmrAnt:me.mmr,oppRank:+d["rr"+q]||null,oppDiv:+d["rd"+q]||null,
   oppPc:(+d["rp"+q]>=0?+d["rp"+q]:null)};
  try{ls("za_room",O.code)}catch(e){}}
 /* sala da Fila Casual: cada jogador publica o proprio nome e perfil nela, como na ranqueada */
 if(d.cs&&d.ph=="lobby")try{rkPubNome(d)}catch(e){}
 if(!O.inRoom&&d.ph=="lobby"&&!O.claiming&&!O.left){O.claiming=1;oClaimSlot().finally(()=>{O.claiming=0})}
 if(oIsHost()&&d.ph=="lobby"&&!O.busy){const all=d.p0&&d.p1&&d.lr0&&d.lr1;if(all&&!d.cd){O.busy=1;O.ref.update({cd:Date.now()+3600}).then(oAfterWrite,()=>{O.busy=0})}else if(!all&&d.cd){O.busy=1;O.ref.update({cd:0}).then(oAfterWrite,()=>{O.busy=0})}}
 if(d.ph=="battle"&&d.st&&(O.seat!=null||O.inRoom)&&!(O.seat==null&&O.specOut&&O.specOut===d.gid)){if(d.gid===G.gid&&(d.seq||0)===(G.seq||0)&&!O.bst&&d.st)O.bst=d.st;
  if(d.gid!==G.gid||(d.seq||0)>(G.seq||0)){const nw=d.gid!==G.gid;
   /* reconectou com a partida ja andada: a apresentacao dos times sai da frente */
   if(!nw&&G.inOn)try{inEnd()}catch(e){}
   /* a jogada do adversario so vale se for possivel: refaz o turno aqui e compara */
   /* o comeco da batalha tambem e conferido: o lider da sala nao escolhe vida, Ecos ou times diferentes do draft */
   if(nw&&(O.seat===0||O.seat===1)&&d.dr&&OVAL.modo=="on"&&!(O.iniOk===d.gid)){const why=oIniValida(d);O.iniOk=d.gid;
    if(why){OVAL.log.push({t:0,seq:d.seq,why});try{console.warn("[anima] comeco recusado: "+why)}catch(e){}
     O.bst=d.st;des(d.st);G.gid=d.gid;G.seq=d.seq||0;G.me=O.seat;G.online=1;G.scr="p";return oInvalida(d,why)}}
   if(!nw&&(G.me===0||G.me===1)&&O.seat===G.me&&O.bst){const why=oValida(d);
    if(why){OVAL.log.push({t:G.t,seq:d.seq,why});if(OVAL.log.length>40)OVAL.log.shift();try{console.warn("[anima] jogada recusada: "+why)}catch(e){}
     if(why==="fim")return;
     if(OVAL.modo=="on")return oInvalida(d,why)}}
   des(d.st);G.seq=d.seq||0;O.bst=d.st;if(nw&&G.t<=1&&!G.log.some(l=>/ usa | → /.test(l.m||""))){G.intro=1;G.annB=1}}G.me=O.seat==null?-1:O.seat;G.online=1;G.scr="p";try{prgComeca()}catch(e){}const lvL=(G.me<0&&!(frAssistindo()&&frAmgSeat()>=0&&G.cur!==frAmgSeat()))?lvPre(d.lv):null;render();try{frFaixa()}catch(e){}if(lvL)lvUI(lvL);else if(G.me<0){const q=document.getElementById("qord");if(q)q.remove();const pv=document.querySelector(".pvov");if(pv)pv.remove();LVK=""}return}
 if(d.ph=="draft"&&d.dr&&(O.seat!=null||O.inRoom)){
  /* conferencia do passo do draft que veio do outro aparelho */
  if((O.seat===0||O.seat===1)&&OVAL.modo=="on"&&d.p1!==OBOT&&d.p0!==OBOT){const V=O.drV,mine=d.dr===O.drMine;let why="";
   if(!mine){try{const N=JSON.parse(d.dr),J=x=>JSON.stringify(x);
    /* draft novo: so o comeco de verdade (nada escolhido ainda) e conferido; quem entra no meio (recarregou) so confere dali em diante */
    if(!V||V.did!==d.did){const novo=J(N.picks)=="[[],[]]"&&J(N.bans)=="[[],[]]"&&J(N.fv)=="[[],[]]"&&J(N.pre)=="[[],[]]"&&!N.si;if(novo)why=oDrInicioValida(d,N)}
    else if((d.dseq||0)===V.dseq+1&&V.dr!==d.dr)why=oDrValida(JSON.parse(V.dr),N,d);
    /* chegou mais de um passo de uma vez (a conexao pulou uma versao): confere o draft inteiro */
    else if((d.dseq||0)>V.dseq+1)why=oDrEstrutura(JSON.parse(V.dr),N);
    if(!why&&(!V||V.did!==d.did))why=oDrEstrutura(null,N)}catch(e){why=""}}
   O.drV={did:d.did,dseq:d.dseq||0,dr:d.dr};
   if(why)return oDrInvalido(d,why)}
  G.online=1;G.bot=0;const skip=oDview(d);O.R=D;
  if(!skip){G.scr="d";dRender()}
  const R=JSON.parse(d.dr);if(O.seat===0&&BLIND.includes(R.ph)&&oNeed(R).every(t=>d["b"+t])){const ds=d.dseq;setTimeout(()=>{if(O.d&&O.d.dseq===ds&&!O.busy){const R2=JSON.parse(O.d.dr);const ms=oResolve(R2,[O.d.b0,O.d.b1]);oWriteR(R2,ms)}},600)}
  return}
 if((G.scr=="p"||G.scr=="d")&&G.online){G.online=0;G.scr="o";if(D&&D.on)D=null}
 if(G.scr=="o")oRender()}
function newCode(){let c="";for(let i=0;i<5;i++)c+=OCH[Math.floor(Math.random()*OCH.length)];return c}
async function oCreate(){O.err="";O.msg="Criando sala…";oRender();try{let code,ok=0;for(let i=0;i<5&&!ok;i++){code=newCode();const s=await O.db.doc("rooms/"+code).get();ok=!s.exists}
  await O.db.doc("rooms/"+code).set({v:2,host:O.pid,p0:O.pid,p1:null,s0:null,s1:null,s2:null,s3:null,s4:null,s5:null,mem:{[okey(O.pid)]:oMeMem()},ru:JSON.stringify({m:"p"}),lr0:false,lr1:false,cp0:"",cp1:"",cd:0,t0:"",t1:"",r0:false,r1:false,fd:"r",ph:"lobby",st:"",seq:0,gid:"",at:Date.now()});
  ls("za_room",code);O.seat=0;ss("za_seat_"+code,"0");O.msg="";O.team=[null,null,null,null];oSub(code)}catch(e){O.msg="";if(termosErro(e)){O.err="Aceite os Termos de Uso para jogar online.";oRender();termosRecusa();return}O.err=e&&e.code=="invalid_argument"?"Você não tem permissão para criar salas nesta página. O dono precisa te convidar como Editor.":"Não foi possível criar a sala ("+(e&&e.code||"erro")+").";oRender()}}
async function oJoin(code){code=(code||"").toUpperCase().replace(/[^A-Z0-9]/g,"");if(code.length<4){O.err="Digite o código da sala.";return oRender()}
 O.err="";O.msg="Procurando a sala…";oRender();try{const ref=O.db.doc("rooms/"+code),s=await ref.get();O.msg="";
  if(!s.exists){O.err="Sala "+code+" não encontrada. Confira o código.";return oRender()}
  const d=s.data();O.seat=null;O.ask=null;O.left=0;
  if(!OSL.some(k=>d[k]===O.pid)){const f=OSL.find(k=>!d[k]);if(!f){O.err="A sala "+code+" está cheia (2 jogadores e 6 espectadores).";return oRender()}
   await ref.update({[f]:O.pid,mem:oMemJunta(Object.assign({},s.data(),{[f]:O.pid}),O.pid,oMeMem())})}else await ref.update({mem:oMemJunta(s.data(),O.pid,oMeMem())});
  ls("za_room",code);O.team=[null,null,null,null];oSub(code)}catch(e){O.msg="";if(termosErro(e)){O.err="Aceite os Termos de Uso para jogar online.";oRender();termosRecusa();return}O.err=e&&e.code=="invalid_argument"?"Você pode ver esta página, mas não jogar online: o dono precisa te convidar como Editor.":"Não foi possível entrar ("+(e&&e.code||"erro")+").";oRender()}}
async function oClaim2(){try{await O.ref.update({p1:O.pid});ss("za_seat_"+O.code,"0");oApply();oRender()}catch(e){if(termosErro(e)){O.err="Aceite os Termos de Uso para jogar online.";oRender();termosRecusa();return}O.err="Não foi possível entrar como Jogador 2.";oRender()}}
function oPickSeat(s){O.seat=s;O.ask=null;ss("za_seat_"+O.code,String(s));oApply();oRender()}
async function oBack(){try{await O.ref.update({ph:"lobby",r0:false,r1:false,lr0:false,lr1:false,cd:0,note:""})}catch(e){O.err="Não foi possível voltar à sala.";render()}}
async function oPush(){if(!G.online||!O.ref)return;const body={st:ser(),seq:(G.seq||0)+1,pv:(G.seq||0),ac:OAC?JSON.stringify(OAC):"",at:Date.now()};OAC=null;O.meuUlt={base:O.bst,st:body.st,ac:body.ac,pv:body.pv};G.seq=body.seq;O.bst=body.st;O.retry=body;O.sending=1;render();
 try{await O.ref.update(body);O.retry=null;O.err=""}catch(e){O.err="A jogada não foi enviada ("+(e&&e.code||"erro")+"). Toque em Reenviar."}O.sending=0;render()}
async function oResend(){if(!O.retry)return;O.sending=1;render();try{await O.ref.update(O.retry);O.retry=null;O.err=""}catch(e){O.err="Ainda não foi possível enviar. Verifique a conexão e tente de novo."}O.sending=0;render()}
function oConcede(){if(!G.online||G.win!=null)return;oAcMarca("rend",G.me);mtQuit=1;G.win=1-G.me;G.q=[];G.sel=null;log(pn(G.me)+" se rendeu");oPush()}
/* ===== Relógio do turno: 60s, e menos a cada turno que o jogador deixa passar ===== */
const TCFG=[60,40,20,10];
let TMR={ch:"",fim:0,av:0};
/* de quem e a vez do lado deste aparelho: online vem do assento da sala, e na
   partida local quem joga e sempre o assento 0 */
function tEu(){return G.online?G.me:0}
function tAtiva(){try{
 if(G.scr!="p"||G.win!=null)return false;
 /* a ranqueada contra bot roda local, mas vale pontos da temporada: tem relogio
    igual ao das salas. So no turno do jogador, porque o bot joga sozinho. */
 if(!G.online)return !!(rkEmJogo()&&G.bot&&G.cur===0);
 return !!(G.me>=0&&O.d&&O.d.ph=="battle"&&oBotSeat()!==G.cur)}catch(e){return false}}
function tSeg(s){const f=(G.afk&&G.afk[s])||0;return TCFG[Math.min(TCFG.length-1,f)]}
function tZera(s){G.afk=(G.afk||[0,0]).slice();G.afk[s]=0}
function tFalta(s){G.afk=(G.afk||[0,0]).slice();G.afk[s]=Math.min(9,(G.afk[s]||0)+1)}
function tPinta(){const el=document.getElementById("tmrb");if(!el)return;
 if(!TMR.fim||!tAtiva()){el.hidden=true;cdPara();return}
 const n=Math.max(0,Math.ceil((TMR.fim-Date.now())/1000));
 el.hidden=false;el.className="tmrb"+(n<=10?" tmrx":n<=20?" tmry":"");
 el.innerHTML="<small>"+(G.cur===tEu()?"Seu tempo":"Tempo de "+pn(G.cur))+"</small><b>"+n+"s</b>";
 if(G.cur===tEu())cdAviso("t"+TMR.ch,n);else cdPara()}
function tCheca(){
 if(!tAtiva()){if(TMR.ch){TMR.ch="";TMR.fim=0;tPinta()}cdPara();return}
 const ch=G.gid+"|"+G.t+"|"+G.cur;
 if(ch!==TMR.ch){TMR.ch=ch;TMR.av=0;
  /* quem está só esperando dá uma folga, para o próprio jogador passar o turno primeiro */
  TMR.fim=Date.now()+tSeg(G.cur)*1000+(G.cur===tEu()?0:6000)}
 tPinta();
 if(Date.now()<TMR.fim||TMR.av||O.sending||O.retry)return;
 if(G.inOn||G.g2v||(G.holdT||0)>Date.now())return;
 TMR.av=1;tEstoura()}
function tEstoura(){try{
 if(!tAtiva())return;
 const s=G.cur,n=G.q.length;
 G.sel=null;   /* habilidade escolhida sem alvo nao entra na jogada */
 oAcMarca("tempo",G.me);
 tFalta(s);
 log((s===tEu()?"Você":pn(s))+" demorou demais: o turno passou"+(n?" com "+n+" habilidade"+(n>1?"s":"")+" já escolhida"+(n>1?"s":""):" sem jogar"));
 try{zToast(s===tEu()?"Tempo esgotado: o turno passou.":"O tempo de "+pn(s)+" acabou.")}catch(e){}
 _endTurn();oPush()
}catch(e){}}
if(typeof setInterval=="function")setInterval(()=>{try{tCheca()}catch(e){}},250);
let LVL="",LVT=0,LVK="";
function lvState(){if(!G.online||G.me<0||G.cur!==G.me||G.win!=null||G.scr!="p")return null;const ix=x=>G.u.indexOf(x);
 const q=G.q.map(a=>({u:ix(a.u),i:a.i,t:a.t?ix(a.t):-1,ts:(a.ts||[]).map(ix),z:a.z||0,o:a.o||0}));
 const s=G.sel?{u:ix(G.sel.u),i:G.sel.i,z:G.sel.z||0,ts:(G.sel.ts||[]).map(ix),o:G.sel.o||0}:null;
 return JSON.stringify({g:G.gid,t:G.t,c:G.cur,q,s,ui:document.getElementById("qord")?"o":document.querySelector(".pvov")?"p":""})}
function lvSend(){try{const d=O.d;if(!d||!O.ref||!G.online||G.me<0)return;if(!["s0","s1","s2","s3","s4","s5"].some(k=>d[k]))return;const v=lvState();if(v==null||v===LVL)return;clearTimeout(LVT);LVT=setTimeout(()=>{const v2=lvState();if(v2==null||v2===LVL||!O.ref)return;LVL=v2;O.ref.update({lv:v2}).catch(()=>{LVL=""})},220)}catch(e){}}
function lvPre(v){if(!v||G.win!=null)return null;let L;try{L=JSON.parse(v)}catch(e){return null}if(L.g!==G.gid||L.t!==G.t||L.c!==G.cur)return null;const U=i=>G.u[i];
 G.q=L.q.map(a=>Object.assign({u:U(a.u),i:a.i,o:a.o},a.t>=0?{t:U(a.t)}:{},a.ts&&a.ts.length?{ts:a.ts.map(U)}:{},a.z?{z:a.z}:{})).filter(a=>a.u);
 G.sel=L.s&&U(L.s.u)?Object.assign({u:U(L.s.u),i:L.s.i,o:L.s.o},L.s.z?{z:L.s.z}:{},L.s.ts&&L.s.ts.length?{ts:L.s.ts.map(U)}:{}):null;L._v=v;return L}
function lvUI(L){const ord=document.getElementById("qord"),pv=document.querySelector(".pvov");
 if(L.ui=="o"){if(!ord||LVK!==L._v)openOrder()}else if(ord)ord.remove();
 if(L.ui=="p"){if(!pv||LVK!==L._v){if(pv)pv.remove();showPredict()}}else if(pv)pv.remove();LVK=L._v}
if(typeof setInterval=="function")setInterval(()=>{if(G.online&&G.me>=0&&G.scr=="p")lvSend()},400);
const _endTurn=endTurn;endTurn=function(){if(G.online&&(G.cur!==G.me||O.sending||O.retry))return;if(G.online){oAcMarca("t",G.me);tZera(G.cur)}const w=G.win;_endTurn();if(G.online&&(G.win!==w||G.scr=="p"))oPush()};


/* ===== PvP: a jogada que chega e conferida antes de valer =====
   Quem termina o turno manda junto o que fez (ac): a fila de habilidades e o que mudou
   antes de rodar o turno (escolhas como a do "Morra por mim!"). Quem recebe parte do
   ultimo estado que os dois tinham (O.bst), refaz o turno com o mesmo motor e o mesmo
   sorteio e compara o resultado. Habilidade em recarga, sem Energia, fora da vez, vida
   ou Energia mexidas: nao bate, e a jogada e recusada. OVAL.modo "on" encerra a
   partida com vitoria de quem recebeu; "obs" so anota (OVAL.log). */
const OVAL={modo:"on",log:[]};
let OAC=null;
/* campos do personagem que nao contam (so tela: numeros flutuantes e marcas de animacao) */
const OVSKIPU={sx:1,sxk:1};
/* o que pode mudar antes do turno rodar (escolhas feitas na tela, fora da fila) */
const OVPREU={bjp:1};
function oAcQ(){const ix=x=>G.u.indexOf(x),un=v=>v&&typeof v=="object"&&G.u.includes(v)?{__u:ix(v)}:v;
 return (G.q||[]).map(a=>{const o={};Object.keys(a).forEach(k=>{const v=a[k];
  if(Array.isArray(v))o[k]=v.map(un);else if(v&&typeof v=="object"){if(G.u.includes(v))o[k]={__u:ix(v)}}
  else if(typeof v!="function")o[k]=v});
  /* Kaioken do lider Goku Blue marcado no botao: vai junto com a jogada */
  try{if(G.kkc&&G.kkc[kkKey(a.u,a.i)])o.kk=1}catch(e){}return o})}
function oAcQDes(L){const un=v=>v&&typeof v=="object"&&v.__u!=null?G.u[v.__u]:v;
 return (Array.isArray(L)?L:[]).map(a=>{const o={};Object.keys(a||{}).forEach(k=>{const v=a[k];o[k]=Array.isArray(v)?v.map(un):un(v)});return o})}
function oAcPre(){try{if(!O.bst)return null;const A=JSON.parse(O.bst),B=JSON.parse(ser()),d={};
 Object.keys(B).forEach(k=>{if(k=="log"||k=="u"||k=="sth"||k=="lk")return;if(JSON.stringify(A[k])!==JSON.stringify(B[k]))d[k]=B[k]});
 const du={};(B.u||[]).forEach((x,i)=>{const y=(A.u||[])[i]||{};Object.keys(x).forEach(k=>{if(OVSKIPU[k])return;if(oCanon(x[k])!==oCanon(y[k]))(du[i]=du[i]||{})[k]=x[k]})});
 if(Object.keys(du).length)d.u=du;return d}catch(e){return null}}
function oAcMarca(k,by){try{OAC={k,by,q:k=="rend"?[]:oAcQ(),pre:k=="rend"?null:oAcPre()}}catch(e){OAC={k,by,q:[],pre:null}}}
/* compara o que importa para a partida */
/* referencia a um personagem dentro de um efeito: {"__u":n} e n sao o mesmo personagem */
const oCanon=v=>JSON.stringify(v==null?null:v).replace(/\{"__u":(-?\d+)\}/g,"$1");
function oDifere(A,B){const L=[];
 ["t","cur","win","ki","zk","zg","tc","afk","sbcd","lvki","cpsv","kz","zs","zd","dr","lead","cf","rs","porTempo"].forEach(k=>{if(JSON.stringify(A[k]==null?null:A[k])!==JSON.stringify(B[k]==null?null:B[k]))L.push(k)});
 const ua=A.u||[],ub=B.u||[];if(ua.length!==ub.length)L.push("u.n");
 ua.forEach((x,i)=>{const y=ub[i]||{};new Set(Object.keys(x).concat(Object.keys(y))).forEach(k=>{if(OVSKIPU[k])return;
  if(oCanon(x[k])!==oCanon(y[k]))L.push("u"+i+"."+k)})});
 return L}
/* refaz a jogada recebida a partir da base. Devolve "" (vale) ou o motivo */
function oValida(d,euQ){let a=null;try{a=typeof d.ac=="string"?(d.ac?JSON.parse(d.ac):null):d.ac}catch(e){a=null}
 if(!a||typeof a!="object")return "sem_acao";
 let A,N;try{A=JSON.parse(O.bst);N=JSON.parse(d.st)}catch(e){return "estado"}
 if(A.gid!==N.gid)return "";
 const eu=euQ==null?G.me:euQ,ele=1-eu,bot=oBotSeat(d);
 /* o adversario diz que a minha ultima jogada nao valia: so aceita se ela de fato nao valia */
 /* a partida ja acabou aqui: acusacao depois do fim nao muda nada (e nao responde, para nao virar pingue-pongue) */
 if((a.k=="inval"||a.k=="aband")&&A.win!=null)return "fim";
 if(a.k=="inval"){if(!(N.win===a.by&&a.by!==eu))return "inval";return (euQ==null&&oMinhaValeu())?"inval_falso":""}
 /* o adversario diz que eu abandonei: so aceita se eu de fato fiquei sem gravar a minha marca */
 if(a.k=="aband"){if(!(N.win===a.by&&a.by!==eu))return "aband";return (euQ==null&&Date.now()-(O.hbOk||0)<40000)?"aband_falso":""}
 if((d.pv==null?-1:d.pv)!==(G.seq||0)){if(a.k=="rend"&&N.win===eu)return "";return "base"}
 if(A.win!=null)return "acabou";
 if(a.k=="rend")return (N.win===eu&&a.by===ele)?"":"rend";
 if(a.k=="t"&&A.cur!==ele)return "vez";
 if(a.k=="bot"&&!(bot>=0&&A.cur===bot&&a.by===bot))return "vez";
 if(a.k=="tempo"&&A.cur===eu&&((a.q||[]).length||(a.pre&&Object.keys(a.pre).length)))return "tempo";
 if(!["t","bot","tempo"].includes(a.k))return "tipo";
 /* refaz num canto: nada aparece na tela e o que nao e da partida volta como estava */
 const FN=["render","sfx","zToast","phaseAnn","pannOff","showPredict","vPlay","voxPlay","frFaixa"],F0={};
 FN.forEach(n=>{try{if(typeof window[n]=="function"){F0[n]=window[n];window[n]=()=>{}}}catch(e){}});
 const SK=new Set(Object.keys(JSON.parse(ser()))),G0={};Object.keys(G).forEach(k=>{if(!SK.has(k)&&k!=="u")G0[k]=G[k]});
 let why="";
 /* um video de ultimate tocando aqui (RFZ) segura o fim de turno na tela; o refazer nao pode esperar por ele */
 const rfz0=RFZ;RFZ=0;
 try{des(O.bst);
  const pre=a.pre||{};
  for(const k of Object.keys(pre)){if(k!=="u"){why="pre:"+k;break}}
  if(!why&&pre.u)for(const i of Object.keys(pre.u)){const u=G.u[+i];if(!u){why="pre:u";break}
   for(const k of Object.keys(pre.u[i])){if(!OVPREU[k]){why="pre:u."+k;break}u[k]=pre.u[i][k]}if(why)break}
  /* no refazer, quem joga e o dono do turno (ok() so deixa o jogador mexer nos proprios personagens) */
  if(!why){G.q=[];G.sel=null;G.qo=0;G.kkc={};const lado=A.cur;G.me=lado;
   for(const x of oAcQDes(a.q)){const u=x.u;if(!u||!G.u.includes(u)||u.s!==lado){why="fila:lado";break}
    const os=opts(u),mesmo=(p,q)=>(p||null)===(q||null),ts=v=>(v||[]).map(y=>G.u.indexOf(y)).sort((a,b)=>a-b).join(",");
    const m=os.find(o=>o.i===x.i&&mesmo(o.t,x.t)&&ts(o.ts)===ts(x.ts)&&(o.z||0)===(x.z||0));
    if(!m){why="fila:ilegal "+(u.c||"")+"#"+x.i;break}
    qpush(Object.assign({},x))}}
  if(!why){if(a.k=="t")tZera(A.cur);if(a.k=="tempo")tFalta(A.cur);
   G.scr="p";G.win=null;_endTurn();
   const RP=JSON.parse(ser()),L=oDifere(RP,N);if(L.length){why="resultado:"+L.slice(0,6).join(",");OVAL.dbg={rp:RP,n:N,L}}}}
 catch(e){why="erro:"+String(e&&e.message||e).slice(0,60)}
 finally{Object.keys(G).forEach(k=>{if(!SK.has(k)&&k!=="u"&&!(k in G0))delete G[k]});Object.assign(G,G0);
  try{des(O.bst)}catch(e){}FN.forEach(n=>{if(F0[n])window[n]=F0[n]});RFZ=rfz0}
 return why}
/* ===== Abandono: quem some da partida online por 1 minuto perde =====
   Cada jogador marca na sala que esta presente (hb0/hb1) a cada 15 s. Se a marca do
   adversario para de mudar por 60 s (contados neste aparelho) e este aparelho esta
   conseguindo gravar a sua, a vitoria e de quem ficou. Aos 20 s sem sinal aparece o aviso. */
const ABND={ms:60000,av:20000};
function abHb(){try{if(!G.online||G.scr!="p"||G.win!=null||!(G.me===0||G.me===1)||!O.ref||!O.d||O.d.ph!="battle")return;
 if(O.seat!==G.me)return;const t=Date.now();O.ref.update({["hb"+G.me]:t}).then(()=>{O.hbOk=Date.now()},()=>{})}catch(e){}}
function abVigia(){try{if(!G.online||G.scr!="p"||G.win!=null||!(G.me===0||G.me===1)||!O.d||O.d.ph!="battle"||O.seat!==G.me){O.abG="";return}
 const ele=1-G.me;if(oBotSeat()===ele||O.sending||O.retry)return;
 const k=(G.gid||"")+":"+ele,v=O.d["hb"+ele]||0,agora=Date.now();
 /* a propria marca sai logo no comeco, sem esperar os 15 s */
 if(!O.d["hb"+G.me]&&agora-(O.hbTry||0)>5000){O.hbTry=agora;abHb()}
 if(O.abG!==k){O.abG=k;O.abV=v;O.abT=agora;O.abAv=0;O.abViu=v?1:0;return}
 if(v!==O.abV){O.abV=v;O.abT=agora;O.abViu=1;if(O.abAv){O.abAv=0;try{zToast(pn(ele)+" voltou.")}catch(e){}}return}
 /* so vale para quem ja marcou presenca nesta partida (aparelho com a versao nova) */
 if(!O.abViu&&!v)return;
 const sem=agora-O.abT;
 if(sem>=ABND.av&&!O.abAv){O.abAv=1;try{zToast(pn(ele)+" está sem conexão. Se não voltar em "+Math.ceil((ABND.ms-sem)/1000)+" s, a vitória é sua.")}catch(e){}}
 /* so declara se este aparelho esta online (gravou a propria marca ha pouco) */
 if(sem>=ABND.ms&&agora-(O.hbOk||0)<25000){O.abG="fim";
  oAcMarca("aband",G.me);G.q=[];G.sel=null;G.win=G.me;log(pn(ele)+" abandonou a partida: a vitória é de "+pn(G.me)+".");
  oPush();render();try{zToast(pn(ele)+" abandonou a partida. A vitória é sua.")}catch(e){}}}catch(e){}}
if(typeof setInterval=="function"){setInterval(abHb,15000);setInterval(abVigia,1000)}
/* "a sua jogada foi invalida": confere a propria jogada. Se ela vale, quem acusou mentiu */
function oMinhaValeu(){try{const M=O.meuUlt;if(!M||!M.base||!M.ac)return true;
 const b0=O.bst,s0=G.seq;O.bst=M.base;G.seq=M.pv;
 let why="";try{why=oValida({st:M.st,ac:M.ac,pv:M.pv},1-G.me)}finally{O.bst=b0;G.seq=s0}
 return !why}catch(e){return true}}
/* jogada impossivel: fica o ultimo estado bom, a partida acaba e a vitoria e de quem recebeu */
function oInvalida(d,why){try{des(O.bst);G.seq=Math.max(G.seq||0,d.seq||0);G.q=[];G.sel=null;
 G.win=G.me;log("Jogada inválida de "+pn(1-G.me)+": a partida foi encerrada.");
 OAC={k:"inval",by:G.me,why:String(why).slice(0,80)};oPush();
 try{zToast("O adversário enviou uma jogada que não é possível. A partida foi encerrada e a vitória é sua.")}catch(e){}
 render()}catch(e){}}
/* ===== Bot na sala online (controlado pelo líder da sala) ===== */
const OBOT="BOT";
function oBotSeat(d){d=d||O.d;return!d?-1:d.p0===OBOT?0:d.p1===OBOT?1:-1}
async function oAddBot(){const d=O.d;if(!d||!oIsHost()||O.busy)return;const me=O.pid;let k=!d.p1?"p1":!d.p0?"p0":d.p1!==me?"p1":"p0";const up={};if(d[k]){const f=["s0","s1","s2","s3","s4","s5"].find(x=>!d[x]);if(!f){O.err="A sala está cheia: libere um lugar de espectador para o jogador que vai sair da vaga.";return oRender()}up[f]=d[k]}const lv=blvGet();O.busy=1;try{await O.ref.update({...up,["lr0"]:false,["lr1"]:false,[k]:OBOT,["lr"+k[1]]:true,cd:0,blv:lv,mem:oMemJunta(Object.assign({},d,up,{[k]:OBOT}),OBOT,{n:"Bot 🤖 ("+BLVN[lv]+")"})});oAfterWrite()}catch(e){O.busy=0;O.err="Não foi possível adicionar o bot.";oRender()}}
async function oRemoveBot(){const d=O.d,s=oBotSeat(d);if(!d||!oIsHost()||O.busy||s<0)return;O.busy=1;try{await O.ref.update({["p"+s]:null,["lr"+s]:false,cd:0});oAfterWrite()}catch(e){O.busy=0;oRender()}}
function oBotChoice(R,s){const op=oOpts(R,s);if(!op.length)return null;if(blv()>=3){const c=bChoose(R,s,op,blv());if(c!=null&&(!Array.isArray(c)||c.length))return c}const by=(m,a)=>a.slice().sort((x,y)=>nz(m,y)-nz(m,x));
 switch(R.ph){case"fvote":return op.sort(()=>Math.random()-.5).slice(0,2);
  case"pre":return by(LRV,op).slice(0,npre(R));
  case"lead":return by(LRV,op)[0];
  case"seq":{const st=R.seq[R.si];if(st.t=="ban")return by(DRV,op)[0];const mine=R.picks[s]||[],mc=mine.map(k=>cls(k)[0]),sup=mine.some(k=>cls(k).some(c=>c=="Tanque"||c=="Suporte"));
   return op.map(k=>{let v=nz(DRV,k);if(!mc.includes(cls(k)[0]))v+=1;if(!sup&&cls(k).some(c=>c=="Tanque"||c=="Suporte"))v+=1.5;return[k,v]}).sort((a,b)=>b[1]-a[1])[0][0]}
  case"fban":{const o=1-s,l=R.lead[o];if(l&&(LRV[l]||5)>=8&&Math.random()<.4&&op.includes(l))return l;return by(DRV,(R.picks[o]||[]).filter(k=>op.includes(k)))[0]||op[0]}
  case"newlead":{const v=k=>(LRV[k]||5)-(DRV[k]||5)*.6;return op.slice().sort((a,b)=>v(b)-v(a))[0]}}
 return oRandFor(R,s)}
function oBotTick(){const d=O.d;if(!d||!O.ref||!oIsHost()||O.busy)return;const bs=oBotSeat(d);if(bs<0)return;
 if(d.ph=="lobby"){if(!d["lr"+bs]){O.busy=1;O.ref.update({["lr"+bs]:true}).then(oAfterWrite,()=>{O.busy=0})}return}
 if(d.ph=="battle"){if(G.win!=null&&d["rm"+(1-bs)]&&!d["rm"+bs]){O.busy=1;O.ref.update({["rm"+bs]:true}).then(oAfterWrite,()=>{O.busy=0})}return}
 if(d.ph!="draft"||!d.dr)return;let R;try{R=JSON.parse(d.dr)}catch(e){return}
 const key=(d.did||"")+":"+R.ph+":"+R.si+":"+(d.b0?1:0)+(d.b1?1:0)+":"+(d.rd0?1:0)+(d.rd1?1:0);if(O.bk!==key){O.bk=key;O.bkt=Date.now();return}if(Date.now()-O.bkt<1500)return;
 if(["field","prerev","banrev","fbanrev"].includes(R.ph)){if(R.ph=="field"&&Date.now()<oDL(d)-12000)return;if(d["rd"+(1-bs)]){O.busy=1;return oWriteR(R,oAdvance(R))}if(!d["rd"+bs]){O.busy=1;O.ref.update({["rd"+bs]:true}).then(oAfterWrite,()=>{O.busy=0})}return}
 if(R.ph=="seq"){const st=R.seq[R.si];if(st&&st.s===bs&&st.t!="rev"){const c=oBotChoice(R,bs);if(c!=null)oSeqPick(c)}return}
 if(BLIND.includes(R.ph)&&oNeed(R).includes(bs)&&!d["b"+bs]){const c=oBotChoice(R,bs);if(c!=null)oSubmit(bs,c)}}
function oBotBattle(){if(!G.online||G.scr!="p"||G.win!=null||!O.d||O.d.ph!="battle"||!oIsHost())return;const bs=oBotSeat();if(bs<0||G.cur!==bs||O.botT||O.sending||O.retry||G.inOn||G.g2v)return;if((G.holdT||0)>Date.now())return;
 O.botT=1;setTimeout(()=>{try{if(G.cur!==bs||G.win!=null||G.scr!="p"||(G.holdT||0)>Date.now()){O.botT=0;return}
  G.u.filter(x=>x.c=="bj"&&x.s==bs&&x.alive).forEach(b=>{const o=G.u.filter(x=>x.s==bs&&x.alive&&x!==b).sort((p,q)=>q.hp-p.hp)[0];b.bjp=o&&b.hp<=60&&o.hp>b.hp+20?G.u.indexOf(o):null});
  G.q=[];G.sel=null;{const so=G.online,lv=blv();G.online=0;try{botPlan(bs,lv)}finally{G.online=so}}render();setTimeout(()=>{try{if(G.cur===bs&&G.win==null&&G.scr=="p"){const w=G.win;oAcMarca("bot",bs);_endTurn();oPush()}}catch(e){}O.botT=0},1100)}catch(e){O.botT=0}},G.t>1?BOTWAIT:900)}
if(typeof setInterval=="function")setInterval(()=>{try{oBotTick()}catch(e){}try{oBotBattle()}catch(e){}},500);
