/* O update do banco mescla so campos de primeiro nivel: gravar mem:{eu} trocava
   a tabela inteira e apagava o nick dos outros, que viravam "Jogador". Junta
   com o que ja esta na sala e descarta quem nao ocupa mais nenhuma vaga. */
function oMemJunta(d,id,v){const m={};const velho=(d&&d.mem)||{};
 const vivos=OSL.map(k=>d&&d[k]).filter(Boolean).concat([id]).map(x=>okey(x));
 Object.keys(velho).forEach(k=>{if(vivos.includes(k))m[k]=velho[k]});
 if(v)m[okey(id)]=v;else delete m[okey(id)];return m}
const okey=id=>"m_"+String(id).replace(/[^A-Za-z0-9_-]/g,"_").slice(0,60);
function oNick(){let n=ls("za_nick");if(!n){n="Lutador "+String(O.pid||"").replace(/[^A-Za-z0-9]/g,"").slice(-4).toUpperCase();ls("za_nick",n)}return n}
function oName(d,id){const m=d&&d.mem&&d.mem[okey(id)];return(m&&m.n)||"Jogador"}
/* o que este aparelho publica sobre si na sala: nome e rank da temporada */
function oMeMem(n){const o={n:(n||oNick())};try{o.pf=pfMini()}catch(e){}try{const st=rkLoad();o.rk=st.rank;o.dv=st.div;o.pc=st.pc==null?-1:st.pc}catch(e){}try{o.mx=mxPacote()}catch(e){}return o}
/* medalha do rank ao lado do nick (quem nunca jogou ranqueada e o bot ficam sem) */
function oMed(d,id){const m=d&&d.mem&&d.mem[okey(id)];if(!m||!m.rk)return"";
 const st={rank:+m.rk||1,div:+m.dv||5,pc:(m.pc==null||m.pc<0)?null:+m.pc};
 return"<i class='omed'>"+rkMedalha(st)+"</i>"}
function oIsHost(){const d=O.d;return!!(d&&O.pid&&(d.host?d.host===O.pid:d.p0===O.pid))}
const CFGD={pre:3,nb:"a",fb:1,fd:"r",t:30,ld:1};
function oRules(d){try{return Object.assign({m:"p"},JSON.parse((d&&d.ru)||"{}"))}catch(e){return{m:"p"}}}
function oCfg(d){const r=oRules(d);return r.m=="c"?Object.assign({},CFGD,r,{m:undefined}):Object.assign({},CFGD)}
