/* ===== Draft online ===== */
O.R=null;O.busy=0;O.tick=null;
const BLIND=["fvote","pre","lead","fban","newlead"];
/* ===== Sorteios do servidor =====
   Toda sala ganha do servidor um numero sorteado (sv) a cada volta para o lobby; nenhum jogador consegue mexer nele.
   Dele saem quem joga primeiro (bit 0), quem bane primeiro (bit 1) e o desempate do voto de campo (o resto).
   Sem sv (sala antiga ou jogo sem servidor), o sorteio continua no aparelho. */
const svOk=d=>!!d&&Number.isInteger(d.sv)&&d.sv>=0;
const svCur=d=>d.sv&1,svBf=d=>(d.sv>>>1)&1,svFv=d=>((d.sv>>>2)%1000003)/1000003;
const oTaken=R=>R.ex.concat(R.bans[0],R.bans[1],R.picks[0],R.picks[1]);
const oRand=a=>a[Math.floor(Math.random()*a.length)];
function oOpts(R,s){switch(R.ph){case"fvote":return FDS.map(f=>f.k);case"pre":return ROS.slice();case"seq":return ROS.filter(k=>!oTaken(R).includes(k));case"lead":return R.pl.slice();
 case"fban":{const o=1-s;return R.picks[o].concat(R.lead[o]?[R.lead[o]]:[])}case"newlead":return R.picks[s].slice();default:return[]}}
const npre=R=>(R.cfg&&R.cfg.pre)||3,npk=R=>R.cfg?3+(R.cfg.fb?1:0):4,TT=R=>((R.cfg&&R.cfg.t)||30)*1000;
function oRandFor(R,s){const o=oOpts(R,s).sort(()=>Math.random()-.5);return R.ph=="pre"?o.slice(0,npre(R)):R.ph=="fvote"?o.slice(0,2):o[0]}
function oNeed(R){return R.ph=="newlead"?R.nl.slice():[0,1]}
function oToSeq(R){const bf=R.bf,fp=1-bf;R.seq=[];for(let i=0;i<R.nb;i++)R.seq.push({t:"ban",s:bf},{t:"ban",s:1-bf});if(R.nb)R.seq.push({t:"rev",s:0});{const P=npk(R),c=[0,0];let who=fp;while(c[0]<P||c[1]<P){for(let k=0;k<2&&c[who]<P;k++){R.seq.push({t:"pick",s:who});c[who]++}who=1-who}}R.si=0;R.ph="seq";oSkip(R)}
function oSkip(R){while(R.ph=="seq"&&R.si<R.seq.length&&R.seq[R.si].t!="rev"&&!oOpts(R,R.seq[R.si].s).length)R.si++;if(R.ph=="seq"&&R.si>=R.seq.length){if(R.cfg&&!R.cfg.fb){R.fb=[null,null];oFinal(R)}else R.ph="fban"}if(R.ph=="seq"&&R.seq[R.si]&&R.seq[R.si].t=="rev")R.ph="banrev"}
function oFinal(R){R.ann=R.lead[0]&&R.lead[0]===R.lead[1]?1:0;R.act=[0,1].map(t=>R.picks[t].filter(k=>k!==R.fb[1-t]&&k!==R.lead[t]));R.ph="done"}
function oNb(R){const mx=Math.max(0,Math.floor((R.av-2*npk(R))/2));R.nb=R.cfg&&R.cfg.nb!=="a"&&R.cfg.nb!=null?Math.min(+R.cfg.nb,mx):Math.min(2,mx)}
function oResolve(R,b){const v=b.map(x=>x?JSON.parse(x):null);
 if(R.ph=="fvote"){R.fv=[v[0]||[],v[1]||[]];R.fd=fvPick(R.fv,svOk(O.d)?svFv(O.d):null);R.ph="field";return 26000}
 if(R.ph=="pre"){R.pre=[v[0],v[1]];const a=R.pre[0],c=R.pre[1];R.dup=a.filter(k=>c.includes(k));R.ex=[...new Set(a.concat(c))];R.pl=R.ex.filter(k=>!R.dup.includes(k));
  R.av=ROS.filter(k=>!R.ex.includes(k)).length;oNb(R);R.noLead=R.pl.length?0:1;R.ph="prerev";return 25000}
 if(R.ph=="lead"){R.lead=[v[0],v[1]];oToSeq(R);return TT(R)}
 if(R.ph=="fban"){R.fb=[v[0],v[1]];R.nl=[];[0,1].forEach(t=>{const x=R.fb[1-t];if(x&&x===R.lead[t]){R.lban[t]=x;R.lead[t]=null;R.nl.push(t)}});R.ph="fbanrev";return 10000}
 if(R.ph=="newlead"){R.nl.forEach(t=>{R.lead[t]=v[t]});R.nl=[];oFinal(R);return TT(R)}}
function oDL(d){const k=(d.did||"")+":"+(d.dseq||0);if(O.dlk!==k){O.dlk=k;O.dlv=Date.now()+(d.dms!=null?d.dms:Math.max(0,Math.min(60000,(d.dl||0)-Date.now())))}return O.dlv}
async function oWriteR(R,ms,extra){const d=O.d;O.busy=1;O.drMine=JSON.stringify(R);try{await O.ref.update(Object.assign({dr:O.drMine,b0:"",b1:"",rd0:false,rd1:false,dl:Date.now()+ms,dms:ms,dseq:(d.dseq||0)+1},extra||{}));oAfterWrite()}catch(e){O.busy=0;O.err="Não foi possível salvar a escolha ("+(e&&e.code||"erro")+").";dRender()}}
async function oSubmit(s,val){const d=O.d;if(!d||O.busy)return;const R=JSON.parse(d.dr),b=[d.b0||"",d.b1||""];b[s]=JSON.stringify(val);if(s===O.seat)O.myB={did:d.did,ph:R.ph,dseq:d.dseq||0,v:b[s]};
 if(oNeed(R).every(t=>b[t])){const ms=oResolve(R,b);return oWriteR(R,ms)}
 O.busy=1;try{await O.ref.update({["b"+s]:b[s]});oAfterWrite()}catch(e){O.busy=0;O.err="Não foi possível enviar ("+(e&&e.code||"erro")+").";dRender()}}
function oAdvance(R){if(R.ph=="banrev"){R.ph="seq";R.si++;oSkip(R)}else if(R.ph=="fbanrev"){if(R.nl.length)R.ph="newlead";else oFinal(R)}else if(R.ph=="field"){if(R.cfg&&!R.cfg.ld)oNoLead(R);else R.ph="pre"}else if(R.ph=="prerev"){if(R.noLead)oToSeq(R);else R.ph="lead"}return TT(R)}
function oNoLead(R){R.ex=[];R.pl=[];R.dup=[];R.pre=[[],[]];R.av=ROS.length;oNb(R);R.noLead=1;oToSeq(R)}
async function oReadyStep(){const d=O.d;if(!d||O.busy||O.seat==null)return;const me=O.seat,R=JSON.parse(d.dr);if(!["field","prerev","banrev","fbanrev"].includes(R.ph))return;
 if(d["rd"+(1-me)]){const ms=oAdvance(R);return oWriteR(R,ms)}O.busy=1;try{await O.ref.update({["rd"+me]:true});oAfterWrite()}catch(e){O.busy=0}}
async function oSeqPick(k){const d=O.d;if(!d||O.busy)return;const R=JSON.parse(d.dr);if(R.ph!="seq")return;const st=R.seq[R.si];if(k===null?st.t!="ban":!oOpts(R,st.s).includes(k))return;
 (st.t=="ban"?R.bans:R.picks)[st.s].push(k);R.si++;oSkip(R);return oWriteR(R,R.ph=="banrev"?10000:TT(R))}
function oConfirm(){if(!D||!D.on||D.spec||O.busy||O.seat==null)return;const me=O.seat,ph=D.ph;if(ph=="pre"||ph=="fvote"){if(D.sel.length==need())oSubmit(me,D.sel.slice())}
 else if(ph=="seq"){if(D.who===me&&D.sel[0])oSeqPick(D.sel[0])}else if(BLIND.includes(ph)&&D.sel[0])oSubmit(me,D.sel[0])}
