/* ===== Conferencia do draft online =====
   Cada mudanca do draft gravada pelo outro aparelho e refeita aqui: o comeco, os avancos automaticos,
   cada ban e pick da sequencia e as escolhas cegas (voto de campo, pre-selecao, lider e ban final).
   As escolhas de cada jogador precisam ser permitidas naquele momento, e o resultado precisa bater. */
function oDrCegas(P,N){switch(P.ph){case"fvote":return[N.fv&&N.fv[0],N.fv&&N.fv[1]];case"pre":return[N.pre&&N.pre[0],N.pre&&N.pre[1]];
 case"lead":return[N.lead[0],N.lead[1]];case"fban":return[N.fb[0],N.fb[1]];case"newlead":return[0,1].map(t=>P.nl.includes(t)?N.lead[t]:null);default:return null}}
function oDrLegal(P,b){const need=oNeed(P);return need.every(t=>{const v=b[t],op=oOpts(P,t);
 if(P.ph=="fvote")return Array.isArray(v)&&v.length<=2&&new Set(v).size===v.length&&v.every(k=>op.includes(k));
 if(P.ph=="pre")return Array.isArray(v)&&v.length<=npre(P)&&new Set(v).size===v.length&&v.every(k=>op.includes(k));
 if(v==null)return !op.length||P.ph=="fban";return op.includes(v)})}
function oDrValida(P,N,d){const J=x=>JSON.stringify(x),cp=x=>JSON.parse(J(x)),alvo=J(N);
 try{
  if(["field","prerev","banrev","fbanrev"].includes(P.ph)){const R=cp(P);oAdvance(R);if(J(R)===alvo)return""}
  if(P.ph=="seq"&&P.seq[P.si]){const st=P.seq[P.si],key=st.t=="ban"?"bans":"picks",a=P[key][st.s],b=N[key]&&N[key][st.s];
   if(Array.isArray(b)&&b.length===a.length+1&&J(b.slice(0,a.length))===J(a)){const k=b[b.length-1];
    if(k===null?st.t=="ban":oOpts(P,st.s).includes(k)){const R=cp(P);R[key][st.s].push(k);R.si++;oSkip(R);if(J(R)===alvo)return""}}}
  if(BLIND.includes(P.ph)){const b=oDrCegas(P,N),me=O.seat,M=O.myB;
   /* a minha propria escolha tem de aparecer do jeito que eu mandei */
   if(b&&M&&M.did===d.did&&M.ph===P.ph&&M.dseq===V0dseq(d)&&oNeed(P).includes(me)&&J(b[me]==null?null:b[me])!==J(JSON.parse(M.v||"null")))return "draft:"+P.ph+":minha escolha";
   if(b&&oDrLegal(P,b)){const R=cp(P),d0=O.d;O.d=d;try{oResolve(R,b.map(x=>x==null?"":J(x)))}finally{O.d=d0}
    /* sem sorteio do servidor, o campo do voto foi sorteado no outro aparelho: so precisa ser um campo valido */
    if(P.ph=="fvote"&&!svOk(d)&&FDS.some(f=>f.k===N.fd))R.fd=N.fd;
    if(J(R)===alvo)return""}}
 }catch(e){return""}/* se a conferencia nao conseguir rodar, nao acusa ninguem */
 return "draft:"+P.ph}
/* conferencia do draft inteiro, para quando nao da para refazer passo a passo:
   bans e picks so crescem, ninguem repete personagem, nada banido ou da pre-selecao e escolhido,
   e o que ja estava escolhido continua igual */
function oDrEstrutura(V,N){try{const J=x=>JSON.stringify(x),A=x=>Array.isArray(x)?x:null;
  const bans=[0,1].map(t=>A(N.bans&&N.bans[t])),picks=[0,1].map(t=>A(N.picks&&N.picks[t]));
  if(bans.some(x=>!x)||picks.some(x=>!x))return "draft:estrutura";
  const ex=A(N.ex)||[],vistos=new Set();
  for(const k of [].concat(bans[0],bans[1],picks[0],picks[1])){if(k==null)continue;if(typeof k!="string"||vistos.has(k)||ex.includes(k))return "draft:estrutura";vistos.add(k)}
  if(N.cfg){const P=npk(N);if(picks.some(x=>x.length>P))return "draft:estrutura"}
  if(V){if(J(V.cfg)!==J(N.cfg)||V.bf!==N.bf)return "draft:estrutura";
   for(const key of ["bans","picks"])for(const t of [0,1]){const a=(V[key]&&V[key][t])||[],c=N[key][t];if(c.length<a.length||J(c.slice(0,a.length))!==J(a))return "draft:estrutura"}}
  if(N.ph=="done"&&Array.isArray(N.act)&&Array.isArray(N.fb)&&Array.isArray(N.lead))
   for(const t of [0,1]){const certo=picks[t].filter(k=>k!==N.fb[1-t]&&k!==N.lead[t]);if(J(N.act[t])!==J(certo))return "draft:estrutura"}
  return ""}catch(e){return ""}}
