function oIniValida(d){let N;try{N=JSON.parse(d.st)}catch(e){return "estado"}
 if(!d.dr)return "";
 /* so o comeco mesmo: quem volta para uma partida ja andada (recarregou a pagina) recebe o estado do meio dela */
 if((N.t||0)>1||(N.log||[]).some(l=>/ usa | → /.test(l.m||"")))return "";let R;try{R=JSON.parse(d.dr)}catch(e){return "draft"}if(R.ph!="done")return "draft";
 const FN=["render","sfx","zToast","phaseAnn","pannOff","showPredict","vPlay","voxPlay","voxPre","vPre","frFaixa","lbSalvaTime"],F0={};
 FN.forEach(n=>{try{if(typeof window[n]=="function"){F0[n]=window[n];window[n]=()=>{}}}catch(e){}});
 const SK=new Set(Object.keys(N)),G0={};Object.keys(G).forEach(k=>{if(!SK.has(k)&&k!=="u")G0[k]=G[k]});
 const rnd=Math.random,rfz0=RFZ;let why="";
 try{RFZ=0;if(!svOk(d))Math.random=()=>N.cur===1?.75:.25;oIniMonta(d,N.gid);Math.random=rnd;
  /* a marca "f" dos efeitos que ja nascem na batalha depende da vez da partida anterior em cada aparelho: fica de fora */
  const semF=X=>{(X.u||[]).forEach(u=>{(u.st||[]).forEach(y=>{delete y.f})});return X};
  const RP=semF(JSON.parse(ser())),L=oDifere(RP,semF(JSON.parse(d.st)));if(L.length){why="inicio:"+L.slice(0,6).join(",");OVAL.dbg={rp:RP,n:N,L}}}
 catch(e){why="";/* se nao der para montar aqui, nao acusa ninguem */}
 finally{Math.random=rnd;Object.keys(G).forEach(k=>{if(!SK.has(k)&&k!=="u"&&!(k in G0))delete G[k]});Object.assign(G,G0);
  FN.forEach(n=>{if(F0[n])window[n]=F0[n]});RFZ=rfz0}
 return why}
