function termosAceita(){const t={v:TERMOS.versao,at:Date.now(),srv:0};try{ls("za_termos",JSON.stringify(t))}catch(e){}termosSobe()}
/* manda o aceite para o servidor (no site). Se ainda nao der, vai na proxima conexao */
async function termosSobe(){try{if(!rkDb())return;const t=termosLer();if(!t||t.v!==TERMOS.versao||t.srv)return;
 await O.db.rpc("termos_aceitar",{p_versao:TERMOS.versao});t.srv=1;ls("za_termos",JSON.stringify(t))}catch(e){}}
/* aceitou em outro aparelho: o servidor sabe, a tela nao precisa aparecer */
async function termosLe(){try{if(!rkDb())return;const r=await O.db.rpc("termos_meu",{});const L=(r&&Array.isArray(r.versoes))?r.versoes:[];
 if(L.indexOf(TERMOS.versao)>=0){if(!termosOk())ls("za_termos",JSON.stringify({v:TERMOS.versao,at:Date.now(),srv:1}));
  const t=termosLer();if(t&&!t.srv){t.srv=1;ls("za_termos",JSON.stringify(t))}
  const o=document.getElementById("tmov");if(o){o.remove();const f=TMCB.splice(0);f.forEach(g=>{try{g()}catch(e){}});try{bnNext()}catch(e){}}}
 else await termosSobe()}catch(e){}}
/* o servidor recusou por falta do aceite da versao atual */
function termosErro(e){return /termos/.test(String(e&&(e.message||e.msg||e.hint||e.code)||e||""))}
function termosRecusa(){try{const t=termosLer();
 if(t&&t.v===TERMOS.versao){if(t.srv){t.srv=0;ls("za_termos",JSON.stringify(t))}termosSobe();
  try{zToast("Confirmando o seu aceite dos Termos de Uso. Se continuar aparecendo, atualize a página.")}catch(e){}return}
 ls("za_termos","");termosShow()}catch(e){}}
/* nenhum modo abre sem o aceite */
["mmVs","startDraft","showLobby","showOnline","showTut","rkEntraFila","csEntra","oJoin","oCreate"].forEach(n=>{try{const f=window[n];if(typeof f!="function")return;
 window[n]=function(){if(!termosOk()){termosShow();return}return f.apply(this,arguments)}}catch(e){}});
{const f=window.oVolta;if(typeof f=="function")window.oVolta=function(){if(!termosOk())return;return f.apply(this,arguments)}}


